const EXPECTED={"schema":"qualified-sichos-301308/v1","route":"/reader/reviewed/sichos-301-308/","title":"Sichos HaRan — teachings 301–308","notice":"The supplied Hebrew texts are preserved independently. The current English follows the supplied Hebrew. Earlier English remains available as textual history.","scope":"Teachings 301–308; 63 original paragraphs and 63 current English translations, with both supplied Hebrew witnesses, source notes and earlier English preserved.","globalQualifications":[{"id":"author301-global-independent-hebrew","placement":"before-owned-body","role":"global-reader-limitation","text":"The unpointed and pointed Hebrew are preserved as independent supplied texts. The English follows the unpointed Hebrew; source notes describe relevant uncertainties. Neither Hebrew text has been silently altered to agree with the other."},{"id":"author301-global-editorial-origin","placement":"before-owned-body","role":"global-reader-limitation","text":"The current English follows the supplied Hebrew. Earlier English is preserved separately as textual history, not as a second current translation."},{"id":"author301-global-citation-limits","placement":"before-owned-body","role":"global-reader-limitation","text":"References retain the detail supplied by the Hebrew, including chapter-only references, combined quotations and abbreviations. Retaining these references does not mean that they have been independently verified or that a reference attached to a combined quotation identifies each part. Additional explanations, identifications and more detailed references in the earlier English remain historical material and have not been independently verified here."},{"id":"author301-global-supplied-source-limits","placement":"before-owned-body","role":"global-reader-limitation","text":"These texts have not been verified against an original printed edition. Preserving the supplied spelling and vowel marks does not certify their accuracy."}],"groups":[{"id":"sichos301","section":301,"title":"Teaching 301","canonical_url":"/reader/sichos-haran/1/301","unit_ids":["sichos-301-position-0"]},{"id":"sichos302","section":302,"title":"Teaching 302","canonical_url":"/reader/sichos-haran/1/302","unit_ids":["sichos-302-position-0"]},{"id":"sichos303","section":303,"title":"Teaching 303","canonical_url":"/reader/sichos-haran/1/303","unit_ids":["sichos-303-position-0","sichos-303-position-1","sichos-303-position-2","sichos-303-position-3"]},{"id":"sichos304","section":304,"title":"Teaching 304","canonical_url":"/reader/sichos-haran/1/304","unit_ids":["sichos-304-position-0","sichos-304-position-1","sichos-304-position-2","sichos-304-position-3"]},{"id":"sichos305","section":305,"title":"Teaching 305","canonical_url":"/reader/sichos-haran/1/305","unit_ids":["sichos-305-position-0","sichos-305-position-1","sichos-305-position-2"]},{"id":"sichos306","section":306,"title":"Teaching 306","canonical_url":"/reader/sichos-haran/1/306","unit_ids":["sichos-306-position-0","sichos-306-position-1","sichos-306-position-2","sichos-306-position-3","sichos-306-position-4","sichos-306-position-5"]},{"id":"sichos307","section":307,"title":"Teaching 307","canonical_url":"/reader/sichos-haran/1/307","unit_ids":["sichos-307-position-0","sichos-307-position-1","sichos-307-position-2"]},{"id":"sichos308","section":308,"title":"Teaching 308","canonical_url":"/reader/sichos-haran/1/308","unit_ids":["sichos-308-position-0","sichos-308-position-1","sichos-308-position-2","sichos-308-position-3","sichos-308-position-4","sichos-308-position-5","sichos-308-position-6","sichos-308-position-7","sichos-308-position-8","sichos-308-position-9","sichos-308-position-10","sichos-308-position-11","sichos-308-position-12","sichos-308-position-13","sichos-308-position-14","sichos-308-position-15","sichos-308-position-16","sichos-308-position-17","sichos-308-position-18","sichos-308-position-19","sichos-308-position-20","sichos-308-position-21","sichos-308-position-22","sichos-308-position-23","sichos-308-position-24","sichos-308-position-25","sichos-308-position-26","sichos-308-position-27","sichos-308-position-28","sichos-308-position-29","sichos-308-position-30","sichos-308-position-31","sichos-308-position-32","sichos-308-position-33","sichos-308-position-34","sichos-308-position-35","sichos-308-position-36","sichos-308-position-37","sichos-308-position-38","sichos-308-position-39","sichos-308-position-40"]}],"units":[{"owner":"sichos-301-position-0","section":301,"source_index":1,"array_position":0,"event_position":0,"group":"sichos301","anchor":"sichos-301-position-0","he":"שמעתי בשמו שאמר: שעקר עבודת איש הישראלי הוא בחרף, לקום בחצות לילה. ובקיץ בעת שהלילה קצר מאד (שאז אין עומדין בחצות (בחוץ לארץ, כמבאר במקום אחר) אז יזהר לעמד בבקר השכם כעלות השחר.","he_nikud":"שָׁמַעְתִּי בִּשְׁמוֹ שֶׁאָמַר: שֶׁעִקָּר עֲבוֹדַת אִישׁ הַיִּשְׂרְאֵלִי הוּא בַּחֹרֶף, לָקוּם בַּחֲצוֹת לַיְלָה. וּבַקַּיִץ בְּעֵת שֶׁהַלַּיְלָה קָצָר מְאֹד (שֶׁאָז אֵין עוֹמְדִין בַּחֲצוֹת (בְּחוּץ לָאָרֶץ, כַּמְבֹאָר בְּמָקוֹם אַחֵר) אָז יִזָּהֵר לַעֲמֹד בַּבֹּקֶר הַשְׁכֵּם כַּעֲלוֹת הַשַּׁחַר.","en":"I heard in the Rebbe’s name that he said: A Jewish man’s main devotion in the winter is to wake up at midnight. And in the summer, when the night is very short (when one does not rise at midnight (in the Diaspora, as explained elsewhere), one should be careful to wake up early in the morning, at dawn.","field_sha256":{"he":"aae221ffe449d19f34fe37571637571ac1bf0de95ed965fed62639bd3cb125a0","he_nikud":"46b4f105505791ed1eeb42ec4747590b15a31c6ddfcd099d8660ea03bef2a55b","en":"54f1278e68c6a16a4417c0253ee8b75774a89905eca04346fc68a3e05c7a93e1"},"history":{"earlier_supplied_English":"I heard in the Rebbe’s name: A Jew’s main devotion in the winter is to wake up at midnight [and say Tikkun Chatzot , the midnight service (cf. Magen Avraham 1:4) ]. In the summer, when the nights are very short [and so awakening at midnight is not practiced in the Diaspora 370 See Likutey Moharan I, 149; Likutey Halakhot , Rosh HaShanah 3:7; She'arit Yisrael 125. ], one should still be careful to wake up early, at the crack of dawn.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-301-original.json","original_owner_pointer":"/segments/0"},"qualifications":[{"id":"author301-origin-sichos-301-position-0","owner":"sichos-301-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-301-position-0","owner":"sichos-301-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"Both supplied Hebrew fields have nested opening parentheses without a matching outer close; the English keeps that punctuation. “As explained elsewhere” has no more precise reference in this paragraph."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-301-position-0","englishUTF8SHA256":"54f1278e68c6a16a4417c0253ee8b75774a89905eca04346fc68a3e05c7a93e1"}},{"owner":"sichos-302-position-0","section":302,"source_index":1,"array_position":0,"event_position":1,"group":"sichos302","anchor":"sichos-302-position-0","he":"פעם אחת עמדתי לפניו והוא ז\"ל היה מנח על מטתו ונזרקו דבורים אלו מתוך פיו הקדוש ואמר בזו הלשון: העקר הוא: מבטן שאול שועתי (דער עקר איז \"מבטן שאול שועתי\").","he_nikud":"פַּעַם אַחַת עָמַדְתִּי לְפָנָיו וְהוּא ז\"ל הָיָה מֻנָּח עַל מִטָּתוֹ וְנִזְרְקוּ דִּבּוּרִים אֵלּוּ מִתּוֹךְ פִּיו הַקָּדוֹשׁ וְאָמַר בְּזוֹ הַלָּשׁוֹן: הָעִקָּר הוּא: מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי (דֶּער עִקָּר אִיז \"מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי\").","en":"I was once standing before the Rebbe as he, of blessed memory, lay in his bed. These words flew out of his holy mouth, and he said in these words: The crucial thing is: “From the belly of Sheol I cried out” (in Yiddish: “The crucial thing is: ‘From the belly of Sheol I cried out’”).","field_sha256":{"he":"f17b32ab91f6a6ad96f7c9620b823952b84ef92086cc2ab684de1905b051b4d2","he_nikud":"0d766dc3522474f88caec0a3d588c551851133d589f0a0f4f4782d7946a9249d","en":"b983df4537fb7c0004fc8dd562e5581c0cda65043d42289999003e07fd966d3a"},"history":{"earlier_supplied_English":"I was once standing before the Rebbe as he lay in his bed. These words flew out of his holy mouth: “ Der iker is: Mi-beten sheol shivati! – The crucial thing is: 'From the belly of hell I cried out!'” (Jonah 2:3; Alim LeTerufah #60) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-302-original.json","original_owner_pointer":"/segments/0"},"qualifications":[{"id":"author301-origin-sichos-302-position-0","owner":"sichos-302-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-302-position-0","owner":"sichos-302-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"Sheol names the biblical realm of the dead; “hell” is not used here as its exclusive equivalent. The source repeats the statement in Yiddish. Additional references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-302-position-0","englishUTF8SHA256":"b983df4537fb7c0004fc8dd562e5581c0cda65043d42289999003e07fd966d3a"}},{"owner":"sichos-303-position-0","section":303,"source_index":1,"array_position":0,"event_position":2,"group":"sichos303","anchor":"sichos-303-position-0","he":"פעם אחת דבר עמי מענין מאוס תאוה הידוע.","he_nikud":"פַּעַם אַחַת דִּבֵּר עִמִּי מֵעִנְיַן מִאוּס תַּאֲוָה הַיָּדוּעַ.","en":"The Rebbe once spoke to me about the baseness of the well-known desire.","field_sha256":{"he":"26069b9899b436db91d7b115b444d6af1bc6b5f9c29618142d69bdb8c76d587a","he_nikud":"7ef1f32100fa4516738ed2dabf56560866fc94e9025e823605999fcf326dd9b3","en":"45a586b823849a75b29f3bf80776ec40a4ab2642f04559a43a4ce3ea9e54e7b9"},"history":{"earlier_supplied_English":"The Rebbe once spoke to me about the folly of sexual desires.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-303-original.json","original_owner_pointer":"/segments/0"},"qualifications":[{"id":"author301-origin-sichos-303-position-0","owner":"sichos-303-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-303-position-0","owner":"sichos-303-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew uses “the well-known desire”; the next paragraph discusses sexual misconduct. This paragraph retains the euphemism. An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-303-position-0","englishUTF8SHA256":"45a586b823849a75b29f3bf80776ec40a4ab2642f04559a43a4ce3ea9e54e7b9"}},{"owner":"sichos-303-position-1","section":303,"source_index":2,"array_position":1,"event_position":3,"group":"sichos303","anchor":"sichos-303-position-1","he":"ואמר אז: מי שמהרהר בהרהורי נאוף הוא שוטה. כי הלא אפלו איש פשוט שקורין 'בעל הבית' הוא גם כן אינו חפץ שיהיה נתפס ח\"ו בענין זה. אפלו אם אינו ירא חטא כלל על כל פנים בודאי אינו רוצה שיהיה לו בזיון בזה שיתפסו אותו עם אשה אחרת.","he_nikud":"וְאָמַר אָז: מִי שֶׁמְּהַרְהֵר בְּהִרְהוּרֵי נִאוּף הוּא שׁוֹטֶה. כִּי הֲלֹא אֲפִלּוּ אִישׁ פָּשׁוּט שֶׁקּוֹרִין 'בַּעַל הַבַּיִת' הוּא גַּם כֵּן אֵינוֹ חָפֵץ שֶׁיִּהְיֶה נִתְפָּס ח\"ו בְּעִנְיָן זֶה. אֲפִלּוּ אִם אֵינוֹ יְרֵא חֵטְא כְּלָל עַל כָּל פָּנִים בְּוַדַּאי אֵינוֹ רוֹצֶה שֶׁיִּהְיֶה לוֹ בִּזָּיוֹן בָּזֶה שֶׁיִּתְפְּסוּ אוֹתוֹ עִם אִשָּׁה אַחֶרֶת.","en":"And he said then, “One who occupies himself with lewd thoughts is a fool. For surely even an ordinary person, called a ‘householder,’ would also not want to be caught, Heaven forbid, in this matter. Even if he has no fear of sin at all, at any rate, he certainly does not want the shame of being caught with another woman.","field_sha256":{"he":"afe38cd9a10625a5ec0618b9f6b68ce14c532393a636047359ea7aeb05e12a8d","he_nikud":"ab3aad95ae160cb03bd9dcfbd4d04fd6c60a0d0cd7913d42dd7f389c8ff19db9","en":"81213b9193e27bfe806ae6fa09435fe33cf1bd3ca1d45f007790445b6b8167ca"},"history":{"earlier_supplied_English":"He said, “One who occupies himself with lewd thoughts is a fool. Even the most ordinary person would not want to be caught doing this. Even if he has no fear of sin, he still has no desire for the shame of being caught with another woman.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-303-original.json","original_owner_pointer":"/segments/1"},"qualifications":[{"id":"author301-origin-sichos-303-position-1","owner":"sichos-303-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-303-position-1","owner":"sichos-303-position-1","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The English quotation continues across paragraphs. The supplied Hebrew here has no matching opening quotation mark; the English does not establish the original printed punctuation. An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-303-position-1","englishUTF8SHA256":"81213b9193e27bfe806ae6fa09435fe33cf1bd3ca1d45f007790445b6b8167ca"}},{"owner":"sichos-303-position-2","section":303,"source_index":3,"array_position":2,"event_position":4,"group":"sichos303","anchor":"sichos-303-position-2","he":"ואם כן למה לו להרהר ולצער נפשו בחנם?!","he_nikud":"וְאִם כֵּן לָמָּה לוֹ לְהַרְהֵר וּלְצַעֵר נַפְשׁוֹ בְּחִנָּם?!","en":"“So why engage in lustful thoughts? Why trouble your soul for nothing?”","field_sha256":{"he":"78115e55927b4c616d8a937a5a9c7974ee9f677e4036a1fb7865a16656e8d1ba","he_nikud":"177aa6cdf01d5901a3ebb1c516e15dcd2a0e771c024d54014cc468a109373489","en":"568d74d69aa4c008fb55e95d27750354e8bfa7ce7cfd84ecdfd279db8180b831"},"history":{"earlier_supplied_English":"“So why engage in lustful thoughts? Why trouble your soul for nothing?”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-303-original.json","original_owner_pointer":"/segments/2"},"qualifications":[{"id":"author301-origin-sichos-303-position-2","owner":"sichos-303-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"The earlier English is retained verbatim."},{"id":"author301-source-note-1-sichos-303-position-2","owner":"sichos-303-position-2","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-303-position-2","englishUTF8SHA256":"568d74d69aa4c008fb55e95d27750354e8bfa7ce7cfd84ecdfd279db8180b831"}},{"owner":"sichos-303-position-3","section":303,"source_index":4,"array_position":3,"event_position":5,"group":"sichos303","anchor":"sichos-303-position-3","he":"(וכבר מבאר שהמחשבה ביד האדם להטותה כרצונו וכו'. עין בספרים הנדפסים בכמה מקומות מזה ויערב לך לעד אם תרצה לקבלם באמת).","he_nikud":"(וּכְבָר מְבֹאָר שֶׁהַמַּחֲשָׁבָה בְּיַד הָאָדָם לְהַטּוֹתָה כִּרְצוֹנוֹ וְכוּ'. עַיֵּן בַּסְּפָרִים הַנִּדְפָּסִים בְּכַמָּה מְקוֹמוֹת מִזֶּה וְיֶעֱרַב לְךָ לָעַד אִם תִּרְצֶה לְקַבְּלָם בֶּאֱמֶת).","en":"(And it has already been explained that every person can control his thoughts and direct them as he wishes, etc. See the printed works in several places about this, and it will be pleasant for you forever if you are willing to accept them truly.)","field_sha256":{"he":"b170fbd6d37f9af064c2230274b22e51e54943dfb9c2b04a4da14e93b6bdcade","he_nikud":"c0656f5c1f81ef1b91fd70db13486236f8c311cd975152ece6e719657f898db4","en":"1eafadb4ccb34c85406516dfde86d9e1874f4d5371da08b2781b8d9d9244a5fd"},"history":{"earlier_supplied_English":"We have spoken of the fact that every person can control his thoughts and direct them as he wishes. This is discussed in numerous places in our printed works. 371 Likutey Moharan II, 50; Tzaddik #170; Likutey Halakhot , Bet HaKnesset 5:24; ibid., Minchah 7:10; ibid., Shiluach HaKen 4:2; Alim LeTerufah #6, #15, #117, #260, #295. Accept this advice and you will be worthy of eternal pleasure.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-303-original.json","original_owner_pointer":"/segments/3"},"qualifications":[{"id":"author301-origin-sichos-303-position-3","owner":"sichos-303-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-303-position-3","owner":"sichos-303-position-3","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew. Additional explanations and references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-303-position-3","englishUTF8SHA256":"1eafadb4ccb34c85406516dfde86d9e1874f4d5371da08b2781b8d9d9244a5fd"}},{"owner":"sichos-304-position-0","section":304,"source_index":1,"array_position":0,"event_position":6,"group":"sichos304","anchor":"sichos-304-position-0","he":"פעם אחת התלוצץ מזה ואמר שעל זה מבקשים בכל יום \"ואל תביאני לידי נסיון ולא לידי בזיון\". ואמר בזו הלשון: אדער אה נסיון אדער אה בזיון (או נסיון, או בזיון). הינו כי אם לא יעמד בנסיון, יהיה לו בזיון.","he_nikud":"פַּעַם אַחַת הִתְלוֹצֵץ מִזֶּה וְאָמַר שֶׁעַל זֶה מְבַקְּשִׁים בְּכָל יוֹם \"וְאַל תְּבִיאֵנִי לִידֵי נִסָּיוֹן וְלֹא לִידֵי בִּזָּיוֹן\". וְאָמַר בְּזוֹ הַלָּשׁוֹן: אָדֶער אַה נִסָּיוֹן אָדֶער אַה בִּזָּיוֹן (אוֹ נִסָּיוֹן, אוֹ בִּזָּיוֹן). הַיְנוּ כִּי אִם לֹא יַעֲמֹד בַּנִּסָּיוֹן, יִהְיֶה לוֹ בִּזָּיוֹן.","en":"Once the Rebbe ridiculed this and said that concerning this one prays every day, “And do not bring me to a test, nor to disgrace.” And he said in these words, in Yiddish: “Either a test, or else disgrace” (either a test, or disgrace). That is, for if one does not pass the test, one will come to disgrace.","field_sha256":{"he":"4d4d7154aef511dd0552231fc6fd2fbd83c9a0e602ff58c8627e3063b7289669","he_nikud":"7033de4c6cefeb781319b45fba9e04b57420b6194d7923da78659c4f47dce3ee","en":"23a272ba0e4dd1666b87a204413bc0f28d8bfe8b0ab7ac7fb019e5ce352ef5e6"},"history":{"earlier_supplied_English":"The Rebbe ridiculed the sexual desire, quoting the words of the morning prayer, “Do not bring me to a test or to disgrace.” He said, “ Ader a nisayon, ader a beziyon – Either a test, or else disgrace.” That is, if you do not pass the test, you will come to disgrace.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-304-original.json","original_owner_pointer":"/segments/0"},"qualifications":[{"id":"author301-origin-sichos-304-position-0","owner":"sichos-304-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-304-position-0","owner":"sichos-304-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew states the teaching, repeats it in Yiddish, and adds a parenthetical equivalent. The English preserves those repetitions. Additional references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-304-position-0","englishUTF8SHA256":"23a272ba0e4dd1666b87a204413bc0f28d8bfe8b0ab7ac7fb019e5ce352ef5e6"}},{"owner":"sichos-304-position-1","section":304,"source_index":2,"array_position":1,"event_position":7,"group":"sichos304","anchor":"sichos-304-position-1","he":"וכבר מבאר קצת שספר הרבה מענין מאוס תאוה זאת ואמר שאינה תאוה כלל וכו'.","he_nikud":"וּכְבָר מְבֹאָר קְצָת שֶׁסִּפֵּר הַרְבֵּה מֵעִנְיַן מִאוּס תַּאֲוָה זֹאת וְאָמַר שֶׁאֵינָהּ תַּאֲוָה כְּלָל וְכוּ'.","en":"And it has already been partly explained that the Rebbe spoke much about the baseness of this desire, saying that it is really no desire at all, etc.","field_sha256":{"he":"78a5ae4cc7d2589fa249c91dd94d6dd41472e8f623e77bc2a96f39a8832d9123","he_nikud":"bbaaa3ea5d5abea9bd8d76d3025b6101c3d709d91e23c1cbd1736b0fda25d25e","en":"26bdcd9a1ad1607544d4787c294496f4cc233a2ca6145424a58885bf324aba14"},"history":{"earlier_supplied_English":"We have discussed how the Rebbe spoke of the baseness of this desire, saying that it is really no temptation at all (see “ His Praises ” #16; “ His Wisdom ” #51) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-304-original.json","original_owner_pointer":"/segments/1"},"qualifications":[{"id":"author301-origin-sichos-304-position-1","owner":"sichos-304-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-304-position-1","owner":"sichos-304-position-1","placement":"after-owning-paragraph","role":"current-source-qualification","text":"Additional explanations and references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-304-position-1","englishUTF8SHA256":"26bdcd9a1ad1607544d4787c294496f4cc233a2ca6145424a58885bf324aba14"}},{"owner":"sichos-304-position-2","section":304,"source_index":3,"array_position":2,"event_position":8,"group":"sichos304","anchor":"sichos-304-position-2","he":"אחר כך אמר: שנמצאים הרבה שמעצם גשמיותם ורגילותם בענין זה, אין מועיל להם כלל מהש ממאסין להם ענין זה, אדרבא באיזה לשון שידברו עמהם מזה יתגברו עליהם ההרהורים יותר. על כן טוב לרב בני אדם לבלי להתחיל לחשב בזה כלל.","he_nikud":"אַחַר כָּךְ אָמַר: שֶׁנִּמְצָאִים הַרְבֵּה שֶׁמֵּעֹצֶם גַּשְׁמִיּוּתָם וּרְגִילוּתָם בְּעִנְיָן זֶה, אֵין מוֹעִיל לָהֶם כְּלָל מַהש ֶּׁמְּמָאֲסִין לָהֶם עִנְיָן זֶה, אַדְּרַבָּא בְּאֵיזֶה לָשׁוֹן שֶׁיְּדַבְּרוּ עִמָּהֶם מִזֶּה יִתְגַּבְּרוּ עֲלֵיהֶם הַהִרְהוּרִים יוֹתֵר. עַל כֵּן טוֹב לְרֹב בְּנֵי אָדָם לִבְלִי לְהַתְחִיל לַחֲשֹׁב בָּזֶה כְּלָל.","en":"Afterward the Rebbe said that there are many people whose bodily involvement and habituation in this matter are so great that explaining its baseness does not help them at all. On the contrary, in whatever language one speaks to them about it, their lewd thoughts become stronger. Therefore it is better for most people not to even begin to think of it at all.","field_sha256":{"he":"8d515929877aa4a79c4c3ec43c7f05266aa4e109bfe8c3f23a11aca0062fcdce","he_nikud":"0ea422bb67c692bc7365f6bd82d8a8c85720e4db9a31f2fc6c622fc3e987f491","en":"d60e06dd6279470ddec580346ca71219bf407fd2868c570161cfea10f0308689"},"history":{"earlier_supplied_English":"The Rebbe said, “People are so bound up with their bodily desires, and tied to this one in particular, that it does not help when you explain how base this is. On the contrary, the more you speak of it, the more lewd thoughts they have. In most cases, it is therefore best not to even begin to think of it at all.”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-304-original.json","original_owner_pointer":"/segments/2"},"qualifications":[{"id":"author301-origin-sichos-304-position-2","owner":"sichos-304-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-304-position-2","owner":"sichos-304-position-2","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The unpointed Hebrew contains “מהש”, and the pointed text has an irregular corresponding sequence. Both supplied forms are preserved. The English renders the surrounding statement about explaining this matter’s baseness, without claiming a restored Hebrew reading. Additional references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-304-position-2","englishUTF8SHA256":"d60e06dd6279470ddec580346ca71219bf407fd2868c570161cfea10f0308689"}},{"owner":"sichos-304-position-3","section":304,"source_index":4,"array_position":3,"event_position":9,"group":"sichos304","anchor":"sichos-304-position-3","he":"וכמבאר מזה בספר הא\"ב: אל תכנס עם פתוייך בטוען ונטען וכו'.","he_nikud":"וְכַמְבֹאָר מִזֶּה בְּסֵפֶר הא\"ב: אַל תִּכְנֹס עִם פִּתּוּיֶיךָ בְּטוֹעֵן וְנִטְעָן וְכוּ'.","en":"And as is explained about this in the Aleph-Bet Book: “Do not enter into litigation with your temptations,” etc.","field_sha256":{"he":"65dd432505c77fa9027a17696d22fbf8ca6f42efd828b1d5a1d7bf94ae03ac55","he_nikud":"8453a3279a31e0227f72e092003fb787e6c241ffad927157b7b730b9244d8f7d","en":"f547886b7bcb3c95c93b1a5a5e950fe7d3f41dacef6e687da2ea7ff11821015d"},"history":{"earlier_supplied_English":"This is explained in Sefer HaMidot : “Do not enter into litigation with your tempter. Thinking about something for any length of time, even of its avoidance, strengthens desire and turns one’s will towards it.” 372 The Aleph-Bet Book , Adultery and Immoral Behavior, A:10.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-304-original.json","original_owner_pointer":"/segments/3"},"qualifications":[{"id":"author301-origin-sichos-304-position-3","owner":"sichos-304-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-304-position-3","owner":"sichos-304-position-3","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew addresses plural “temptations”. The earlier English’s singular “tempter” and additional continuation remain accessible as historical wording, not as this paragraph’s current text. Additional references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-304-position-3","englishUTF8SHA256":"f547886b7bcb3c95c93b1a5a5e950fe7d3f41dacef6e687da2ea7ff11821015d"}},{"owner":"sichos-305-position-0","section":305,"source_index":1,"array_position":0,"event_position":10,"group":"sichos305","anchor":"sichos-305-position-0","he":"שיך להשיחות ששמעתי ממנו ז\"ל כמה פעמים שאמר בזה הלשון: אין מה לעשות (מע האט גאר ניט צו טאהן).","he_nikud":"שַׁיָּךְ לְהַשִּׂיחוֹת שֶׁשָּׁמַעְתִּי מִמֶּנּוּ ז\"ל כַּמָּה פְּעָמִים שֶׁאָמַר בְּזֶה הַלָּשׁוֹן: אֵין מַה לַּעֲשׂוֹת (מֶע הָאט גָּאר נִיט צוּ טָאהן).","en":"This relates to the conversations I heard from the Rebbe, of blessed memory, many times when he said in these words: “There is nothing to do” (in Yiddish: “We have nothing at all to do”).","field_sha256":{"he":"63d9427a20ec20b3e9c283a7a4c708613eff252f22b4f9d6e4e1e755bb79aafc","he_nikud":"ad9d0a30259bc79703528739f9122e5c8269f4245fd13067d3c84d9e9d4640ba","en":"30aabd602560bcedefd69d05d3809796a1b009eb2a5d302567c5ac4e399c528a"},"history":{"earlier_supplied_English":"Many times the Rebbe said, “ Me hat gar nit tzu tahn – We have nothing at all to do.”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-305-original.json","original_owner_pointer":"/segments/0"},"qualifications":[{"id":"author301-origin-sichos-305-position-0","owner":"sichos-305-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-305-position-0","owner":"sichos-305-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew describes repeated occasions without giving an exact number."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-305-position-0","englishUTF8SHA256":"30aabd602560bcedefd69d05d3809796a1b009eb2a5d302567c5ac4e399c528a"}},{"owner":"sichos-305-position-1","section":305,"source_index":2,"array_position":1,"event_position":11,"group":"sichos305","anchor":"sichos-305-position-1","he":"(וכבר נדפסו (לעיל רסט רפז) כמה שיחות נפלאות) וכן מבאר בדברי רבותינו ז\"ל במנחות דף צ\"ט: \"תנא דבי רבי ישמעאל – דברי תורה לא יהיה עליך חובה ואי אתה רשאי לפטר עצמך מהן\".","he_nikud":"(וּכְבָר נִדְפְּסוּ (לְעֵיל רסט רפז) כַּמָּה שִׂיחוֹת נִפְלָאוֹת) וְכֵן מְבֹאָר בְּדִבְרֵי רַבּוֹתֵינוּ ז\"ל בִּמְנָחוֹת דַּף צ\"ט: \"תָּנָא דְּבֵי רַבִּי יִשְׁמָעֵאל – דִּבְרֵי תּוֹרָה לֹא יִהְיֶה עָלֶיךָ חוֹבָה וְאִי אַתָּה רַשַּׁאי לִפְטֹר עַצְמְךָ מֵהֶן\".","en":"(And several wondrous conversations have already been printed, above, 269 and 287.) And so it is explained in the words of our Sages, of blessed memory, in Menachos, page 99: “The school of Rabbi Ishmael taught: ‘The words of Torah should not be an obligation upon you, and you are not permitted to exempt yourself from them.’”","field_sha256":{"he":"5d7918ad43181f5f4187974512601374be339f757e5b36020d38067af38df3ac","he_nikud":"0b2e96bc494909ac570467a818c63205319eaa421112e216bebf4a5f55cfd3f9","en":"89f55cf405f7611eab878d68bd03f0ac134fa463481f2d775cc719beb43503b5"},"history":{"earlier_supplied_English":"[The Rebbe said this in relation to his conversations and many of them have already been printed]. We find in the Talmud that the disciples of Rabbi Ishmael taught, “The words of the Torah should not be viewed as an obligation, but one is not permitted to exempt oneself from them” ( Menachot 99b) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-305-original.json","original_owner_pointer":"/segments/1"},"qualifications":[{"id":"author301-origin-sichos-305-position-1","owner":"sichos-305-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-305-position-1","owner":"sichos-305-position-1","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The supplied Hebrew cites Menachos, page 99, without specifying a side. Earlier English gives 99b and an English comparison text gives 99a; neither side has been independently established here. The source also refers to teachings 269 and 287; those destinations have not been independently checked here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-305-position-1","englishUTF8SHA256":"89f55cf405f7611eab878d68bd03f0ac134fa463481f2d775cc719beb43503b5"}},{"owner":"sichos-305-position-2","section":305,"source_index":3,"array_position":2,"event_position":12,"group":"sichos305","anchor":"sichos-305-position-2","he":"והוא עצה נפלאה למי שמבינה מעט.","he_nikud":"וְהוּא עֵצָה נִפְלָאָה לְמִי שֶׁמְּבִינָהּ מְעַט.","en":"And this is wonderful advice for one who understands it even a little.","field_sha256":{"he":"c35a4fa5363aa0f0175dbf6b1e83535e62e94bf28e2bb51ff607ae31c2ecc7f0","he_nikud":"b1043435effcc01971fc8fc8478700b0a4886ba91a26aeebb8fcd5d30d0eb132","en":"62c0cf2aadfb942f1697984a6881b57fd0f5f335e24285b0dc650626d764f4d0"},"history":{"earlier_supplied_English":"This explains the Rebbe’s statement and is wonderful advice to he who understands it even a little.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-305-original.json","original_owner_pointer":"/segments/2"},"qualifications":[{"id":"author301-origin-sichos-305-position-2","owner":"sichos-305-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-305-position-2","englishUTF8SHA256":"62c0cf2aadfb942f1697984a6881b57fd0f5f335e24285b0dc650626d764f4d0"}},{"owner":"sichos-306-position-0","section":306,"source_index":1,"array_position":0,"event_position":13,"group":"sichos306","anchor":"sichos-306-position-0","he":"שיך להא\"ב החדש אות ד' דעת סימן א' המתחיל: דע כי לכל העולמות ולכל נברא יש קומה מיחדת וכו', למשל מין האריה וכו'. וההבדלים כלם הם רמוזים בתמונת האותיות ובצרופיהם. והזוכה להבין את התורה וכו'.","he_nikud":"שַׁיָּךְ לְהָא\"ב הֶחָדָשׁ אוֹת ד' דַּעַת סִימָן א' הַמַּתְחִיל: דַּע כִּי לְכָל הָעוֹלָמוֹת וּלְכָל נִבְרָא יֵשׁ קוֹמָה מְיֻחֶדֶת וְכוּ', לְמָשָׁל מִין הָאַרְיֵה וְכוּ'. וְהַהֶבְדֵּלִים כֻּלָּם הֵם רְמוּזִים בִּתְמוּנַת הָאוֹתִיּוֹת וּבְצֵרוּפֵיהֶם. וְהַזּוֹכֶה לְהָבִין אֶת הַתּוֹרָה וְכוּ'.","en":"This relates to the new Aleph-Bet Book, letter dalet, Knowledge, item 1, which begins: “Know that every world and everything created has its own particular form, etc.; for example, the species of the lion, etc. And all the differences are alluded to in the forms of the letters and their combinations. And one who is worthy of understanding the Torah, etc.”","field_sha256":{"he":"5f0a3b0a521dcafb85522d0000f822dace749aa28558c750c47aa58bffa33b0e","he_nikud":"487c5da17b13d2ad4a23bda601a8e93811fec8007e4f11421ff9baa5e01d5c8e","en":"6a0689af0a072fe7f12a14f047a6077e055605a5bd5f40b738f8ea155a6cc7ec"},"history":{"earlier_supplied_English":"In the second part of Sefer HaMidot, in the category of Da'at (Knowledge), it is written: “Every universe and everything created has its own particular form, … for example, the lion … and the differences between created beings are alluded to in the forms of the letters and their combinations. One who is worthy of understanding the Torah ….” 373 Ibid. , True Knowledge B:1. See Likutey Halakhot , Milah 5:24; ibid., Behemah Tehorah 4:23; Alim LeTerufah #205; Sichot VeSipurim , p. 84, #12.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-306-original.json","original_owner_pointer":"/segments/0"},"qualifications":[{"id":"author301-origin-sichos-306-position-0","owner":"sichos-306-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-306-position-0","owner":"sichos-306-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The source calls this the new Aleph-Bet Book, letter dalet, Knowledge, item 1. Identification with a particular second-part edition and additional references in the earlier English have not been independently established. An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-306-position-0","englishUTF8SHA256":"6a0689af0a072fe7f12a14f047a6077e055605a5bd5f40b738f8ea155a6cc7ec"}},{"owner":"sichos-306-position-1","section":306,"source_index":2,"array_position":1,"event_position":14,"group":"sichos306","anchor":"sichos-306-position-1","he":"נראה לי שזהו ענין השיחה ששמעתי מפיו הקדוש קדם שבת חנכה תקס\"ה מענין הבריות של העולם, שכל התמונות והצורות של כל בני אדם כלם נכללים בתבת אדם הנאמר בתורה \"נעשה אדם\" (בראשית א־כו). כי בזו התבה אדם שאמר השם יתברך \"נעשה אדם\" בתבה זו בעצמה נכללים כל מיני התמונות של כל בני אדם שבעולם.","he_nikud":"נִרְאֵה לִי שֶׁזֶּהוּ עִנְיַן הַשִּׂיחָה שֶׁשָּׁמַעְתִּי מִפִּיו הַקָּדוֹשׁ קֹדֶם שַׁבָּת חֲנֻכָּה תקס\"ה מֵעִנְיַן הַבְּרִיּוֹת שֶׁל הָעוֹלָם, שֶׁכָּל הַתְּמוּנוֹת וְהַצּוּרוֹת שֶׁל כָּל בְּנֵי אָדָם כֻּלָּם נִכְלָלִים בְּתֵבַת אָדָם הַנֶּאֱמַר בַּתּוֹרָה \"נַעֲשֶׂה אָדָם\" (בְּרֵאשִׁית א־כו). כִּי בְּזוֹ הַתֵּבָה אָדָם שֶׁאָמַר הַשֵּׁם יִתְבָּרַךְ \"נַעֲשֶׂה אָדָם\" בְּתֵבָה זוֹ בְּעַצְמָהּ נִכְלָלִים כָּל מִינֵי הַתְּמוּנוֹת שֶׁל כָּל בְּנֵי אָדָם שֶׁבָּעוֹלָם.","en":"It appears to me that this is the subject of the conversation I heard from the Rebbe’s holy lips before Shabbat Chanukah 5565 regarding the creatures of the world: all the likenesses and forms of all human beings are included in the word adam (man) mentioned in the Torah, “Let us make man” (Genesis 1:26). For in this word adam, of which God, blessed be He, said “Let us make man,” in this very word are included all kinds of likenesses of all human beings in the world.","field_sha256":{"he":"6cc6b4e946d84a66e1272c37e3a76d30390447f9b9228b90ae7f6eb23158bacb","he_nikud":"f74db594b701444ab3c3dfe1fffa8475d5ab99fc36eac8bae6cc4d67437c26b4","en":"a26a1d44ea071e4c18857203086590af6f9a5ff4099d92688a58d93e57d2c32b"},"history":{"earlier_supplied_English":"This appears to be related to a conversation we heard from Rebbe’s holy lips before Shabbat Chanukah 5565/1804, regarding the creatures in the world. 374 See Likutey Moharan I, 54:3. This lesson was revealed on that same Shabbat Chanukah . The Rebbe said, “Every human likeness is included in the word adam (man) as mentioned in the Torah. God said, ‘Let us make man ( adam ) in our image’ (Genesis 1:26) . As soon as He said the word adam , He included every human likeness in that word.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-306-original.json","original_owner_pointer":"/segments/1"},"qualifications":[{"id":"author301-origin-sichos-306-position-1","owner":"sichos-306-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-306-position-1","owner":"sichos-306-position-1","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew year תקס״ה is rendered 5565. The earlier English’s civil-year conversion and statement about another lesson’s revelation have not been independently verified here. An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-306-position-1","englishUTF8SHA256":"a26a1d44ea071e4c18857203086590af6f9a5ff4099d92688a58d93e57d2c32b"}},{"owner":"sichos-306-position-2","section":306,"source_index":3,"array_position":2,"event_position":15,"group":"sichos306","anchor":"sichos-306-position-2","he":"וכן תבת בהמה וחיה וכו' הנאמר במעשה בראשית, בזו התבה גם כן נכלל כלהתמונות של כל בהמה וחיה וכן שאר הנבראים.","he_nikud":"וְכֵן תֵּבַת בְּהֵמָה וְחַיָּה וְכוּ' הַנֶּאֱמָר בְּמַעֲשֵׂה בְּרֵאשִׁית, בְּזוֹ הַתֵּבָה גַּם כֵּן נִכְלָל כָּלהַתְּמוּנוֹת שֶׁל כָּל בְּהֵמָה וְחַיָּה וְכֵן שְׁאָר הַנִּבְרָאִים.","en":"And likewise the word for animal and beast, etc., mentioned in the account of Creation: in this word too are included all the forms of every animal and beast, and likewise the other created beings.","field_sha256":{"he":"45ef47371c00c6bb0878e016c2404ecfa38bfef160f63ae2046271f4fa42c354","he_nikud":"f7647a69a527f76fd0f438e5273dadc510e05ad082e8abeddad895ad66267a1d","en":"b93f754f7280528fb2af7a3b5ff8cb44f7d8437df48e3f864aeafca5066d3e86"},"history":{"earlier_supplied_English":"“The same is true of such words as behemah (animal) and chayah (beast) used in the account of creation. These words include the forms of every animal and beast. The same is true of everything else created.”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-306-original.json","original_owner_pointer":"/segments/2"},"qualifications":[{"id":"author301-origin-sichos-306-position-2","owner":"sichos-306-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-306-position-2","owner":"sichos-306-position-2","placement":"after-owning-paragraph","role":"current-source-qualification","text":"Both supplied Hebrew fields fuse the words for “all the forms”. The source uses a singular “word” while naming animal categories; the English retains that number without reconstructing the Hebrew. An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-306-position-2","englishUTF8SHA256":"b93f754f7280528fb2af7a3b5ff8cb44f7d8437df48e3f864aeafca5066d3e86"}},{"owner":"sichos-306-position-3","section":306,"source_index":4,"array_position":3,"event_position":16,"group":"sichos306","anchor":"sichos-306-position-3","he":"והאריך בשיחה זו.","he_nikud":"וְהֶאֱרִיךְ בְּשִׂיחָה זוֹ.","en":"And the Rebbe spoke at length on this topic.","field_sha256":{"he":"3f5376dd494d5f451a6f988c4b58494ff5e76d25421163f35e08fa2fe4d2b42b","he_nikud":"e144ee4f1644e07ccae9fff405bf154f6c129704a7d0bfc2c7b1010a0d328837","en":"d7e7a4f0c574efc0cc3b502fe410e814dd94477c8a48693de780974c608098de"},"history":{"earlier_supplied_English":"The Rebbe spoke at length on this topic.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-306-original.json","original_owner_pointer":"/segments/3"},"qualifications":[{"id":"author301-origin-sichos-306-position-3","owner":"sichos-306-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-306-position-3","owner":"sichos-306-position-3","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-306-position-3","englishUTF8SHA256":"d7e7a4f0c574efc0cc3b502fe410e814dd94477c8a48693de780974c608098de"}},{"owner":"sichos-306-position-4","section":306,"source_index":5,"array_position":4,"event_position":17,"group":"sichos306","anchor":"sichos-306-position-4","he":"ואמר אז: שיש חכמות אפלו בזה העולם שיכולין לחיות בהם לבד בלי שום אכילה ושתיה. כי יש דברים נפלאים וחכמות עליונות ונוראות אפלו בזה העולם שיכולין לחיות בהם לבד בלי שום אכילה ושתיה.","he_nikud":"וְאָמַר אָז: שֶׁיֵּשׁ חָכְמוֹת אֲפִלּוּ בְּזֶה הָעוֹלָם שֶׁיְּכוֹלִין לִחְיוֹת בָּהֶם לְבַד בְּלִי שׁוּם אֲכִילָה וּשְׁתִיָּה. כִּי יֵשׁ דְּבָרִים נִפְלָאִים וְחָכְמוֹת עֶלְיוֹנוֹת וְנוֹרָאוֹת אֲפִלּוּ בְּזֶה הָעוֹלָם שֶׁיְּכוֹלִין לִחְיוֹת בָּהֶם לְבַד בְּלִי שׁוּם אֲכִילָה וּשְׁתִיָּה.","en":"And he then said that there are categories of wisdom, even in this world, on which alone one can live, without any eating or drinking. For there are wonderful things and lofty and awesome categories of wisdom, even in this world, on which alone one can live, without any eating or drinking.","field_sha256":{"he":"8d008d76db38e7b25bf5df5eb6996d211716e5ffd49bbf2593cb39f13b28ed22","he_nikud":"269d4826921fe00a861a635226527024cebb5aa0f21c6a0f083d9f4fa1b68419","en":"abc33990d5f2eab58e97156d03c9f73a13b4d83b1b927938bdbdc0abdb13752d"},"history":{"earlier_supplied_English":"He then said, “There are categories of wisdom, even in this world, which can sustain a person without any other nourishment. There are such awesomely wonderful categories of wisdom even in this world. A man can live without eating or drinking with such wisdom alone” (see “ His Wisdom ” #181) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-306-original.json","original_owner_pointer":"/segments/4"},"qualifications":[{"id":"author301-origin-sichos-306-position-4","owner":"sichos-306-position-4","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-306-position-4","owner":"sichos-306-position-4","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew. Additional explanations and references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-306-position-4","englishUTF8SHA256":"abc33990d5f2eab58e97156d03c9f73a13b4d83b1b927938bdbdc0abdb13752d"}},{"owner":"sichos-306-position-5","section":306,"source_index":6,"array_position":5,"event_position":18,"group":"sichos306","anchor":"sichos-306-position-5","he":"והאריך בשיחה זו הרבה ולא זכינו לכתבה:","he_nikud":"וְהֶאֱרִיךְ בְּשִׂיחָה זוֹ הַרְבֵּה וְלֹא זָכִינוּ לְכָתְבָהּ:","en":"And the Rebbe spoke at great length in this conversation, but we were not worthy of recording it:","field_sha256":{"he":"a70b36173b71fab6f766cb374d5b678b2a442985aa8f4e354d63b1a5a6c44348","he_nikud":"2bbc5810c389d914b59b146874645b001eb960647ebbfcac912d40d0f22ca4d9","en":"b009d85fe46721610ed1ff4063b7ec52f3f598b6fadbdd653baf53176149723d"},"history":{"earlier_supplied_English":"The Rebbe spoke at length, but we were not worthy of recording the rest.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-306-original.json","original_owner_pointer":"/segments/5"},"qualifications":[{"id":"author301-origin-sichos-306-position-5","owner":"sichos-306-position-5","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-306-position-5","owner":"sichos-306-position-5","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-306-position-5","englishUTF8SHA256":"b009d85fe46721610ed1ff4063b7ec52f3f598b6fadbdd653baf53176149723d"}},{"owner":"sichos-307-position-0","section":307,"source_index":1,"array_position":0,"event_position":19,"group":"sichos307","anchor":"sichos-307-position-0","he":"לענין מה שדרך העולם לומר בכל שנה ובכל עת שעכשו אינם עתים טובות ובשנים הקודמים היה טוב יותר וכו'.","he_nikud":"לְעִנְיַן מַה שֶּׁדֶּרֶךְ הָעוֹלָם לוֹמַר בְּכָל שָׁנָה וּבְכָל עֵת שֶׁעַכְשָׁו אֵינָם עִתִּים טוֹבוֹת וּבַשָּׁנִים הַקּוֹדְמִים הָיָה טוֹב יוֹתֵר וְכוּ'.","en":"Regarding what people commonly say every year and at every time: times are not good now and previous years were better, etc.","field_sha256":{"he":"6e83c972eddec9a4afb1679f68f6ce3034b6d9026c5cd4ebda7903a5e752469b","he_nikud":"37657154db854e50e83cef1bd94a7e572115ef0808fd65a93570956ae64fef86","en":"22641acc36decf9c04ffc7b172e7c74b2139b7ed8fc862f06615ea67c247ac71"},"history":{"earlier_supplied_English":"Every year, people say that previous years were better and times are not as good as they were before.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-307-original.json","original_owner_pointer":"/segments/0"},"qualifications":[{"id":"author301-origin-sichos-307-position-0","owner":"sichos-307-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-307-position-0","owner":"sichos-307-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-307-position-0","englishUTF8SHA256":"22641acc36decf9c04ffc7b172e7c74b2139b7ed8fc862f06615ea67c247ac71"}},{"owner":"sichos-307-position-1","section":307,"source_index":2,"array_position":1,"event_position":20,"group":"sichos307","anchor":"sichos-307-position-1","he":"כידוע שיחות כאלו בין רב העולם, דברנו עמו מזה הרבה. ורב השיחה היה שספרו לפניו הרבה שבימים הראשונים הטובים היה הכל בזול גדול הרבה יותר משל עכשו. כי לא היה אז נגידים ועשירים גדולים כמו עכשו. ומה שמוציא עכשו בעל הבית פשוט ואפלו מקבל חשוב הוא יותר מההוצאות של הנגידים, שבשנים הקודמים כידוע ומפרסם כל זה.","he_nikud":"כַּיָּדוּעַ שִׂיחוֹת כָּאֵלּוּ בֵּין רֹב הָעוֹלָם, דִּבַּרְנוּ עִמּוֹ מִזֶּה הַרְבֵּה. וְרֹב הַשִּׂיחָה הָיָה שֶׁסִּפְּרוּ לְפָנָיו הַרְבֵּה שֶׁבַּיָּמִים הָרִאשׁוֹנִים הַטּוֹבִים הָיָה הַכֹּל בְּזוֹל גָּדוֹל הַרְבֵּה יוֹתֵר מִשֶּׁל עַכְשָׁו. כִּי לֹא הָיָה אָז נְגִידִים וַעֲשִׁירִים גְּדוֹלִים כְּמוֹ עַכְשָׁו. וּמַה שֶּׁמּוֹצִיא עַכְשָׁו בַּעַל הַבַּיִת פָּשׁוּט וַאֲפִלּוּ מְקַבֵּל חָשׁוּב הוּא יוֹתֵר מֵהַהוֹצָאוֹת שֶׁל הַנְּגִידִים, שֶׁבַּשָּׁנִים הַקּוֹדְמִים כַּיָּדוּעַ וּמְפֻרְסָם כָּל זֶה.","en":"As is known, such discussions are common among most people; we spoke with him about this at length. Most of the conversation consisted of their telling him repeatedly that in the good old days everything was far cheaper than it is now. For there were not then great magnates and rich men as there are now. And what a simple householder, and even an important recipient [of support], spends now is more than the expenditures of the magnates in former years, as all this is well known and widely recognized.","field_sha256":{"he":"635bbd9883c7e59081b4fc043c78b5614f360db2b8629606c1b4918f5ed2729f","he_nikud":"2071bf4ea6047aeb0241ae1bec2604bba88fdea0bf3a1673de85e6b23a56278d","en":"727be8390c2f191cf343a2f55748a5c540673e0c5a828dcbcb0894f43ba5bac2"},"history":{"earlier_supplied_English":"The Rebbe spoke to us about this at length. He said that people might say that things were much cheaper in the good old days, but then again, people did not have as much money as they have now. A simple householder, even one living from charity, spends more today than the wealthy of yesteryear.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-307-original.json","original_owner_pointer":"/segments/1"},"qualifications":[{"id":"author301-origin-sichos-307-position-1","owner":"sichos-307-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-307-position-1","owner":"sichos-307-position-1","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew describes an “important recipient”; whether this refers to the recipient’s standing or the scale of what he receives is not clear. “[Of support]” is explanatory wording. The English leaves that distinction unresolved."},{"id":"author301-source-note-2-sichos-307-position-1","owner":"sichos-307-position-1","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew. Additional explanations and references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-307-position-1","englishUTF8SHA256":"727be8390c2f191cf343a2f55748a5c540673e0c5a828dcbcb0894f43ba5bac2"}},{"owner":"sichos-307-position-2","section":307,"source_index":3,"array_position":2,"event_position":21,"group":"sichos307","anchor":"sichos-307-position-2","he":"ענה ואמר: הלא אדרבא, השם יתברך מנהיג עתה העולם יפה יותר מקדם! ואמר בזה הלשון: אדרבא דער אייבערשטער פירט היינט שעניר דיא וועלט.","he_nikud":"עָנָה וְאָמַר: הֲלֹא אַדְּרַבָּא, הַשֵּׁם יִתְבָּרַךְ מַנְהִיג עַתָּה הָעוֹלָם יָפֶה יוֹתֵר מִקֹּדֶם! וְאָמַר בְּזֶה הַלָּשׁוֹן: אַדְּרַבָּא דֶּער אֵייבֶּערְשְׁטֶער פִירְט הַיינְט שֶׁענֶיר דִיא וֶועלְט.","en":"The Rebbe answered, “Surely, on the contrary, God, blessed be He, now directs the world better than before!” And he said in these words, in Yiddish: “On the contrary, God now directs the world better.”","field_sha256":{"he":"42658afa7199e94dc7aaf74399a8bc1f9d3889f694ffa66c2cd132d4cfecaa19","he_nikud":"6baabd337cc4869ebc0855bc92a529c0f1bea42e04148175f9b7c55a98fc4810","en":"6f95089329d3c5dc609331af42906a7d3912d219a3a75086c9739e1840e0cda4"},"history":{"earlier_supplied_English":"He said, “ Aderaba. Der Eibershter firt heint sheiner die velt – The opposite is true. God now directs the world better than ever.” 375 See Sichot VeSipurim , p. 212, #33; above, note 192.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-307-original.json","original_owner_pointer":"/segments/2"},"qualifications":[{"id":"author301-origin-sichos-307-position-2","owner":"sichos-307-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-307-position-2","owner":"sichos-307-position-2","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew. Additional explanations and references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-307-position-2","englishUTF8SHA256":"6f95089329d3c5dc609331af42906a7d3912d219a3a75086c9739e1840e0cda4"}},{"owner":"sichos-308-position-0","section":308,"source_index":1,"array_position":0,"event_position":22,"group":"sichos308","anchor":"sichos-308-position-0","he":"ויש לנו בזה שיחות הרבה, שכל דבורים ושיחות כאלו של העולם הכל הם מן היצר הרע, שמרבה שיחות כאלה להכביד הצער ולהגדיל דאגת הפרנסה כאלו עכשו ח\"ו, אפס תקוה.","he_nikud":"וְיֵשׁ לָנוּ בָּזֶה שִׂיחוֹת הַרְבֵּה, שֶׁכָּל דִּבּוּרִים וְשִׂיחוֹת כָּאֵלּוּ שֶׁל הָעוֹלָם הַכֹּל הֵם מִן הַיֵּצֶר הָרָע, שֶׁמַּרְבֶּה שִׂיחוֹת כָּאֵלֶּה לְהַכְבִּיד הַצַּעַר וּלְהַגְדִּיל דַּאֲגַת הַפַּרְנָסָה כְּאִלּוּ עַכְשָׁו ח\"ו, אָפֵס תִּקְוָה.","en":"And we have many discussions about this: all such words and discussions of the world are entirely from the evil inclination, which multiplies such discussions to increase the pain and magnify the worry about livelihood, as though now, Heaven forbid, there were no hope.","field_sha256":{"he":"a8123200eecb2d6d3d4dfbedcd72a3203beffad82d9e3bba16da66fed7c87aa0","he_nikud":"9fe668a31793034d259f654fe20f882d9995f2d476af13db9ceb188f05c2f4ef","en":"f128bdcf73aac0160db3392e68bf0940b1dd41b3078443fea31741321c8fd557"},"history":{"earlier_supplied_English":"These are among the many thoughts which the Rebbe shared with us regarding the above. All this talk about the good old days is the work of the Evil One. He wants people to speak like this to make them suffer and worry all the more about their livelihoods. He would like to make them feel that there is no hope at all now, Heaven forbid.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/0"},"qualifications":[{"id":"author301-origin-sichos-308-position-0","owner":"sichos-308-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-308-position-0","owner":"sichos-308-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The supplied Hebrew says “we have many discussions about this” without naming that plural speaking voice. The English retains “we” without attributing those words specifically to the Rebbe."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-0","englishUTF8SHA256":"f128bdcf73aac0160db3392e68bf0940b1dd41b3078443fea31741321c8fd557"}},{"owner":"sichos-308-position-1","section":308,"source_index":2,"array_position":1,"event_position":23,"group":"sichos308","anchor":"sichos-308-position-1","he":"ובאמת הוא שקר וכזב כי השם יתברך מפרנס ומכלכל העולם תמיד ובכל דור ובכל שנה נמצאים עולים ויורדים. ואם נסתכל היטב בכל שנה ובכל עת, בודאי נמצא תמיד אנשים רבים שהיו עניים ומשרתים וכיוצא בשנים הקודמים, ועכשו נתעשרו. וגם הם רבם אומרים שהשנים אינם מתקנות עתה כמקדם, מחמת שרוצים בכל פעם עשירות יותר, ומנהיגים בביתם בגדולות יותר, עד שהוצאתם מרבה. ואומרים שעתה אינם שנים טובות כמקדם, אף על פי שאנו זוכרים שזה סמוך לפני איזה שנים היו עניים או משרתים וכיוצא בהם.","he_nikud":"וּבֶאֱמֶת הוּא שֶׁקֶר וְכָזָב כִּי הַשֵּׁם יִתְבָּרַךְ מְפַרְנֵס וּמְכַלְכֵּל הָעוֹלָם תָּמִיד וּבְכָל דּוֹר וּבְכָל שָׁנָה נִמְצָאִים עוֹלִים וְיוֹרְדִים. וְאִם נִסְתַּכֵּל הֵיטֵב בְּכָל שָׁנָה וּבְכָל עֵת, בְּוַדַּאי נִמְצָא תָּמִיד אֲנָשִׁים רַבִּים שֶׁהָיוּ עֲנִיִּים וּמְשָׁרְתִים וְכַיּוֹצֵא בַּשָּׁנִים הַקּוֹדְמִים, וְעַכְשָׁו נִתְעַשְּׁרוּ. וְגַם הֵם רֻבָּם אוֹמְרִים שֶׁהַשָּׁנִים אֵינָם מְתֻקָּנוֹת עַתָּה כְּמִקֹּדֶם, מֵחֲמַת שֶׁרוֹצִים בְּכָל פַּעַם עֲשִׁירוּת יוֹתֵר, וּמַנְהִיגִים בְּבֵיתָם בִּגְדוֹלוֹת יוֹתֵר, עַד שֶׁהוֹצָאָתָם מְרֻבָּה. וְאוֹמְרִים שֶׁעַתָּה אֵינָם שָׁנִים טוֹבוֹת כְּמִקֹּדֶם, אַף עַל פִּי שֶׁאָנוּ זוֹכְרִים שֶׁזֶּה סָמוּךְ לִפְנֵי אֵיזֶה שָׁנִים הָיוּ עֲנִיִּים אוֹ מְשָׁרְתִים וְכַיּוֹצֵא בָּהֶם.","en":"But in truth it is falsehood and lies, for God, blessed be He, continuously provides for and sustains the world, and in every generation and every year there are those who rise and those who fall. And if we look carefully at every year and every time, we will certainly always find many people who were poor and servants and the like in previous years and have now become wealthy. And even they, for the most part, say that times are not as good now as before, because they want more wealth each time and conduct their households on a grander scale, until their expenses are great. And they say that now the years are not as good as before, even though we remember that only some years ago they were poor or servants or the like.","field_sha256":{"he":"886285d1bb5d9cc6ce7783cdaa9b0c9a689fd0b6f571640c496ac54289324b4f","he_nikud":"8be568196b6fdafdbd4e4af369eb58fa52200ecbb17730c2c9f9caf1e5b1cc72","en":"eca605b34885535164f2cc3373b344ba8a8f4687bd259ed6a5fa586b36bd8153"},"history":{"earlier_supplied_English":"This is all false. God continuously sustains the world and people rise and fall financially in every generation. If you look carefully at any period, you will find people who were poor, with menial jobs, who became wealthy. Yet they too claim that times are not as good as before – because they always want more. Now that they have tasted wealth, they are no longer satisfied and want more all the time. They now live ostentatiously and cannot meet their expenses, so they complain that times are not as good as before. But we ourselves recall that not too many years ago, most of these complainers were poor or working as domestics or the like.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/1"},"qualifications":[{"id":"author301-origin-sichos-308-position-1","owner":"sichos-308-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-1","englishUTF8SHA256":"eca605b34885535164f2cc3373b344ba8a8f4687bd259ed6a5fa586b36bd8153"}},{"owner":"sichos-308-position-2","section":308,"source_index":3,"array_position":2,"event_position":24,"group":"sichos308","anchor":"sichos-308-position-2","he":"ויהיה איך שיהיה, מאי נפקא מנה, מה שצועקים בכל פעם שהימים הראשונים היו טובים מאלה. וכבר צוח שלמה על זה וסתר דבריהם. ואמר (קהלת ז): \"אל תאמר שהימים הראשונים היו טובים מאלה, כי לא מחכמה שאלת על זה\".","he_nikud":"וְיִהְיֶה אֵיךְ שֶׁיִּהְיֶה, מַאי נָפְקָא מִנָּהּ, מַה שֶּׁצּוֹעֲקִים בְּכָל פַּעַם שֶׁהַיָּמִים הָרִאשׁוֹנִים הָיוּ טוֹבִים מֵאֵלֶּה. וּכְבָר צָוַח שְׁלֹמֹה עַל זֶה וְסָתַר דִּבְרֵיהֶם. וְאָמַר (קֹהֶלֶת ז): \"אַל תֹּאמַר שֶׁהַיָּמִים הָרִאשׁוֹנִים הָיוּ טוֹבִים מֵאֵלֶּה, כִּי לֹא מֵחָכְמָה שָׁאַלְתָּ עַל זֶה\".","en":"And however it may be, what difference does it make that they constantly cry out that the former days were better than these? Solomon already cried out about this and refuted their words. And he said (Ecclesiastes 7): “Do not say that the former days were better than these, for it is not out of wisdom that you ask about this.”","field_sha256":{"he":"36e6bfd9c62aaf9cacf421acfde58c3759e0cda3d6849be49ed9272db9e678bf","he_nikud":"4afaa1ec88428cc17bb7f2f24ac1c633122922318fc397cb2f979d97dc94684e","en":"9f597d05fc248779cb4252a5c1243a29d6ef73d237576515c9d1727af3a79af8"},"history":{"earlier_supplied_English":"Whether or not this is the fact, what use is it always to cry that the past was better? The wise King Solomon refuted this idea long ago when he said, “Do not say that the former times were better than these, for it is not out of wisdom that you ask this” (Ecclesiastes 7:10) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/2"},"qualifications":[{"id":"author301-origin-sichos-308-position-2","owner":"sichos-308-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-2","englishUTF8SHA256":"9f597d05fc248779cb4252a5c1243a29d6ef73d237576515c9d1727af3a79af8"}},{"owner":"sichos-308-position-3","section":308,"source_index":4,"array_position":3,"event_position":25,"group":"sichos308","anchor":"sichos-308-position-3","he":"ואף על פי שרש\"י פרש שם כי הכל לפי זכות הדורות, אף על פי כן הרבה פנים לתורה ואין מקרא יוצא מדי פשוטו, כי שלמה המלך, ע\"ה, שהיה חכם גדול מכל אדם אמר בחכמתו ורוח קדשו שזה שטות גדול מה שאומרים שהימים הראשונים היו טובים מאלה. כי בכל פעם אומרים כך. ובאמת אנו רואים שבכל פעם העולם נתעשר יותר, ומתנהג העולם בגדולות ובהוצאה מרבה יותר משנים קדמוניות:","he_nikud":"וְאַף עַל פִּי שֶׁרַשִׁ\"י פֵּרֵשׁ שָׁם כִּי הַכֹּל לְפִי זְכוּת הַדּוֹרוֹת, אַף עַל פִּי כֵן הַרְבֵּה פָּנִים לַתּוֹרָה וְאֵין מִקְרָא יוֹצֵא מִדֵּי פְּשׁוּטוֹ, כִּי שְׁלֹמֹה הַמֶּלֶךְ, ע\"ה, שֶׁהָיָה חָכָם גָּדוֹל מִכָּל אָדָם אָמַר בְּחָכְמָתוֹ וְרוּחַ קָדְשׁוֹ שֶׁזֶּה שְׁטוּת גָּדוֹל מַה שֶּׁאוֹמְרִים שֶׁהַיָּמִים הָרִאשׁוֹנִים הָיוּ טוֹבִים מֵאֵלֶּה. כִּי בְּכָל פַּעַם אוֹמְרִים כָּךְ. וּבֶאֱמֶת אָנוּ רוֹאִים שֶׁבְּכָל פַּעַם הָעוֹלָם נִתְעַשֵּׁר יוֹתֵר, וּמִתְנַהֵג הָעוֹלָם בִּגְדוֹלוֹת וּבְהוֹצָאָה מְרֻבָּה יוֹתֵר מִשָּׁנִים קַדְמוֹנִיּוֹת:","en":"And although Rashi explained there that everything depends on the merit of the generations, nevertheless the Torah has many faces, and scripture does not depart from its plain meaning. For King Solomon, peace be upon him, who was wiser than all men, said in his wisdom and holy spirit that it is great foolishness to say that the former days were better than these. For people say this all the time. And in truth we see that each time the world becomes wealthier and conducts itself on a grander scale and with greater expenditure than in earlier years:","field_sha256":{"he":"ffe05c784ea3d6c721f546d59070413db7a695b869517b223f86e5102cc48b85","he_nikud":"5193f6791c3965adccaef29e5212c805466c496cad0bd7dc4201dcb7c787434f","en":"5448d4bda936e08ff865a66c287b8cf7a72b1ba9504f6475e474ba14007adb14"},"history":{"earlier_supplied_English":"Rashi may interpret this verse to teach us that everything depends on the merit of each generation. Still, “The Torah has many faces” ( Bamidbar Rabbah 13:15) , and, “The scripture does not depart from its simple meaning” ( Shabbat 63a; Yebamot 24a) . King Solomon was the wisest of all men and spoke with Divine inspiration. He said that it is great foolishness to say, “The former times were better than these.” In every generation, there have been people who say this. But if you look closely into the matter, you will see that the world is constantly becoming more prosperous. People constantly live better and spend more than in the past.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/3"},"qualifications":[{"id":"author301-origin-sichos-308-position-3","owner":"sichos-308-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-3","englishUTF8SHA256":"5448d4bda936e08ff865a66c287b8cf7a72b1ba9504f6475e474ba14007adb14"}},{"owner":"sichos-308-position-4","section":308,"source_index":5,"array_position":4,"event_position":26,"group":"sichos308","anchor":"sichos-308-position-4","he":"ובאמת מאי נפקא מנה בזה? אדרבא, אם עכשו העולם בדחקות יותר צריכים לברח להשם יתברך ולעסק בתורה ועבודה. כי אין מקום לברח מצרות ויסורי עולם הזה רק אל השם יתברך ואל התורה כי \"אדם לעמל יולד\" (איוב ה) וכמו שכתוב במדרש (סנהדרין צט:): 'אדם לעמל יולד, אשרי מי שעמלו בתורה'.","he_nikud":"וּבֶאֱמֶת מַאי נָפְקָא מִנָּהּ בָּזֶה? אַדְּרַבָּא, אִם עַכְשָׁו הָעוֹלָם בְּדַחֲקוּת יוֹתֵר צְרִיכִים לִבְרֹחַ לְהַשֵּׁם יִתְבָּרַךְ וְלַעֲסֹק בְּתוֹרָה וַעֲבוֹדָה. כִּי אֵין מָקוֹם לִבְרֹחַ מִצָּרוֹת וְיִסּוּרֵי עוֹלָם הַזֶּה רַק אֶל הַשֵּׁם יִתְבָּרַךְ וְאֶל הַתּוֹרָה כִּי \"אָדָם לֶעָמָל יוּלָד\" (אִיּוּב ה) וּכְמוֹ שֶׁכָּתוּב בַּמִּדְרָשׁ (סַנְהֶדְרִין צט:): 'אָדָם לֶעָמָל יוּלָד, אַשְׁרֵי מִי שֶׁעֲמָלוֹ בַּתּוֹרָה'.","en":"And in truth, what difference does this make? On the contrary, if the world is now in greater straits, one must flee to God, blessed be He, and engage in Torah and service. For there is no place to flee from the troubles and sufferings of this world except to God, blessed be He, and to the Torah, for “man is born to toil” (Job 5). And as it is written in the Midrash (Sanhedrin 99b): ‘Man is born to toil; fortunate is one whose toil is in Torah.’","field_sha256":{"he":"d6de7b8f3d3c79cece0a53112faab56bf34ffb6a735dedbe56393460a6a12c08","he_nikud":"40a152f0b01a614d0cba1a4fa856967a763a3d269a9539e90cdd22a08bae51e7","en":"ef5b62283e108354aaa0c04704e872633852a90e1dad6290c8d80445dd54f69e"},"history":{"earlier_supplied_English":"What difference does it really make? If the world were really to be poorer now than before, that is all the more reason to flee to God and involve yourself in Torah and devotion. If there is suffering and trouble in the world, the only place to escape is to God and His Torah. It is written, “For man is born to struggle” (Job 5:7) . The Midrash remarks, “'Man is born to struggle': Happy is he who struggles with the Torah” (cf. Sanhedrin 99b) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/4"},"qualifications":[{"id":"author301-origin-sichos-308-position-4","owner":"sichos-308-position-4","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-308-position-4","owner":"sichos-308-position-4","placement":"after-owning-paragraph","role":"current-source-qualification","text":"Greater hardship is introduced conditionally; the following statement that refuge is in God and Torah is not conditional."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-4","englishUTF8SHA256":"ef5b62283e108354aaa0c04704e872633852a90e1dad6290c8d80445dd54f69e"}},{"owner":"sichos-308-position-5","section":308,"source_index":6,"array_position":5,"event_position":27,"group":"sichos308","anchor":"sichos-308-position-5","he":"פרוש: מאחר שאיך שיהיה, אם יהיה עשיר או עני וכו' אף על פי כן בודאי יהיה לו עמל וכעס כל ימיו כי צרות ויסורי כל אדם רבים מאד וכמו שכתוב \"גם כל ימיו כעס ומכאובות\" וכו' (קהלת ב־כג).","he_nikud":"פֵּרוּשׁ: מֵאַחַר שֶׁאֵיךְ שֶׁיִּהְיֶה, אִם יִהְיֶה עָשִׁיר אוֹ עָנִי וְכוּ' אַף עַל פִּי כֵן בְּוַדַּאי יִהְיֶה לוֹ עָמָל וָכַעַס כָּל יָמָיו כִּי צָרוֹת וְיִסּוּרֵי כָּל אָדָם רַבִּים מְאֹד וּכְמוֹ שֶׁכָּתוּב \"גַּם כָּל יָמָיו כַּעַס וּמַכְאוֹבוֹת\" וְכוּ' (קֹהֶלֶת ב־כג).","en":"The meaning is: since, however it may be, whether one is rich or poor, etc., nevertheless one will certainly have toil and vexation all one's days, for the troubles and sufferings of every person are very many. And as it is written: “And all his days are vexation and pain,” etc. (Ecclesiastes 2:23).","field_sha256":{"he":"c6777ed51eee57820156d11dd8b4f95e39a969863a60ff5429267c42e605c806","he_nikud":"591f60fc382b05235f816e8c5e48e8b2a4bb3ca48a06ecf39661581f94fd6580","en":"3de65abecc28e052bb8915be64b17d53117e68bd0d1461e1eb7cafe4fb6892ee"},"history":{"earlier_supplied_English":"Whether you are rich or poor, your life will be filled with toil and frustration. Man’s lot is suffering and pain, as it is written, “For all his days are vexatious and painful” (Ecclesiastes 2:23) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/5"},"qualifications":[{"id":"author301-origin-sichos-308-position-5","owner":"sichos-308-position-5","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-5","englishUTF8SHA256":"3de65abecc28e052bb8915be64b17d53117e68bd0d1461e1eb7cafe4fb6892ee"}},{"owner":"sichos-308-position-6","section":308,"source_index":7,"array_position":6,"event_position":28,"group":"sichos308","anchor":"sichos-308-position-6","he":"וכמובא בשל\"ה (ח\"ב קלח.) בלשון חרוז: \"אין רגע בלא פגע אין שעה וכו' אין יום וכו'\" על כן בודאי אשרי מי שבורח מזה העמל של פגעי העולם הזה אל עמל התורה, ואז בודאי אשרי וטוב לו בעולם הזה ובעולם הבא.","he_nikud":"וְכַמּוּבָא בַּשְּׁלָ\"ה (ח\"ב קלח.) בִּלְשׁוֹן חָרוּז: \"אֵין רֶגַע בְּלֹא פֶּגַע אֵין שָׁעָה וְכוּ' אֵין יוֹם וְכוּ'\" עַל כֵּן בְּוַדַּאי אַשְׁרֵי מִי שֶׁבּוֹרֵחַ מִזֶּה הֶעָמָל שֶׁל פִּגְעֵי הָעוֹלָם הַזֶּה אֶל עֲמַל הַתּוֹרָה, וְאָז בְּוַדַּאי אַשְׁרֵי וְטוֹב לוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.","en":"And as it is brought in the Shelah (part 2, 138a) in rhyme: “There is no moment without misfortune, no hour, etc., no day, etc.” Therefore, certainly fortunate is one who flees from this toil of the misfortunes of this world to the toil of Torah. And then certainly fortunate is he and it is good for him in this world and in the World to Come.","field_sha256":{"he":"a7654dcef555f8ab14b6800c5ed5c9f9f92e998e114965220f286eacfbfb0360","he_nikud":"c5e7a687694fcbc97f7715dece14d7962052cbb155f0e431555b623c0c27fbc9","en":"afaa1a285da3e52e9aba1ff6034e39e1566419b4e54c25362ee360839fc7273f"},"history":{"earlier_supplied_English":"In the holy Shelah , 376 Shelah 2:138a. See above, note 288. we find a verse: Ein rega belo pega Ein sha’ah belo ra’ah Ein yom belo reses ve'ayom There is no moment Without its torment There is no hour That is not sour There is no day Without dismay. Happy is the man who flees from the struggles of this troublesome world for the toil of Torah. He will be “happy and prosperous” – happy in this world and prosperous in the World to Come ( Avot 6:4; Berakhot 8a) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/6"},"qualifications":[{"id":"author301-origin-sichos-308-position-6","owner":"sichos-308-position-6","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-6","englishUTF8SHA256":"afaa1a285da3e52e9aba1ff6034e39e1566419b4e54c25362ee360839fc7273f"}},{"owner":"sichos-308-position-7","section":308,"source_index":8,"array_position":7,"event_position":29,"group":"sichos308","anchor":"sichos-308-position-7","he":"אבל בזה שאומר שהימים הראשונים היה טובים מאלה, ובגדל דאגתו וטרדתו וצערו על פרנסתו וממון בכל פעם יותר ויותר, בזה לא יפעל כלום רק מבלה ימיו בצער ודאגה וכעס ומכאובות ומבטל עצמו מהתורה ותפלה וכו' מחמת דאגות ושיחות ושטותים כאלו. ולבסוף (קהלת ה): \"מאומה לא ישא בעמלו\". כי (קהלת ו): \"בהבל בא ובחשך ילך\" וכו'.","he_nikud":"אֲבָל בָּזֶה שֶׁאוֹמֵר שֶׁהַיָּמִים הָרִאשׁוֹנִים הָיָה טוֹבִים מֵאֵלֶּה, וּבְגֹדֶל דַּאֲגָתוֹ וְטִרְדָּתוֹ וְצַעֲרוֹ עַל פַּרְנָסָתוֹ וּמָמוֹן בְּכָל פַּעַם יוֹתֵר וְיוֹתֵר, בָּזֶה לֹא יִפְעַל כְּלוּם רַק מְבַלֶּה יָמָיו בְּצַעַר וּדְאָגָה וְכַעַס וּמַכְאוֹבוֹת וּמְבַטֵּל עַצְמוֹ מֵהַתּוֹרָה וּתְפִלָּה וְכוּ' מֵחֲמַת דְּאָגוֹת וְשִׂיחוֹת וּשְׁטוּתִים כָּאֵלּוּ. וּלְבַסּוֹף (קֹהֶלֶת ה): \"מְאוּמָה לֹא יִשָּׂא בַּעֲמָלוֹ\". כִּי (קֹהֶלֶת ו): \"בְּהֶבֶל בָּא וּבַחֹשֶׁךְ יֵלֵךְ\" וְכוּ'.","en":"But by saying that the former days were better than these, and with his worry and preoccupation and pain about his livelihood and money growing greater and greater each time, he will accomplish nothing through this. He only spends his days in pain and worry and vexation and suffering, and keeps himself from Torah and prayer, etc., because of such worries and discussions and foolishness. And in the end (Ecclesiastes 5): “He will carry nothing away from his toil.” For (Ecclesiastes 6): “In vanity he comes, and in darkness he goes,” etc.","field_sha256":{"he":"e4c6cfe60f763f8a9229cb727f4d6d5b5bbcb814a252411e26c762df59521d1a","he_nikud":"4ffafa7ca609985a0e0c5ac7a79ab969596d63597e5a2fa1a08574ad521ef0fe","en":"fb2561faeefad4291a05cadf7f0101981e769c6fbdc89b4999b95112bdf966cd"},"history":{"earlier_supplied_English":"The person who says that “the first days are better than these” and worries, and is constantly anxious about his finances, accomplishes nothing. His attitude causes him to struggle more and more to earn a living and waste his days in worry and vexation. This foolishness keeps him from Torah and prayer, and regarding his end, it is written, “He takes away nothing for his effort” (Ecclesiastes 5:14) . It is also written, “For in vanity he comes, and in darkness he leaves” (ibid., 6:4) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/7"},"qualifications":[{"id":"author301-origin-sichos-308-position-7","owner":"sichos-308-position-7","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-7","englishUTF8SHA256":"fb2561faeefad4291a05cadf7f0101981e769c6fbdc89b4999b95112bdf966cd"}},{"owner":"sichos-308-position-8","section":308,"source_index":9,"array_position":8,"event_position":30,"group":"sichos308","anchor":"sichos-308-position-8","he":"כי באמת מי שיש לו עינים לראות ולב להבין האמת לאמתו יבין בשכל ויראה שגם בימים הראשונים היה העולם מלא דאגות וטרדות הפרנסה, וכמו שאנו רואים בכל הספרים שנתחברו לפני מאות שנים שרבם ככלם כותבים בהקדמותיהם שהיה להם צרות רבות בימיהם וחסרון כיס ודחקות הפרנסה הקשה מכלם, ואף על פי כן חברו ספרים קדושים הרבה כי (קהלת א): \"מה שהיה הוא שיהיה\" וכו'.","he_nikud":"כִּי בֶּאֱמֶת מִי שֶׁיֵּשׁ לוֹ עֵינַיִם לִרְאוֹת וְלֵב לְהָבִין הָאֱמֶת לַאֲמִתּוֹ יָבִין בְּשֵׂכֶל וְיִרְאֶה שֶׁגַּם בַּיָּמִים הָרִאשׁוֹנִים הָיָה הָעוֹלָם מָלֵא דַּאֲגוֹת וְטִרְדוֹת הַפַּרְנָסָה, וּכְמוֹ שֶׁאָנוּ רוֹאִים בְּכָל הַסְּפָרִים שֶׁנִּתְחַבְּרוּ לִפְנֵי מֵאוֹת שָׁנִים שֶׁרֻבָּם כְּכֻלָּם כּוֹתְבִים בְּהַקְדָּמוֹתֵיהֶם שֶׁהָיָה לָהֶם צָרוֹת רַבּוֹת בִּימֵיהֶם וְחֶסְרוֹן כִּיס וְדַחֲקוּת הַפַּרְנָסָה הַקָּשָׁה מִכֻּלָּם, וְאַף עַל פִּי כֵן חִבְּרוּ סְפָרִים קְדוֹשִׁים הַרְבֵּה כִּי (קֹהֶלֶת א): \"מַה שֶּׁהָיָה הוּא שֶׁיִּהְיֶה\" וְכוּ'.","en":"For in truth, one who has eyes to see and a heart to understand the truth in its fullness will understand with his intellect and see that in the former days too the world was full of worries and preoccupations about livelihood. And as we see in all the books composed hundreds of years ago, most—almost all—write in their introductions that they had many troubles in their days, and lack of money and the difficulty of livelihood were the hardest of them all. And nevertheless they composed many holy books, for (Ecclesiastes 1): “What was is what will be,” etc.","field_sha256":{"he":"0d3fe22670552c3632f620f7ca74083d20e8a031fd44e9ebb922772c76952a49","he_nikud":"2299e9f05a119394553f3b1bd75de7917c902ed9615c1dd2e9b8d90d327c14ef","en":"aa8ed6dfe7a62c31ce5991819122a054969a02710cdcee7b74e2b90bae45187b"},"history":{"earlier_supplied_English":"If you have eyes to see and a heart to understand, you will perceive that the past had as much suffering and troubles as the present. Look in books written hundreds of years ago and you will find that their authors also suffered from poverty and endured the most difficult struggles just to earn a livelihood. This did not deter them and they still wrote many holy books. It is written, “What was, that is what will be … there is nothing new under the sun” (ibid., 1:9) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/8"},"qualifications":[{"id":"author301-origin-sichos-308-position-8","owner":"sichos-308-position-8","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-8","englishUTF8SHA256":"aa8ed6dfe7a62c31ce5991819122a054969a02710cdcee7b74e2b90bae45187b"}},{"owner":"sichos-308-position-9","section":308,"source_index":10,"array_position":9,"event_position":31,"group":"sichos308","anchor":"sichos-308-position-9","he":"והכלל: שגם בימים הראשונים היה העולם מלא דאגות פרנסה כמו שכתב שלמה המלך, ע\"ה (קהלת ב): \"גם כל ימיו כעס ומכאובות\" וכו'. וכתיב \"אדם לעמל יולד קצר ימים ושבע רגז\" וכו'. וכיוצא כאלה פסוקים הרבה.","he_nikud":"וְהַכְּלָל: שֶׁגַּם בַּיָּמִים הָרִאשׁוֹנִים הָיָה הָעוֹלָם מָלֵא דַּאַגוֹת פַּרְנָסָה כְּמוֹ שֶׁכָּתַב שְׁלֹמֹה הַמֶּלֶךְ, ע\"ה (קֹהֶלֶת ב): \"גַּם כָּל יָמָיו כַּעַס וּמַכְאוֹבוֹת\" וְכוּ'. וּכְתִיב \"אָדָם לְעָמָל יוּלָד קְצַר יָמִים וּשְׂבַע רֹגֶז\" וְכוּ'. וְכַיּוֹצֵא כָּאֵלֶּה פְּסוּקִים הַרְבֵּה.","en":"And the general rule is that in the former days too the world was full of worries about livelihood, as King Solomon, peace be upon him, wrote (Ecclesiastes 2): “And all his days are vexation and pain,” etc. And it is written: “Man is born to toil, short of days and full of trouble,” etc. And there are many similar verses.","field_sha256":{"he":"e8e7700abb0acb69efe491165f16f8cfae7483380dc8b7eae1c7f3538456ee07","he_nikud":"b754fe9eac969a82198148e29527f4505218d160048eb10b8686cc0a1ea08bef","en":"024ba44c5d937e6b863f9a8d342292a787ba18fbdc709789240a927844881915"},"history":{"earlier_supplied_English":"Life was difficult even in the “good old days.” How many years ago did King Solomon write of man, “For all his days are vexation and pain”? How many years ago did the Book of Job say, “Man is born to struggle – of few days and full of trouble” (Job 14:1) ? The scriptures wrote about this long ago.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/9"},"qualifications":[{"id":"author301-origin-sichos-308-position-9","owner":"sichos-308-position-9","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-9","englishUTF8SHA256":"024ba44c5d937e6b863f9a8d342292a787ba18fbdc709789240a927844881915"}},{"owner":"sichos-308-position-10","section":308,"source_index":11,"array_position":10,"event_position":32,"group":"sichos308","anchor":"sichos-308-position-10","he":"וגם אז נדמה לכל אחד שבצוק העתים כאלה צריכים לדאג רק על הפרנסה ועל ידי זה אבדו ימיהם והלכו מן העולם בלא חמדה.","he_nikud":"וְגַם אָז נִדְמֶה לְכָל אֶחָד שֶׁבְּצוּק הָעִתִּים כָּאֵלֶּה צְרִיכִים לִדְאֹג רַק עַל הַפַּרְנָסָה וְעַל יְדֵי זֶה אָבְדוּ יְמֵיהֶם וְהָלְכוּ מִן הָעוֹלָם בְּלֹא חֶמְדָּה.","en":"And even then it seemed to each person that in such difficult times one must worry only about livelihood, and through this they lost their days and departed from the world without delight.","field_sha256":{"he":"db84f84aa81384ae88fa4ede25a81481c8fe0d07c38bc1996619ad54ba7a1ab4","he_nikud":"a99218d4f24f2cfcb918e05897bb15dfc6943b6795dd282b91126684c1bca8dd","en":"bb6f19de55a741f5c0314a104df3a3cc3fe8608f0244899dede0adc025bf873d"},"history":{"earlier_supplied_English":"Even then, many people thought that times were troublesome (Daniel 9:25) and that one must only worry about his livelihood. These people lost their days and departed from this world without joy or pleasure (II Chronicles 21:20) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/10"},"qualifications":[{"id":"author301-origin-sichos-308-position-10","owner":"sichos-308-position-10","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-10","englishUTF8SHA256":"bb6f19de55a741f5c0314a104df3a3cc3fe8608f0244899dede0adc025bf873d"}},{"owner":"sichos-308-position-11","section":308,"source_index":12,"array_position":11,"event_position":33,"group":"sichos308","anchor":"sichos-308-position-11","he":"ואף על פי כן נמצא בכל דור צדיקים ויראים וכשרים שלא השגיחו על זה וברחו מן העמל של עולם הזה לעמל התורה ועבודה וזכו להם ולדורותיהם וכו' אשרי להם.","he_nikud":"וְאַף עַל פִּי כֵן נִמְצָא בְּכָל דּוֹר צַדִּיקִים וִירֵאִים וּכְשֵׁרִים שֶׁלֹּא הִשְׁגִּיחוּ עַל זֶה וּבָרְחוּ מִן הֶעָמָל שֶׁל עוֹלָם הַזֶּה לַעֲמַל הַתּוֹרָה וַעֲבוֹדָה וְזָכוּ לָהֶם וּלְדוֹרוֹתֵיהֶם וְכוּ' אַשְׁרֵי לָהֶם.","en":"And nevertheless, in every generation there were righteous, God-fearing and upright people who paid no attention to this and fled from the toil of this world to the toil of Torah and service, and merited for themselves and for their generations, etc. Fortunate are they.","field_sha256":{"he":"33f4709bcd255f56161b88cf605a3ddef9090ca9edac39cb5a29eabf4b5b77ca","he_nikud":"8d10b101dd40633ea116a70065af12d526a10d523a07a3c1d3bda74a4099736d","en":"f739b5bf82f17d26613e43cea4deb0f3731acde7cc755e0077d6a850d172103d"},"history":{"earlier_supplied_English":"But each generation also had God-fearing men and tzaddikim. They paid no attention to these concerns and escaped the struggles of the world to toil in Torah and devotion. They achieved for themselves and for their children. Fortunate are they.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/11"},"qualifications":[{"id":"author301-origin-sichos-308-position-11","owner":"sichos-308-position-11","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-11","englishUTF8SHA256":"f739b5bf82f17d26613e43cea4deb0f3731acde7cc755e0077d6a850d172103d"}},{"owner":"sichos-308-position-12","section":308,"source_index":13,"array_position":12,"event_position":34,"group":"sichos308","anchor":"sichos-308-position-12","he":"וכן עכשו בודאי הבחירה חפשית ובודאי יש כח עתה גם עתה לכל אחד ואחד לברח מדאגות ושיחות של צער כאלה, לברח מהם ולבטח בה' ולקבל על עצמו עמל התורה תחת עמל המר של דאגת העולם הזה. ובודאי יפרנסו השם יתברך, כי השם יתברך מפרנס העולם תמיד כאז כן עתה. אדרבא, השם יתברך מנהיג העולם בכל פעם יפה יותר.","he_nikud":"וְכֵן עַכְשָׁו בְּוַדַּאי הַבְּחִירָה חָפְשִׁית וּבְוַדַּאי יֵשׁ כֹּחַ עַתָּה גַּם עַתָּה לְכָל אֶחָד וְאֶחָד לִבְרֹחַ מִדְּאָגוֹת וְשִׂיחוֹת שֶׁל צַעַר כָּאֵלֶּה, לִבְרֹחַ מֵהֶם וְלִבְטֹחַ בַּה' וּלְקַבֵּל עַל עַצְמוֹ עֲמַל הַתּוֹרָה תַּחַת עָמָל הַמַּר שֶׁל דַּאֲגַת הָעוֹלָם הַזֶּה. וּבְוַדַּאי יְפַרְנְסוֹ הַשֵּׁם יִתְבָּרַךְ, כִּי הַשֵּׁם יִתְבָּרַךְ מְפַרְנֵס הָעוֹלָם תָּמִיד כְּאָז כֵּן עַתָּה. אַדְּרַבָּא, הַשֵּׁם יִתְבָּרַךְ מַנְהִיג הָעוֹלָם בְּכָל פַּעַם יָפֶה יוֹתֵר.","en":"And likewise now, certainly choice is free, and certainly there is strength now, even now, for each and every person to flee from such worries and painful discussions—to flee from them and trust in God and take upon himself the toil of Torah in place of the bitter toil of worry about this world. And certainly God, blessed be He, will provide for him, for God, blessed be He, sustains the world always, then as now. On the contrary, God, blessed be He, directs the world more beautifully each time.","field_sha256":{"he":"a048b8cd9c2a5df2b4db541943f474c7c21ee1e56017c4dbbc2d4ed28e0dae1f","he_nikud":"6e9df062890db2dc44ef5dcd112674586f527b9eb0b22fe61d8f43da1df15300","en":"a8400082f6bf60615cd3c6dc509eb860dd51595598dae7dd8e5423a02e98c956"},"history":{"earlier_supplied_English":"Even today, you have free will. You have the power to escape from these painful discussions and from worries. You can flee from them and trust in God, abandoning the struggles of this bitter world and involving yourself in the work of Torah. God will certainly sustain you. Does He not sustain the entire world, now as always? And now God directs the world better than ever before.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/12"},"qualifications":[{"id":"author301-origin-sichos-308-position-12","owner":"sichos-308-position-12","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-12","englishUTF8SHA256":"a8400082f6bf60615cd3c6dc509eb860dd51595598dae7dd8e5423a02e98c956"}},{"owner":"sichos-308-position-13","section":308,"source_index":14,"array_position":13,"event_position":35,"group":"sichos308","anchor":"sichos-308-position-13","he":"הכלל: שהעולם הזה מלא דאגות ויגונות וצער ויסורים תמיד כמו אז כמו עתה וכמו שנגזר מחטא אדם הראשון (בראשית ג): \"בעצבון תאכלנה\", \"בזעת אפך תאכל לחם\". ואין מקום לברח מהעצבון והדאגות האלו המקצרים ומכלים ימי האדם, אין מקום לברח מהם כי אם אל השם יתברך ואל התורה וכנ\"ל.","he_nikud":"הַכְּלָל: שֶׁהָעוֹלָם הַזֶּה מָלֵא דְּאָגוֹת וִיגוֹנוֹת וְצַעַר וְיִסּוּרִים תָּמִיד כְּמוֹ אָז כְּמוֹ עַתָּה וּכְמוֹ שֶׁנִּגְזַר מֵחֵטְא אָדָם הָרִאשׁוֹן (בְּרֵאשִׁית ג): \"בְּעִצָּבוֹן תֹּאכֲלֶנָּה\", \"בְּזֵעַת אַפֶּךָ תֹּאכַל לֶחֶם\". וְאֵין מָקוֹם לִבְרֹחַ מֵהָעִצָּבוֹן וְהַדְּאָגוֹת הָאֵלּוּ הַמְקַצְּרִים וּמְכַלִּים יְמֵי הָאָדָם, אֵין מָקוֹם לִבְרֹחַ מֵהֶם כִּי אִם אֶל הַשֵּׁם יִתְבָּרַךְ וְאֶל הַתּוֹרָה וכנ\"ל.","en":"The general rule is that this world is always full of worries and sorrows and pain and sufferings, then as now, as was decreed because of the sin of the first Adam (Genesis 3): “In pain you shall eat of it,” “By the sweat of your brow you shall eat bread.” And there is no place to flee from this anguish and these worries that shorten and consume a person's days—there is no place to flee from them except to God, blessed be He, and to the Torah, as mentioned above.","field_sha256":{"he":"0d9b51b360cd8f91c200dcc53eac62b09b6975be57e21d1cec0f283cf852d192","he_nikud":"3bc8463805a8116dae29ac3fda0653e8caa57799e3f6ad0a9c92a0b9bdfc3dc1","en":"73b95b3c352218a450f381197966eb4aad31b4c7c5b451fe1656822012babfa2"},"history":{"earlier_supplied_English":"This world was always filled with worries and suffering. Things have not changed. It is written, “In pain you shall eat” (Genesis 3:17) , and, “By the sweat of your brow you shall eat bread” (ibid., 3:19) . This was decreed since Adam’s sin and there is no place to escape. These worries and pains destroy a man’s life; the only shelter is God and His Torah.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/13"},"qualifications":[{"id":"author301-origin-sichos-308-position-13","owner":"sichos-308-position-13","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-13","englishUTF8SHA256":"73b95b3c352218a450f381197966eb4aad31b4c7c5b451fe1656822012babfa2"}},{"owner":"sichos-308-position-14","section":308,"source_index":15,"array_position":14,"event_position":36,"group":"sichos308","anchor":"sichos-308-position-14","he":"וכבר דברנו, שזהו מה שאמרו רבותינו ז\"ל במשנה (אבות ו): 'כך הוא דרכה של תורה פת במלח תאכל, ומים במשורה תשתה, ועל הארץ תישן, וחיי צער תחיה, ובתורה אתה עמל. אם אתה עושה כן אשריך וטוב לך. אשריך בעולם הזה וטוב לך לעולם הבא'.","he_nikud":"וּכְבָר דִּבַּרְנוּ, שֶׁזֶּהוּ מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ ז\"ל בַּמִּשְׁנָה (אָבוֹת ו): 'כָּךְ הוּא דַּרְכָּהּ שֶׁל תּוֹרָה פַּת בַּמֶּלַח תֹּאכַל, וּמַיִם בַּמְּשׂוּרָה תִּשְׁתֶּה, וְעַל הָאָרֶץ תִּישַׁן, וְחַיֵּי צַעַר תִּחְיֶה, וּבַתּוֹרָה אַתָּה עָמֵל. אִם אַתָּה עוֹשֶׂה כֵּן אַשְׁרֶיךָ וְטוֹב לָךְ. אַשְׁרֶיךָ בָּעוֹלָם הַזֶּה וְטוֹב לָךְ לָעוֹלָם הַבָּא'.","en":"And we have already discussed that this is what our Sages, of blessed memory, said in the Mishnah (Avos 6): ‘Thus is the way of Torah: bread with salt you shall eat, and measured water you shall drink, and on the ground you shall sleep, and a life of privation you shall live, and in the Torah you toil. If you do so, fortunate are you and it is good for you. Fortunate are you in this world, and it is good for you in the World to Come.’","field_sha256":{"he":"a6c3388837f648e30aea50bf950085a3d233d181b2796e28db18c507c83c2002","he_nikud":"8ce04e61c836718a060715e14127ea8b290e69b490a2045be8cd7247b9046e87","en":"7a9bf90a84093023210a94a565ae8483606732c4190be3d5ad22ea09f851afc8"},"history":{"earlier_supplied_English":"The Mishnah teaches, “Thus is the way of Torah: Bread with salt you shall eat, measured water shall you drink, on the ground you shall sleep, and a life of privation you shall live, while in the Torah you shall toil. If you do so, 'you shall be happy, and it shall be good for you' (Psalms 128:2) . 'You shall be happy'. in this world – 'and it shall be good for you' in the World to Come” ( Avot 6:4) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/14"},"qualifications":[{"id":"author301-origin-sichos-308-position-14","owner":"sichos-308-position-14","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-14","englishUTF8SHA256":"7a9bf90a84093023210a94a565ae8483606732c4190be3d5ad22ea09f851afc8"}},{"owner":"sichos-308-position-15","section":308,"source_index":16,"array_position":15,"event_position":37,"group":"sichos308","anchor":"sichos-308-position-15","he":"ומקשין ההמון עם: איך שיך אשריך בעולם הזה מאחר שצריך לסבל עמל כזה לאכל פת במלח וכו'? וכבר מבאר באיזה ספרים איזה תרוצים דחוקים בדרך דרש, אבל באמת מי שיש לו עינים ולב להסתכל בעניני עולם הזה באמת, מי שזכה לינק באמת מתורותיו ושיחותיו ומעשיותיו הנוראים של רבנו הקדוש והנורא זכר צדיק וקדוש לברכה, אצלו מבאר המשנה בפשיטות גמור ויכולין להסביר הדבר לכל בר שכל אמתי הבקי קצת בטוב הנהגת העולם.","he_nikud":"וּמַקְשִׁין הַהֲמוֹן עָם: אֵיךְ שַׁיָּךְ אַשְׁרֶיךָ בָּעוֹלָם הַזֶּה מֵאַחַר שֶׁצָּרִיךְ לִסְבֹּל עָמָל כָּזֶה לֶאֱכֹל פַּת בַּמֶּלַח וְכוּ'? וּכְבָר מְבֹאָר בְּאֵיזֶה סְפָרִים אֵיזֶה תֵּרוּצִים דְּחוּקִים בְּדֶרֶךְ דְּרָשׁ, אֲבָל בֶּאֱמֶת מִי שֶׁיֵּשׁ לוֹ עֵינַיִם וְלֵב לְהִסְתַּכֵּל בְּעִנְיְנֵי עוֹלָם הַזֶּה בֶּאֱמֶת, מִי שֶׁזָּכָה לִינֹק בֶּאֱמֶת מִתּוֹרוֹתָיו וְשִׂיחוֹתָיו וּמַעֲשִׂיּוֹתָיו הַנּוֹרָאִים שֶׁל רַבֵּנוּ הַקָּדוֹשׁ וְהַנּוֹרָא זֵכֶר צַדִּיק וְקָדוֹשׁ לִבְרָכָה, אֶצְלוֹ מְבֹאָר הַמִּשְׁנָה בִּפְשִׁיטוּת גָּמוּר וִיכוֹלִין לְהַסְבִּיר הַדָּבָר לְכָל בַּר שֵׂכֶל אֲמִתִּי הַבָּקִי קְצָת בְּטוּב הַנְהָגַת הָעוֹלָם.","en":"And the common people object: how can ‘fortunate are you in this world’ apply when one must endure such toil, eating bread with salt, etc.? And some strained answers by way of homily have already been explained in some books. But in truth, one who has eyes and a heart to look truthfully at the matters of this world, one who has truly merited to draw nourishment from the awesome teachings and discussions and stories of our holy and awesome Rebbe, may the memory of the righteous and holy one be for a blessing—for him the Mishnah is explained with complete simplicity. And the matter can be explained to any person of true intellect who is somewhat familiar with the good conduct of the world.","field_sha256":{"he":"e46358c33d4087e8c0ad77b19314c940365de27182bd8f66e50041caa34c2a04","he_nikud":"6741a3ef2e778061b995114003b84ef8c38050b2b22f00665d0768ce46b997c4","en":"f56025448f7c4a510c3154dbd7aaccd1261f31c9fa5adc378fc60b4551e481a3"},"history":{"earlier_supplied_English":"People find this difficult to understand. After telling us the struggles we must endure – “bread with salt you shall eat” – how can the Mishnah state, “'You shall be happy' – in this world\"? Many writers attempt to resolve this by way of homily, but their explanations remain strained. In fact, there really is no question. If you have eyes to see and a heart that truly understands the world, you know this. If you have absorbed the wisdom contained in the Rebbe’s awesome teachings, you know the truth. The Mishnah means exactly what it says.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/15"},"qualifications":[{"id":"author301-origin-sichos-308-position-15","owner":"sichos-308-position-15","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-15","englishUTF8SHA256":"f56025448f7c4a510c3154dbd7aaccd1261f31c9fa5adc378fc60b4551e481a3"}},{"owner":"sichos-308-position-16","section":308,"source_index":17,"array_position":16,"event_position":38,"group":"sichos308","anchor":"sichos-308-position-16","he":"כי כל העשירים והגבירים הגדולים מודים שהעולם הזה מלא יגונות ויסורים. כי דאגותיהם ויסוריהם רבות מאד מאד בכל פעם ובכל יום ובכל שעה, וכמו שאמרו רבותינו ז\"ל (שם ב־ז): 'מרבה נכסים מרבה דאגה' ואף על פי שההמון עם העניים אינם מבינים זאת ונדמה להם שאם היה להם עשירות לא היה להם דאגות, אבל באמת הם טועים הרבה בזה וכנראה בחוש וכמו שאמרו רבותינו ז\"ל.","he_nikud":"כִּי כָּל הָעֲשִׁירִים וְהַגְּבִירִים הַגְּדוֹלִים מוֹדִים שֶׁהָעוֹלָם הַזֶּה מָלֵא יְגוֹנוֹת וְיִסּוּרִים. כִּי דַּאֲגוֹתֵיהֶם וְיִסּוּרֵיהֶם רַבּוֹת מְאֹד מְאֹד בְּכָל פַּעַם וּבְכָל יוֹם וּבְכָל שָׁעָה, וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ ז\"ל (שָׁם ב־ז): 'מַרְבֶּה נְכָסִים מַרְבֶּה דְּאָגָה' וְאַף עַל פִּי שֶׁהַהֲמוֹן עַם הָעֲנִיִּים אֵינָם מְבִינִים זֹאת וְנִדְמֶה לָהֶם שֶׁאִם הָיָה לָהֶם עֲשִׁירוּת לֹא הָיָה לָהֶם דְּאָגוֹת, אֲבָל בֶּאֱמֶת הֵם טוֹעִים הַרְבֵּה בָּזֶה וְכַנִּרְאֶה בְּחוּשׁ וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ ז\"ל.","en":"For all the wealthy and the great magnates acknowledge that this world is full of sorrows and sufferings. For their worries and sufferings are very, very many at every time and every day and every hour, as our Sages, of blessed memory, said (ibid., 2:7): ‘More possessions, more worry.’ And although the common poor people do not understand this and it seems to them that if they had wealth they would have no worries, in truth they are greatly mistaken about this, as is evident to the senses and as our Sages, of blessed memory, said.","field_sha256":{"he":"a5d30b500377272d5fc241f1f72515854fd3089c4450b9ffe2c1ad9d4cb24186","he_nikud":"37aaec28f6d6406568a51255a11fd6d685308786caf6ac5d527a61a029eed414","en":"11cbe379570879f8289311c2500252505fb7b6188d591fc9b8d54db6853eedbf"},"history":{"earlier_supplied_English":"The wealthiest men in the world will tell you that the world is filled with worry and suffering. The rich suffer as much as everyone else. Thus, our Sages teach, “The more possessions, the more worry” (ibid., 2:7) . The poor may not realize this. They may think that they would no longer have problems if they were wealthy. But they are sadly mistaken, as we can see with our own eyes. The truth is as our Sages have taught it. Whether you are rich or poor, you cannot avoid worries. The world is filled with pain and suffering and there is no avenue of escape.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/16"},"qualifications":[{"id":"author301-origin-sichos-308-position-16","owner":"sichos-308-position-16","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-16","englishUTF8SHA256":"11cbe379570879f8289311c2500252505fb7b6188d591fc9b8d54db6853eedbf"}},{"owner":"sichos-308-position-17","section":308,"source_index":18,"array_position":17,"event_position":39,"group":"sichos308","anchor":"sichos-308-position-17","he":"והעניים והבעלי בתים יש להם גם כן בודאי דאגות הרבה וכנזכר לעיל. על כן אין מקום לברח מיסורי עולם הזה המלא מכאובות יסורים מיסורים שונים, הן בענין פרנסה הן בענין צער ויסורים מאשתו ובניו, ולהנשים נדמה שיש להם מבעליהם יסורים, והן בענין יסורים ומכאובים ממש. שנמצאים הרבה סובלי חלאים ומכות מפלאות רחמנא לצלן בעולם הן על כל אלה וכיוצא בהם, אין מקום לברח מכל זה כי אם אל התורה.","he_nikud":"וְהָעֲנִיִּים וְהַבַּעֲלֵי בָּתִּים יֵשׁ לָהֶם גַּם כֵּן בְּוַדַּאי דְּאָגוֹת הַרְבֵּה וְכַנִּזְכַּר לְעֵיל. עַל כֵּן אֵין מָקוֹם לִבְרֹחַ מִיִּסּוּרֵי עוֹלָם הַזֶּה הַמָּלֵא מַכְאוֹבוֹת יִסּוּרִים מִיִּסּוּרִים שׁוֹנִים, הֵן בְּעִנְיַן פַּרְנָסָה הֵן בְּעִנְיַן צַעַר וְיִסּוּרִים מֵאִשְׁתּוֹ וּבָנָיו, וּלְהַנָּשִׁים נִדְמֶה שֶׁיֵּשׁ לָהֶם מִבַּעֲלֵיהֶם יִסּוּרִים, וְהֵן בְּעִנְיַן יִסּוּרִים וּמַכְאוֹבִים מַמָּשׁ. שֶׁנִּמְצָאִים הַרְבֵּה סוֹבְלֵי חֲלָאִים וּמַכּוֹת מֻפְלָאוֹת רַחֲמָנָא לִצְלַן בָּעוֹלָם הֵן עַל כָּל אֵלֶּה וְכַיּוֹצֵא בָּהֶם, אֵין מָקוֹם לִבְרֹחַ מִכָּל זֶה כִּי אִם אֶל הַתּוֹרָה.","en":"And the poor and the householders also certainly have many worries, as mentioned above. Therefore there is no place to flee from the sufferings of this world, which is full of pains and sufferings of various kinds: whether about livelihood, or about pain and suffering from one's wife and children—and women think that they have suffering from their husbands—or about actual sufferings and pains. For many who suffer from illnesses and extraordinary afflictions, the Merciful One protect us, are found in the world. From all these and the like, there is no place to flee from all of this except to the Torah.","field_sha256":{"he":"aa9b3e944c521e93eff111e03fd6a69285fbd5b797cdde3f3ce995dfbd1e0f0b","he_nikud":"da4025150cc668112347a8c75b6ed16b71f24ce958fa1bf6e9662a3694da1f39","en":"bf92ae58a70c57b3811986069c025ff507c96414842cfe6f467493f0e2ad0ba7"},"history":{"earlier_supplied_English":"If you are a man, you worry about earning a livelihood. You are concerned about your wife and children. If you are a woman, you imagine that you are troubled by your husband. Then, there is the real suffering and pain of those who suffer because of serious sickness and And misfortune. Heaven help us. There is no escape – except in the Torah.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/17"},"qualifications":[{"id":"author301-origin-sichos-308-position-17","owner":"sichos-308-position-17","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-17","englishUTF8SHA256":"bf92ae58a70c57b3811986069c025ff507c96414842cfe6f467493f0e2ad0ba7"}},{"owner":"sichos-308-position-18","section":308,"source_index":19,"array_position":18,"event_position":40,"group":"sichos308","anchor":"sichos-308-position-18","he":"כי כל מי שרוצה שיהיה לו טוב בעולם הזה שיחיה בנחת בלי צער הוא מלא צרות תמיד. כי כל מה שמקוה לטוב – בא להפך. ואפלו אם יהיה לו לפעמים איזה טוב מדמה, הוא בודאי מערב ביגונות תמיד כידוע בחוש למסתכל על האמת.","he_nikud":"כִּי כָּל מִי שֶׁרוֹצֶה שֶׁיִּהְיֶה לוֹ טוֹב בָּעוֹלָם הַזֶּה שֶׁיִּחְיֶה בְּנַחַת בְּלִי צַעַר הוּא מָלֵא צָרוֹת תָּמִיד. כִּי כָּל מַה שֶּׁמְּקַוֶּה לְטוֹב – בָּא לְהֵפֶךְ. וַאֲפִלּוּ אִם יִהְיֶה לוֹ לִפְעָמִים אֵיזֶה טוֹב מְדֻמֶּה, הוּא בְּוַדַּאי מְעֹרָב בִּיגוֹנוֹת תָּמִיד כַּיָּדוּעַ בְּחוּשׁ לַמִּסְתַּכֵּל עַל הָאֱמֶת.","en":"For everyone who wants to have good in this world, to live at ease without pain, is always full of troubles. For everything he hopes will be good turns out the opposite. And even if he sometimes has some imagined good, it is certainly always mixed with sorrows, as is evident to the senses of one who looks at the truth.","field_sha256":{"he":"2344600a3568a504c5f93e6bbfd45ad4e31f5341c38bd869210304c53b60a5ad","he_nikud":"e4c30cce955cd1480f145c8330758c62ab5f5a1b5345536e25e205f40ca7f6bd","en":"9d0e48ee5ef67859521ba98a4ff50298d13442092498854d811fec1600f46ca4"},"history":{"earlier_supplied_English":"If you desire the good of this world and want to live at ease without troubles, you will be constantly frustrated. The more you seek good, the more you will find the opposite. Everything you manage to grasp will be diluted with suffering. Look with truth and you will see this yourself.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/18"},"qualifications":[{"id":"author301-origin-sichos-308-position-18","owner":"sichos-308-position-18","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-18","englishUTF8SHA256":"9d0e48ee5ef67859521ba98a4ff50298d13442092498854d811fec1600f46ca4"}},{"owner":"sichos-308-position-19","section":308,"source_index":20,"array_position":19,"event_position":41,"group":"sichos308","anchor":"sichos-308-position-19","he":"על כן בעולם הזה \"אין חכמה ואין תבונה ואין עצה\" (משלי כא) לחיות בנחת, כי אם כשמתרצה באמת להסתפק בתכלית המעוט ולחיות חיי צער, כמו שאמרו שם במשנה הנ\"ל: פת במלח תאכל וכו'. שאז דיקא כשמקבל על עצמו כל הדחקות וחיי צער ולסבל הכל ולעסק בתורה כמו שכתוב שם: 'ובתורה אתה עמל', אז דיקא יש לו חיות גם בעולם הזה.","he_nikud":"עַל כֵּן בָּעוֹלָם הַזֶּה \"אֵין חָכְמָה וְאֵין תְּבוּנָה וְאֵין עֵצָה\" (מִשְׁלֵי כא) לִחְיוֹת בְּנַחַת, כִּי אִם כְּשֶׁמִּתְרַצֶּה בֶּאֱמֶת לְהִסְתַּפֵּק בְּתַכְלִית הַמִּעוּט וְלִחְיוֹת חַיֵּי צַעַר, כְּמוֹ שֶׁאָמְרוּ שָׁם בַּמִּשְׁנָה הַנַּ\"ל: פַּת בַּמֶּלַח תֹּאכַל וְכוּ'. שֶׁאָז דַּיְקָא כְּשֶׁמְּקַבֵּל עַל עַצְמוֹ כָּל הַדַּחֲקוּת וְחַיֵּי צַעַר וְלִסְבֹּל הַכֹּל וְלַעֲסֹק בַּתּוֹרָה כְּמוֹ שֶׁכָּתוּב שָׁם: 'וּבַתּוֹרָה אַתָּה עָמֵל', אָז דַּיְקָא יֵשׁ לוֹ חִיּוּת גַּם בָּעוֹלָם הַזֶּה.","en":"Therefore in this world “there is no wisdom and no understanding and no counsel” (Proverbs 21) for living at ease, except when one is truly willing to be satisfied with the absolute minimum and live a life of privation, as they said there in the above-mentioned Mishnah: bread with salt you shall eat, etc. For precisely then, when one accepts upon himself all the hardship and a life of privation, and to endure everything and engage in Torah, as it is written there: ‘and in the Torah you toil’—precisely then he has vitality even in this world.","field_sha256":{"he":"400889194f74da930dd39ceb50de477d58db9ea3e8b8cea46f0bf87ab1d7fdf0","he_nikud":"e82e5513f2a1fb3367e982d2c8f3ece49fceba49cfd58e0ebb821d3526e7508b","en":"4e542b51dba0cd9d8d99b3947ac0c1e845613821af070d10104135089968a405"},"history":{"earlier_supplied_English":"It is written, “There is no wisdom, understanding or counsel against God” (Proverbs 21:30) . The only way to be at ease is to be willing to subsist on an absolute minimum. Firmly resolve to follow the dictum of the Mishnah, “Bread with salt you shall eat … a life of privation shall you live.” Accept upon yourself a life of deprivation and hardship in order to involve yourself in the Torah – “in the Torah you shall toil.”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/19"},"qualifications":[{"id":"author301-origin-sichos-308-position-19","owner":"sichos-308-position-19","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-19","englishUTF8SHA256":"4e542b51dba0cd9d8d99b3947ac0c1e845613821af070d10104135089968a405"}},{"owner":"sichos-308-position-20","section":308,"source_index":21,"array_position":20,"event_position":42,"group":"sichos308","anchor":"sichos-308-position-20","he":"ואשרי לו גם בעולם הזה. כמו שכתוב שם 'אם אתה עושה כן אשריך בעולם הזה' ודאי.","he_nikud":"וְאַשְׁרֵי לוֹ גַּם בָּעוֹלָם הַזֶּה. כְּמוֹ שֶׁכָּתוּב שָׁם 'אִם אַתָּה עוֹשֶׂה כֵּן אַשְׁרֶיךָ בָּעוֹלָם הַזֶּה' וַדַּאי.","en":"And fortunate is he even in this world, as it is written there: ‘If you do so, fortunate are you in this world’—certainly.","field_sha256":{"he":"616936c9c900fb77c0cc075767060d0c441bdf1df8be00e8bab792af1866beba","he_nikud":"0c1dd44e62a4e9d01601a4398a8aa5629326a2a1861418b0370d9e5dcc810778","en":"31df9bca97aa568406e9d2688ffaddac42ea27cb3baea9810a1f83b5c504baeb"},"history":{"earlier_supplied_English":"Only then will you have life, even in this world. “If you do so, 'you shall be happy' … in this world.” This is certainly true.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/20"},"qualifications":[{"id":"author301-origin-sichos-308-position-20","owner":"sichos-308-position-20","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-20","englishUTF8SHA256":"31df9bca97aa568406e9d2688ffaddac42ea27cb3baea9810a1f83b5c504baeb"}},{"owner":"sichos-308-position-21","section":308,"source_index":22,"array_position":21,"event_position":43,"group":"sichos308","anchor":"sichos-308-position-21","he":"כי לא יהיה לו שום יסורים מפגעי העולם הזה המרבים אצל כל אדם מאד מאחר שמקבל על עצמו הכל בשביל התורה וכל חיותו וטובו הוא התורה שהוא טוב אמתי ואז בודאי חייו חיים אמתיים ואשרי לו גם בעולם הזה.","he_nikud":"כִּי לֹא יִהְיֶה לוֹ שׁוּם יִסּוּרִים מִפִּגְעֵי הָעוֹלָם הַזֶּה הַמְּרֻבִּים אֵצֶל כָּל אָדָם מְאֹד מֵאַחַר שֶׁמְּקַבֵּל עַל עַצְמוֹ הַכֹּל בִּשְׁבִיל הַתּוֹרָה וְכָל חִיּוּתוֹ וְטוּבוֹ הוּא הַתּוֹרָה שֶׁהוּא טוֹב אֲמִתִּי וְאָז בְּוַדַּאי חַיָּיו חַיִּים אֲמִתִּיִּים וְאַשְׁרֵי לוֹ גַּם בָּעוֹלָם הַזֶּה.","en":"For he will have no suffering from the misfortunes of this world, which are very numerous for every person, since he accepts everything upon himself for the sake of Torah. And all his vitality and good is the Torah, which is true good. And then certainly his life is true life, and fortunate is he even in this world.","field_sha256":{"he":"c4a6782167dec7e2130362dae539eb56105693654d148c31fa830c122ed85cf1","he_nikud":"d8237846cb65ecf91ff681f7c3fc3e402ba13c143a10b85d1bd9e5b3bd6a9cfa","en":"f35fe8c6176d18d192035433bc1b36aef0f6d2210dc57b3477b94f6d4d7d00ae"},"history":{"earlier_supplied_English":"No longer will you suffer from worldly troubles. You have already accepted them upon yourself for the sake of the Torah. All your life – all your good – is the true good. Thus, your life is a true life. Happy are you – even in this world.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/21"},"qualifications":[{"id":"author301-origin-sichos-308-position-21","owner":"sichos-308-position-21","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-21","englishUTF8SHA256":"f35fe8c6176d18d192035433bc1b36aef0f6d2210dc57b3477b94f6d4d7d00ae"}},{"owner":"sichos-308-position-22","section":308,"source_index":23,"array_position":22,"event_position":44,"group":"sichos308","anchor":"sichos-308-position-22","he":"אבל הרוצה תענוגי עולם הזה, ולחיות בנחת בעולם הזה, בודאי חייו מרים ומרורים מאד. כי אפלו 'רוח קימעא עוכרתו' (סוטה ה.). כי תכף כשבא עליו דבר נגד רצונו, יש לו צער ויסורים.","he_nikud":"אֲבָל הָרוֹצֶה תַּעֲנוּגֵי עוֹלָם הַזֶּה, וְלִחְיוֹת בְּנַחַת בָּעוֹלָם הַזֶּה, בְּוַדַּאי חַיָּיו מָרִים וּמְרוֹרִים מְאֹד. כִּי אֲפִלּוּ 'רוּחַ קִימְעָא עוֹכַרְתּוֹ' (סוֹטָה ה.). כִּי תֵּכֶף כְּשֶׁבָּא עָלָיו דָּבָר נֶגֶד רְצוֹנוֹ, יֵשׁ לוֹ צַעַר וְיִסּוּרִים.","en":"But one who wants the pleasures of this world and to live at ease in this world certainly has a very bitter and embittered life. For even ‘a slight breeze disturbs him’ (Sotah 5a). For immediately when something contrary to his will comes upon him, he has pain and suffering.","field_sha256":{"he":"95fa19afb8b37b3c4246ea1594781b6aa8167524ce562344716c172c00f3a76e","he_nikud":"fc35861b6c766b62a5e9696adbe7e5f24b8001b5c6baac4e80bcbbd7496c6057","en":"46b50aaf3172311f523fa8ccba3cc7c6f58c0c50b0345c9291a306b6c8ac07a6"},"history":{"earlier_supplied_English":"The man who wants to live at ease in this world and enjoy its delights will find only bitterness. “Even the slightest breeze will upset him” ( Sotah 5a) . The smallest happening contrary to his wishes will cause him to suffer greatly.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/22"},"qualifications":[{"id":"author301-origin-sichos-308-position-22","owner":"sichos-308-position-22","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-22","englishUTF8SHA256":"46b50aaf3172311f523fa8ccba3cc7c6f58c0c50b0345c9291a306b6c8ac07a6"}},{"owner":"sichos-308-position-23","section":308,"source_index":24,"array_position":23,"event_position":45,"group":"sichos308","anchor":"sichos-308-position-23","he":"וזה אי אפשר שיתנהג הכל כרצונו אפלו אם יהיה גביר ואדון ומושל, כי עולם הזה מלא יסורים כנ\"ל.","he_nikud":"וְזֶה אִי אֶפְשָׁר שֶׁיִּתְנַהֵג הַכֹּל כִּרְצוֹנוֹ אֲפִלּוּ אִם יִהְיֶה גְּבִיר וְאָדוֹן וּמוֹשֵׁל, כִּי עוֹלָם הַזֶּה מָלֵא יִסּוּרִים כַּנַּ\"ל.","en":"And it is impossible that everything should go according to his will, even if he is a magnate and a lord and a ruler, for this world is full of sufferings, as mentioned above.","field_sha256":{"he":"e9821f5b6c4ab7e496d84f4777fa71733ab50de39db0ad774d6a06ef0cf2add4","he_nikud":"3ae0e4712861f0f27f6563ce55e85aba5eed1313935bc385d1779f4465a9c90f","en":"055b672b4ebd9d2dbb71e6d83ef990e2bdc0fd086043055ba7dd64a166898e97"},"history":{"earlier_supplied_English":"You may be immensely rich and powerful. You may be a lord or a king. It is still impossible for everything to be as you want, in a world filled with suffering.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/23"},"qualifications":[{"id":"author301-origin-sichos-308-position-23","owner":"sichos-308-position-23","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-308-position-23","owner":"sichos-308-position-23","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew word translated “ruler” does not identify a particular office or person."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-23","englishUTF8SHA256":"055b672b4ebd9d2dbb71e6d83ef990e2bdc0fd086043055ba7dd64a166898e97"}},{"owner":"sichos-308-position-24","section":308,"source_index":25,"array_position":24,"event_position":46,"group":"sichos308","anchor":"sichos-308-position-24","he":"על כן אין מקום לברח מעמל עולם הזה, ויסוריו כי אם אל עמל התורה, לקבל על עצמו לילך בדרכה של התורה, לאכל פת במלח וכו'. ואז אשרי וטוב לו. אשריו בעולם הזה ודאי והדברים מובנים היטב לבקי קצת ביסורי עולם הזה ודאגותיו הרבים ומסתכל על האמת.","he_nikud":"עַל כֵּן אֵין מָקוֹם לִבְרֹחַ מֵעֲמַל עוֹלָם הַזֶּה, וְיִסּוּרָיו כִּי אִם אֶל עֲמַל הַתּוֹרָה, לְקַבֵּל עַל עַצְמוֹ לֵילֵךְ בְּדַרְכָּהּ שֶׁל הַתּוֹרָה, לֶאֱכֹל פַּת בַּמֶּלַח וְכוּ'. וְאָז אַשְׁרֵי וְטוֹב לוֹ. אַשְׁרָיו בָּעוֹלָם הַזֶּה וַדַּאי וְהַדְּבָרִים מוּבָנִים הֵיטֵב לַבָּקִי קְצָת בְּיִסּוּרֵי עוֹלָם הַזֶּה וְדַאֲגוֹתָיו הָרַבִּים וּמִסְתַּכֵּל עַל הָאֱמֶת.","en":"Therefore there is no place to flee from the toil of this world and its sufferings except to the toil of Torah: to accept upon oneself to walk in the way of Torah, to eat bread with salt, etc. And then fortunate is he and it is good for him. Fortunate is he in this world—certainly. And these matters are well understood by one who is somewhat familiar with the sufferings of this world and its many worries, and who looks at the truth.","field_sha256":{"he":"c96d74f1584b5fa91648413fcf814f8a20d685540c07f03850bde3bd09ab91df","he_nikud":"14e6a996bd97f5f7e5037d2dc6d84277c82ffc245ba7162a0aa4197f9604b335","en":"d0de8d063c8ab989f746a36beafcc6e607dfee5ea8a83e1da69280ff46a5a886"},"history":{"earlier_supplied_English":"The only way to escape this suffering is in the Torah. Accept the way of the Torah, eating bread with salt …. Then you will be happy and it will be good for you. Happy – even in this world. Look at the truth. Understand well the troubles of this world. You will certainly see the truth of this.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/24"},"qualifications":[{"id":"author301-origin-sichos-308-position-24","owner":"sichos-308-position-24","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-24","englishUTF8SHA256":"d0de8d063c8ab989f746a36beafcc6e607dfee5ea8a83e1da69280ff46a5a886"}},{"owner":"sichos-308-position-25","section":308,"source_index":26,"array_position":25,"event_position":47,"group":"sichos308","anchor":"sichos-308-position-25","he":"(ועין מזה בשיחותיו של רבנו ז\"ל, הנדפסים אצל הספורי מעשיות לעיל, ועין בהמעשה של החכם והתם וכו').","he_nikud":"(וְעַיֵּן מִזֶּה בְּשִׂיחוֹתָיו שֶׁל רַבֵּנוּ ז\"ל, הַנִּדְפָּסִים אֵצֶל הַסִּפּוּרֵי מַעֲשִׂיּוֹת לְעֵיל, וְעַיֵּן בְּהַמַּעֲשֶׂה שֶׁל הֶחָכָם וְהַתָּם וְכוּ').","en":"(And see about this in the discussions of our Rebbe, of blessed memory, printed with the Stories above; and see in the story of the Wise Man and the Simple Man, etc.)","field_sha256":{"he":"f0b43b864476a784ee68f8d6278da4db15fbc015c293e3b7a053f8252d86ddc0","he_nikud":"8bee6204251b1773a9ac337d4321c1155e6973ff365c1ca45487be9e514d706a","en":"5f12f26d51e499b868f32b0ca1842b73b9835ba9eba9cdc194e9440df18c329b"},"history":{"earlier_supplied_English":"You will find many of these [ideas] in the Rebbe’s teachings, especially those printed together with the Sipurey Ma'asiot . 377 All the Sichot up to #116 were originally printed with the Sipurey Ma'asiot . See note 298. They are also brought out most forcefully in the tale of “The Sophisticate and the Simpleton” ( Rabbi Nachman’s Stories #9) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/25"},"qualifications":[{"id":"author301-origin-sichos-308-position-25","owner":"sichos-308-position-25","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-25","englishUTF8SHA256":"5f12f26d51e499b868f32b0ca1842b73b9835ba9eba9cdc194e9440df18c329b"}},{"owner":"sichos-308-position-26","section":308,"source_index":27,"array_position":26,"event_position":48,"group":"sichos308","anchor":"sichos-308-position-26","he":"אפלו חכמי המחקרים של אמות העולם מודים לכל זה, שהעולם הזה מלא יסורים תמיד וכמבאר בספריהם הרבה מזה. ואמרו: שאין טוב בעולם הזה כי אם הסבל. דהינו שצריכין בעולם הזה לקבל על עצמו לסבל כל מה שיעבר עליו וכו'.","he_nikud":"אֲפִלּוּ חַכְמֵי הַמְחַקְּרִים שֶׁל אֻמּוֹת הָעוֹלָם מוֹדִים לְכָל זֶה, שֶׁהָעוֹלָם הַזֶּה מָלֵא יִסּוּרִים תָּמִיד וְכַמְבֹאָר בְּסִפְרֵיהֶם הַרְבֵּה מִזֶּה. וְאָמְרוּ: שֶׁאֵין טוֹב בָּעוֹלָם הַזֶּה כִּי אִם הַסֵּבֶל. דְּהַיְנוּ שֶׁצְּרִיכִין בָּעוֹלָם הַזֶּה לְקַבֵּל עַל עַצְמוֹ לִסְבֹּל כָּל מַה שֶּׁיַּעֲבֹר עָלָיו וְכוּ'.","en":"Even the scholars of inquiry among the nations of the world acknowledge all this: that this world is always full of sufferings, as much about this is explained in their books. And they said that there is no good in this world except endurance. That is, in this world one must accept upon oneself to endure everything that happens to one, etc.","field_sha256":{"he":"6ccc0f00da520169f753ee45169ad77d276262f11d3a11f44f62532b2d34d654","he_nikud":"01590612529a6a4eea1fd84fcaf7825ecc497c34432ce5dc363f6b66c0cc261d","en":"f0b1fe4d8f0fa60ac079641591a44f2b8901f1b3d0fc09bf0e8f0a3adda08a27"},"history":{"earlier_supplied_English":"Even pagan philosophers realized that the world is filled with suffering and discussed it often in their works. They came to the conclusion that the only solution is stoic forbearance. That person must accept upon himself to endure all that happens to him ( Alim LeTerufah #441) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/26"},"qualifications":[{"id":"author301-origin-sichos-308-position-26","owner":"sichos-308-position-26","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-26","englishUTF8SHA256":"f0b1fe4d8f0fa60ac079641591a44f2b8901f1b3d0fc09bf0e8f0a3adda08a27"}},{"owner":"sichos-308-position-27","section":308,"source_index":28,"array_position":27,"event_position":49,"group":"sichos308","anchor":"sichos-308-position-27","he":"אבל כל דבריהם אינם מועילים להעולם בלא התורה הקדושה שזכינו אנחנו בני ישראל. כי אין אדם זוכה לזה שיקבל על עצמו הסבל בעולם הזה ושלא יטרידוהו צרות העולם הזה כי אם על ידי התורה הקדושה.","he_nikud":"אֲבָל כָּל דִּבְרֵיהֶם אֵינָם מוֹעִילִים לְהָעוֹלָם בְּלֹא הַתּוֹרָה הַקְּדוֹשָׁה שֶׁזָּכִינוּ אֲנַחְנוּ בְּנֵי יִשְׂרָאֵל. כִּי אֵין אָדָם זוֹכֶה לָזֶה שֶׁיְּקַבֵּל עַל עַצְמוֹ הַסֵּבֶל בָּעוֹלָם הַזֶּה וְשֶׁלֹּא יַטְרִידוּהוּ צָרוֹת הָעוֹלָם הַזֶּה כִּי אִם עַל יְדֵי הַתּוֹרָה הַקְּדוֹשָׁה.","en":"But all their words are of no avail to the world without the holy Torah that we, the children of Israel, have merited. For no person merits to accept upon himself endurance in this world and not be disturbed by the troubles of this world except through the holy Torah.","field_sha256":{"he":"be4368fe41681c0490eee11a5e8191494ee087d4ec9d1067dbbca17eb0c80f5d","he_nikud":"06d0352ee640bab81e0cfbb0ac888988edec32ecdead89d81b620d2b40e3cea5","en":"79a3868cc9432b72ebf8b7365603c09e38d9fa20025674569d2c277b8ce75b9f"},"history":{"earlier_supplied_English":"But all their words are of no avail in a world without the Torah which we Jews have been fortunate to receive. No man can endure this world and not be overcome by its suffering. Only the Torah can provide this strength.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/27"},"qualifications":[{"id":"author301-origin-sichos-308-position-27","owner":"sichos-308-position-27","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-27","englishUTF8SHA256":"79a3868cc9432b72ebf8b7365603c09e38d9fa20025674569d2c277b8ce75b9f"}},{"owner":"sichos-308-position-28","section":308,"source_index":29,"array_position":28,"event_position":50,"group":"sichos308","anchor":"sichos-308-position-28","he":"כי כשמישב האדם עצמו היטב האמת לאמתו שהעולם הזה אינו שום תכלית כלל, כי אפלו אם היה עולם הזה מלא טובות ועשירות בלי שום יסורים וצער ודאגות כלל אף על פי כן הוא הבל וריק כי הזמן חולף ועובר כהרף עין (תהלים קמד): \"וימינו כצל עובר\" ולא כצלו של דקל וכו', וכמו שכתוב: \"ימי שנותינו בהם שבעים שנה וכו' ורהבם עמל ואון כי גז חיש ונעופה\".","he_nikud":"כִּי כְּשֶׁמְּיַשֵּׁב הָאָדָם עַצְמוֹ הֵיטֵב הָאֱמֶת לַאֲמִתּוֹ שֶׁהָעוֹלָם הַזֶּה אֵינוֹ שׁוּם תַּכְלִית כְּלָל, כִּי אֲפִלּוּ אִם הָיָה עוֹלָם הַזֶּה מָלֵא טוֹבוֹת וַעֲשִׁירוּת בְּלִי שׁוּם יִסּוּרִים וְצַעַר וּדְאָגוֹת כְּלָל אַף עַל פִּי כֵן הוּא הֶבֶל וָרִיק כִּי הַזְּמַן חוֹלֵף וְעוֹבֵר כְּהֶרֶף עַיִן (תְּהִלִּים קמד): \"וְיָמֵינוּ כְּצֵל עוֹבֵר\" וְלֹא כְצִלּוֹ שֶׁל דֶּקֶל וְכוּ', וּכְמוֹ שֶׁכָּתוּב: \"יְמֵי שְׁנוֹתֵינוּ בָהֶם שִׁבְעִים שָׁנָה וְכוּ' וְרָהְבָּם עָמָל וָאָוֶן כִּי גָז חִישׁ וַנָּעוּפָה\".","en":"For when a person thoroughly settles within himself the truth in its fullness that this world has no purpose whatsoever, [he recognizes that] even if this world were full of good things and wealth without any sufferings or pain or worries at all, nevertheless it would be vanity and emptiness, for time passes and goes in the blink of an eye (Psalms 144): “And our days are like a passing shadow”—and not like the shadow of a palm tree, etc. And as it is written: “The days of our years are seventy years, etc., and their pride is toil and sorrow, for it passes quickly and we fly away.”","field_sha256":{"he":"779a6f53ab2168811bf8c450e70c8f15079a64c0013a2327302f0a99cb0a8cff","he_nikud":"220402a6ddf598c2a17b29bc503155cbf082c15863779cc993b985fbc46b7599","en":"17ce1bae50ad45459742d63728374e8d82e20db0149ba31710d109e06c73bf6b"},"history":{"earlier_supplied_English":"Imagine a world filled with good and riches. Imagine a world in which there was no pain or suffering or worries. It would still be empty and devoid of all purpose. For time passes like the blink of an eye, and life is over. It is written, “Our days are like a passing shadow” (Psalms 144:4) . Our Sages comment that life is not even permanent, like the shadow of a palm tree (cf. Bereshit Rabbah 96:3; Kohelet Rabbah 1:3) . It is also written, “The days of our years are seventy years … their pride is travail and vanity, for it is speedily gone and flies away” (Psalms 90:10) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/28"},"qualifications":[{"id":"author301-origin-sichos-308-position-28","owner":"sichos-308-position-28","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-308-position-28","owner":"sichos-308-position-28","placement":"after-owning-paragraph","role":"current-source-qualification","text":"“[He recognizes that]” supplies an explanatory link after the opening “when a person settles the truth within himself”. Those bracketed words are explanatory supply, not a separate predicate in the supplied Hebrew. The supplied Hebrew syntax and abbreviated quotations are preserved."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-28","englishUTF8SHA256":"17ce1bae50ad45459742d63728374e8d82e20db0149ba31710d109e06c73bf6b"}},{"owner":"sichos-308-position-29","section":308,"source_index":30,"array_position":29,"event_position":51,"group":"sichos308","anchor":"sichos-308-position-29","he":"מכל שכן שגם כל העולם הזה מלא צער ויגונות ויסורים ודאגות וטרדות בלי שעור, מגדול ועד קטן, מן גדולי גדולי העשירים המפלגים עד תכלית עני שבעניים, כלם מלאים דאגות, וטרדות הוצאות פרנסתם, ושארי יסורים מיסורים שונים, וצרות והרפתקאות כידוע לכל. ואפלו קיסרים ומלכים ושרים גדולים מלאים דאגות ויסורים ופחדים רבים בלי שעור כידוע למי שבקי בהם ובדרכיהם.","he_nikud":"מִכָּל שֶׁכֵּן שֶׁגַּם כָּל הָעוֹלָם הַזֶּה מָלֵא צַעַר וִיגוֹנוֹת וְיִסּוּרִים וּדְאָגוֹת וּטְרָדוֹת בְּלִי שִׁעוּר, מִגָּדוֹל וְעַד קָטֹן, מִן גְּדוֹלֵי גְדוֹלֵי הָעֲשִׁירִים הַמֻּפְלָגִים עַד תַּכְלִית עָנִי שֶׁבָּעֲנִיִּים, כֻּלָּם מְלֵאִים דְּאָגוֹת, וּטְרָדוֹת הוֹצָאוֹת פַּרְנָסָתָם, וּשְׁאָרֵי יִסּוּרִים מִיִּסּוּרִים שׁוֹנִים, וְצָרוֹת וְהַרְפַּתְקָאוֹת כַּיָּדוּעַ לַכֹּל. וַאֲפִלּוּ קֵיסָרִים וּמְלָכִים וְשָׂרִים גְּדוֹלִים מְלֵאִים דְּאָגוֹת וְיִסּוּרִים וּפְחָדִים רַבִּים בְּלִי שִׁעוּר כַּיָּדוּעַ לְמִי שֶׁבָּקִי בָּהֶם וּבְדַרְכֵיהֶם.","en":"All the more so, since this whole world is also full of pain and sorrows and sufferings and worries and preoccupations without measure, from great to small, from the greatest of the exceedingly wealthy to the poorest of the poor. All are full of worries and preoccupations about the expenses of their livelihood, and other sufferings of various kinds, and troubles and mishaps, as is known to all. And even emperors and kings and great princes are full of worries and sufferings and many fears without measure, as is known to one familiar with them and their ways.","field_sha256":{"he":"4a2365cdda6f6d2b4424ffc1b83867ef2dfd1c4e60a1c7b0debeb369a52bdf25","he_nikud":"3a5eaf998915170c309b206141100143c63bfe638f90a97fc2af8dcb1997c0ae","en":"c8332bc484af2d901204adef4806c003b13419709f04f9f8b11b203edc9c80c0"},"history":{"earlier_supplied_English":"If even a perfect world would itself be purposeless, what shall we say about the world in which we live? It is filled with pain, sorrow and suffering without end. Every man’s life is filled with worries about finances and concerns, troubles and problems, from the greatest to the smallest, from the richest of the rich to the poorest of the poor. Every man is trapped by his limitations. The greatest emperors and kings are filled with worries and fears without measure, as is understood by those who know about their lives.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/29"},"qualifications":[{"id":"author301-origin-sichos-308-position-29","owner":"sichos-308-position-29","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-29","englishUTF8SHA256":"c8332bc484af2d901204adef4806c003b13419709f04f9f8b11b203edc9c80c0"}},{"owner":"sichos-308-position-30","section":308,"source_index":31,"array_position":30,"event_position":52,"group":"sichos308","anchor":"sichos-308-position-30","he":"וכל זה ידוע ומבאר אפלו לחכמי האמות העולם.","he_nikud":"וְכָל זֶה יָדוּעַ וּמְבֹאָר אֲפִלּוּ לְחַכְמֵי הָאֻמּוֹת הָעוֹלָם.","en":"And all this is known and explained even to the wise men of the nations of the world.","field_sha256":{"he":"69a7ca39236f384e2056a064282fc4db2ad45d20b3dabf8dc21f5a0380551347","he_nikud":"13fbde39ea5598feb003df5c7f87d559c9159007f1f5a590873c4dedebb82685","en":"71c8f5107e26fc23dec870e4eb1a1341035c58487d9f72c3f4987828d929fe6a"},"history":{"earlier_supplied_English":"Even the gentile wise men realized this.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/30"},"qualifications":[{"id":"author301-origin-sichos-308-position-30","owner":"sichos-308-position-30","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-30","englishUTF8SHA256":"71c8f5107e26fc23dec870e4eb1a1341035c58487d9f72c3f4987828d929fe6a"}},{"owner":"sichos-308-position-31","section":308,"source_index":32,"array_position":31,"event_position":53,"group":"sichos308","anchor":"sichos-308-position-31","he":"ואף על פי כן אין מי שיברח מזה כי אם כשבוחר חלקו בתורה ומצוות הקדושים, ומרצה להסתפק בתכלית המעוט מזה העולם כדי לעסק בתורה ולבלות ימיו על התורה ועל העבודה.","he_nikud":"וְאַף עַל פִּי כֵן אֵין מִי שֶׁיִּבְרַח מִזֶּה כִּי אִם כְּשֶׁבּוֹחֵר חֶלְקוֹ בְּתוֹרָה וּמִצְווֹת הַקְּדוֹשִׁים, וּמְרֻצֶּה לְהִסְתַּפֵּק בְּתַכְלִית הַמִּעוּט מִזֶּה הָעוֹלָם כְּדֵי לַעֲסֹק בַּתּוֹרָה וּלְבַלּוֹת יָמָיו עַל הַתּוֹרָה וְעַל הָעֲבוֹדָה.","en":"And nevertheless no one escapes from this except when he chooses his portion in Torah and the holy commandments, and is willing to be satisfied with the absolute minimum of this world in order to engage in Torah and spend his days on Torah and service.","field_sha256":{"he":"2b7e96b4cc04787fd6651232889f7ace7ca3b40032d455a4db07fc0f45c6bfe2","he_nikud":"32167eed76e8c4a691c50bb922b69e2336479dfb5346fc0c9557561d556f78a8","en":"7ad86c5c2fbcdd82912c5ba958ad4699ef6fc7511e3e9851370a456d560f17d7"},"history":{"earlier_supplied_English":"The only way out is to choose the Torah and its commandments. Make up your mind to be satisfied with an absolute minimum in order to immerse yourself in the Torah.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/31"},"qualifications":[{"id":"author301-origin-sichos-308-position-31","owner":"sichos-308-position-31","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-31","englishUTF8SHA256":"7ad86c5c2fbcdd82912c5ba958ad4699ef6fc7511e3e9851370a456d560f17d7"}},{"owner":"sichos-308-position-32","section":308,"source_index":33,"array_position":32,"event_position":54,"group":"sichos308","anchor":"sichos-308-position-32","he":"אז דיקא יכול לברח מן עמל העולם הזה, לפטר מעליו עמל ויגיעות וטרדות ומרירות נפש של דאגות העולם הזה, ולחיות חיים אמתיים בתורה ועבודת ה', אשר הוא עקר החיים האמתיים בעולם הזה ובעולם הבא.","he_nikud":"אָז דַּיְקָא יָכוֹל לִבְרֹחַ מִן עֲמַל הָעוֹלָם הַזֶּה, לִפְטֹר מֵעָלָיו עָמָל וִיגִיעוֹת וּטְרָדוֹת וּמְרִירוּת נֶפֶשׁ שֶׁל דַּאֲגוֹת הָעוֹלָם הַזֶּה, וְלִחְיוֹת חַיִּים אֲמִתִּיִּים בְּתוֹרָה וַעֲבוֹדַת ה', אֲשֶׁר הוּא עִקַּר הַחַיִּים הָאֲמִתִּיִּים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.","en":"Precisely then he can flee from the toil of this world, to free himself of the toil and labors and preoccupations and bitterness of soul of the worries of this world, and to live true life in Torah and the service of God, which is the essence of true life in this world and in the World to Come.","field_sha256":{"he":"a9ddb1b2f388d848e7943760d839eb2d508e3674cedc031e380d17bc6cb4a056","he_nikud":"000b22d79c21c5b06fc26fecb5e37645842a3b7391c466c006976b5f2976dffa","en":"490b0aeec7008860fe29816d18705f36bb484f0eadfb36c378b566e40844e775"},"history":{"earlier_supplied_English":"Spend your days with Torah and devotion and you will be immune to the world’s travail. You will shake off the toil and struggle of worldly concerns and no longer taste the bitterness and enxiety they have to offer. Devoted to God and His Torah, you will truly be alive, for this is the root of life, both in this world and the next.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/32"},"qualifications":[{"id":"author301-origin-sichos-308-position-32","owner":"sichos-308-position-32","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-32","englishUTF8SHA256":"490b0aeec7008860fe29816d18705f36bb484f0eadfb36c378b566e40844e775"}},{"owner":"sichos-308-position-33","section":308,"source_index":34,"array_position":33,"event_position":55,"group":"sichos308","anchor":"sichos-308-position-33","he":"ובודאי צדקו ונאמנו דברי המשנה הקדושה אפלו על פי פשוטה. שמי שבוחר לסבל בעולם הזה לאכל פת במלח ומים במשורה ישתה ועל הארץ יישן וחיי צער יחיה, כי אפלו פת במלח ומים במשורה לאו כל אדם זוכה בהרחבה, ועל כן הוא צריך עם כל זה להיות מרצה לחיות חיי צער, אבל כל זה הוא מקבל על עצמו כדי לעסק בתורה כמו שכתוב שם: 'ובתורה אתה עמל', אז אם עושה כן בודאי אשריך וטוב לך. אשריך בעולם הזה ודאי. כי בודאי יש לו חיות אמתי מאחר שמקבל על עצמו לסבל כל יסורי עולם הזה.","he_nikud":"וּבְוַדַּאי צָדְקוּ וְנֶאֶמְנוּ דִּבְרֵי הַמִּשְׁנָה הַקְּדוֹשָׁה אֲפִלּוּ עַל פִּי פְּשׁוּטָהּ. שֶׁמִּי שֶׁבּוֹחֵר לִסְבֹּל בָּעוֹלָם הַזֶּה לֶאֱכֹל פַּת בַּמֶּלַח וּמַיִם בַּמְּשׂוּרָה יִשְׁתֶּה וְעַל הָאָרֶץ יִישַׁן וְחַיֵּי צַעַר יִחְיֶה, כִּי אֲפִלּוּ פַּת בַּמֶּלַח וּמַיִם בַּמְּשׂוּרָה לָאו כָּל אָדָם זוֹכֶה בְּהַרְחָבָה, וְעַל כֵּן הוּא צָרִיךְ עִם כָּל זֶה לִהְיוֹת מְרֻצֶּה לִחְיוֹת חַיַּי צַעַר, אֲבָל כָּל זֶה הוּא מְקַבֵּל עַל עַצְמוֹ כְּדֵי לַעֲסֹק בַּתּוֹרָה כְּמוֹ שֶׁכָּתוּב שָׁם: 'וּבַתּוֹרָה אַתָּה עָמֵל', אָז אִם עוֹשֶׂה כֵּן בְּוַדַּאי אַשְׁרֶיךָ וְטוֹב לָךְ. אַשְׁרֶיךָ בָּעוֹלָם הַזֶּה וַדַּאי. כִּי בְּוַדַּאי יֵשׁ לוֹ חִיּוּת אֲמִתִּי מֵאַחַר שֶׁמְּקַבֵּל עַל עַצְמוֹ לִסְבֹּל כָּל יִסּוּרֵי עוֹלָם הַזֶּה.","en":"And certainly the words of the holy Mishnah are right and faithful even according to their plain meaning. If one chooses to endure in this world—to eat bread with salt, drink water by measure, sleep on the ground and live a life of privation—for not every person merits to have even bread with salt and water by measure in abundance, and therefore, with all this, he must be willing to live a life of privation—but accepts all this upon himself in order to engage in Torah, as it is written there: ‘and in the Torah you toil’, then, if he does so, certainly: fortunate are you and it is good for you. Fortunate are you in this world—certainly. For certainly he has true vitality, since he accepts upon himself to endure all the sufferings of this world.","field_sha256":{"he":"8478c9cb2d30896540b92a3e4615eac3a429175329047db0231ba4a30c8c1fea","he_nikud":"2dfbd6db2bed71dff4d37b9d3dbc1cfcd527163dd5a61a380288bdad25e43295","en":"26347c07705e406f8a185465cee26b1fffe31bf7c24e114b0ec46bffa6eb69e2"},"history":{"earlier_supplied_English":"You will then know that the words of the Mishnah are correct, even in their plain meaning. You will have chosen to live such a life, eating bread with salt, drinking water by measure, sleeping on the ground and living a life of privation. You must be willing to accept such a life, for there are times when even bread with salt and water by measure will not be abundant. But accept all this in order to immerse yourself in the Torah – “in the Torah you shall toil.” If you do this, you will certainly be “happy and it shall be good for you … happy in this world.” You will have accepted any suffering from this world and will be worthy of true life.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/33"},"qualifications":[{"id":"author301-origin-sichos-308-position-33","owner":"sichos-308-position-33","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-33","englishUTF8SHA256":"26347c07705e406f8a185465cee26b1fffe31bf7c24e114b0ec46bffa6eb69e2"}},{"owner":"sichos-308-position-34","section":308,"source_index":35,"array_position":34,"event_position":56,"group":"sichos308","anchor":"sichos-308-position-34","he":"וזכה להשיג האמת שהעולם הזה לא נברא בשביל נחת להתענג בו. אדרבא מי שרוצה להתענג בזה העולם הוא מלא יסורים וכעס ומכאובות וכנ\"ל. רק הוא בורח מעמל העולם הזה לעמל התורה אשר הוא חיינו וארך ימינו. אז לא די שיזכה לעולם הבא שהוא עולם הנצחי שכל העולם הזה אינו עולה כנגדו אפלו כהרף עין, אף גם בעולם הזה אשרי לו אשרי חלקו.","he_nikud":"וְזָכָה לְהַשִּׂיג הָאֱמֶת שֶׁהָעוֹלָם הַזֶּה לֹא נִבְרָא בִּשְׁבִיל נַחַת לְהִתְעַנֵּג בּוֹ. אַדְּרַבָּא מִי שֶׁרוֹצֶה לְהִתְעַנֵּג בְּזֶה הָעוֹלָם הוּא מָלֵא יִסּוּרִים וְכַעַס וּמַכְאוֹבוֹת וכנ\"ל. רַק הוּא בּוֹרֵחַ מֵעֲמַל הָעוֹלָם הַזֶּה לַעֲמַל הַתּוֹרָה אֲשֶׁר הוּא חַיֵּינוּ וְאֹרֶךְ יָמֵינוּ. אָז לֹא דַּי שֶׁיִּזְכֶּה לָעוֹלָם הַבָּא שֶׁהוּא עוֹלָם הַנִּצְחִי שֶׁכָּל הָעוֹלָם הַזֶּה אֵינוֹ עוֹלֶה כְּנֶגְדּוֹ אֲפִלּוּ כְּהֶרֶף עַיִן, אַף גַּם בָּעוֹלָם הַזֶּה אַשְׁרֵי לוֹ אַשְׁרֵי חֶלְקוֹ.","en":"And he has merited to grasp the truth that this world was not created for ease and enjoyment in it. On the contrary, one who wants to take pleasure in this world is full of sufferings and vexation and pain, as mentioned above. Rather, he flees from the toil of this world to the toil of Torah, which is our life and the length of our days. Then not only will he merit the World to Come, which is the eternal world, against which this whole world does not amount even to the blink of an eye, but also in this world fortunate is he, fortunate is his portion.","field_sha256":{"he":"f5aa7819fdf0f9629e695b17c4828f954c687f2326b8d8d0b8fb26a2b08e0bcf","he_nikud":"ee6e24de4e444ba93474bec5e63eef9c2e036e081089123e09cd6e8ea6f0547f","en":"dcfee0eb5cab984241d51ff8ac73d4701ea5eda4ef856996c59392a21bb88e86"},"history":{"earlier_supplied_English":"You will then be worthy of perceiving the truth and you will know that the world was not created for ease and enjoyment. You will realize that the man who seeks the delights of this world will find only pain and vexation. The Torah is our life and the length of our days. 378 Prayer before Evening Shma , from Deuteronomy 30:20. If you flee the struggles of the world to toil in the Torah, you will be worthy of the World to Come, whose eternity reduces all of this world to the blink of an eye in comparison. But besides this, you will also have a good life in this world.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/34"},"qualifications":[{"id":"author301-origin-sichos-308-position-34","owner":"sichos-308-position-34","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-34","englishUTF8SHA256":"dcfee0eb5cab984241d51ff8ac73d4701ea5eda4ef856996c59392a21bb88e86"}},{"owner":"sichos-308-position-35","section":308,"source_index":36,"array_position":35,"event_position":57,"group":"sichos308","anchor":"sichos-308-position-35","he":"כי בעולם הזה אין טוב כמו הסבל אבל אי אפשר לקבל הסבל של יסורי העולם הזה כי אם כשבורח אל עמל התורה והמצוות הקדושים וכנ\"ל. והדברים מבארים ומובנים מאד למי שחפץ באמת ואינו רוצה להטעות את עצמו.","he_nikud":"כִּי בָּעוֹלָם הַזֶּה אֵין טוֹב כְּמוֹ הַסֵּבֶל אֲבָל אִי אֶפְשָׁר לְקַבֵּל הַסֵּבֶל שֶׁל יִסּוּרֵי הָעוֹלָם הַזֶּה כִּי אִם כְּשֶׁבּוֹרֵחַ אֶל עֲמַל הַתּוֹרָה וְהַמִּצְווֹת הַקְּדוֹשִׁים וְכַּנַּ\"ל. וְהַדְּבָרִים מְבֹאָרִים וּמוּבָנִים מְאֹד לְמִי שֶׁחָפֵץ בָּאֱמֶת וְאֵינוֹ רוֹצֶה לְהַטְעוֹת אֶת עַצְמוֹ.","en":"For in this world there is no good like endurance. But it is impossible to accept endurance of the sufferings of this world except when one flees to the toil of Torah and the holy commandments, as mentioned above. And these matters are explained and very well understood by one who desires the truth and does not want to deceive himself.","field_sha256":{"he":"f8b43014ae8f38b8c9f2ffeb3e8c3dcf96524a3a9b09ea2e51004889cc11c7b1","he_nikud":"0974089bc317f6bdfab086bd6e47722497c11216c454dc744e83457bb767cfca","en":"a8fe9db149cd75567026035739a8f50e9c818b907ebc34472b93dafef8cc6cd2"},"history":{"earlier_supplied_English":"The best way to handle this world is forbearance. This cannot be attained except through immersion in the Torah and its commandments. Open your eyes to the truth and you will see this.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/35"},"qualifications":[{"id":"author301-origin-sichos-308-position-35","owner":"sichos-308-position-35","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-35","englishUTF8SHA256":"a8fe9db149cd75567026035739a8f50e9c818b907ebc34472b93dafef8cc6cd2"}},{"owner":"sichos-308-position-36","section":308,"source_index":37,"array_position":36,"event_position":58,"group":"sichos308","anchor":"sichos-308-position-36","he":"כי מי שמתלוצץ מדברים כאלו הוא מתלוצץ רק מעצמו, הינו שאינו רוצה לקבל עצותינו האמתיות ופונה ערפו אליהם. כי הוא רוצה רק לטבע ביון מצולת העולם הזה, ומי ימחה בידו, יאחז כל אחד דרכו (תהלים כ): \"ואנחנו בשם ה' אלקינו נזכיר\".","he_nikud":"כִּי מִי שֶׁמִּתְלוֹצֵץ מִדְּבָרִים כָּאֵלּוּ הוּא מִתְלוֹצֵץ רַק מֵעַצְמוֹ, הַיְנוּ שֶׁאֵינוֹ רוֹצֶה לְקַבֵּל עֲצוֹתֵינוּ הָאֲמִתִּיּוֹת וּפוֹנֶה עָרְפּוֹ אֲלֵיהֶם. כִּי הוּא רוֹצֶה רַק לִטְבֹּעַ בִּיוֵן מְצוּלַת הָעוֹלָם הַזֶּה, וּמִי יִמְחֶה בְּיָדוֹ, יֹאחֵז כָּל אֶחָד דַּרְכּוֹ (תְּהִלִּים כ): \"וַאֲנַחְנוּ בְּשֵׁם ה' אֱלֹקֵינוּ נַזְכִּיר\".","en":"For one who ridicules such matters ridicules only himself; that is, he does not want to accept our true counsel and turns his back on it. For he wants only to sink in the mire of the depths of this world, and who can prevent him? Let each person hold to his own path. (Psalms 20): “And we will invoke the name of the Lord our God.”","field_sha256":{"he":"ce3a5483e93091747eafe4867355d96cb5ea472482f802cbbabc2429f8829b8f","he_nikud":"3fd0d93937508b04f358ae763c8404546965957a0264fadf7f2df70e02198504","en":"9320760c97bdc008814f409e698a2f8988cea59170e652e4ca655e0f263dd79a"},"history":{"earlier_supplied_English":"Ridicule these words and you only ridicule yourself. We speak the truth and it is yours to accept. But if you wish to turn your back on it and remain immersed in the deep quicksand (Psalms 69:3) of this world, there is no one to prevent you. “Let each man go his own way, but we will call out in God’s name.”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/36"},"qualifications":[{"id":"author301-origin-sichos-308-position-36","owner":"sichos-308-position-36","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-36","englishUTF8SHA256":"9320760c97bdc008814f409e698a2f8988cea59170e652e4ca655e0f263dd79a"}},{"owner":"sichos-308-position-37","section":308,"source_index":38,"array_position":37,"event_position":59,"group":"sichos308","anchor":"sichos-308-position-37","he":"וכמו שאמר רבנו ז\"ל, על אחד שדבר עמו הרבה, וכונת רבנו ז\"ל, היה להוציאו ממקומות שנטבע בהם במים שאין להם סוף.","he_nikud":"וּכְמוֹ שֶׁאָמַר רַבֵּנוּ ז\"ל, עַל אֶחָד שֶׁדִּבֵּר עִמּוֹ הַרְבֵּה, וְכַוָּנַת רַבֵּנוּ ז\"ל, הָיָה לְהוֹצִיאוֹ מִמְּקוֹמוֹת שֶׁנִּטְבַּע בָּהֶם בְּמַיִם שֶׁאֵין לָהֶם סוֹף.","en":"And as our Rebbe, of blessed memory, said regarding a certain man, with whom there had been much conversation: our Rebbe, of blessed memory, intended to bring him out of the places in which he had sunk, in waters without end.","field_sha256":{"he":"a7f3a7000337b017d21d34e1987d85972c0b4f3a2e9c782a674069600da380a3","he_nikud":"c637279008834f9dede5f41128b970a4e40a453e65a47774d8af5ed2ab59edba","en":"f1ec8b971925e6cabef0d49926948d1da65478c09ccf569b1c81f0d189ddce48"},"history":{"earlier_supplied_English":"These were the Rebbe’s words to a man who spoke to him at length. The Rebbe knew that this man was drowning in the endless waters ( Yebamot 121a) and wanted to rescue him.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/37"},"qualifications":[{"id":"author301-origin-sichos-308-position-37","owner":"sichos-308-position-37","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-308-position-37","owner":"sichos-308-position-37","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew does not explicitly identify which participant spoke at length. The English leaves that speaker unstated; it does not adopt either earlier English account to decide the speaker or identify which preceding words are meant."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-37","englishUTF8SHA256":"f1ec8b971925e6cabef0d49926948d1da65478c09ccf569b1c81f0d189ddce48"}},{"owner":"sichos-308-position-38","section":308,"source_index":39,"array_position":38,"event_position":60,"group":"sichos308","anchor":"sichos-308-position-38","he":"אבל אותו האיש נתן כתף סוררת וחזק את לבו ולא קבל דברי רבנו ז\"ל, בלבו אף על פי שגם הוא הבין שדברי רבנו ז\"ל, אמתיים ונפלאים, אבל לא רצה לקבלם.","he_nikud":"אֲבָל אוֹתוֹ הָאִישׁ נָתַן כָּתֵף סוֹרֶרֶת וְחִזֵּק אֶת לִבּוֹ וְלֹא קִבֵּל דִּבְרֵי רַבֵּנוּ ז\"ל, בְּלִבּוֹ אַף עַל פִּי שֶׁגַּם הוּא הֵבִין שֶׁדִּבְרֵי רַבֵּנוּ ז\"ל, אֲמִתִּיִּים וְנִפְלָאִים, אֲבָל לֹא רָצָה לְקַבְּלָם.","en":"But that man gave a rebellious shoulder and hardened his heart, and did not accept the words of our Rebbe, of blessed memory, into his heart, even though he too understood that the words of our Rebbe, of blessed memory, were true and wondrous. But he did not want to accept them.","field_sha256":{"he":"12de37fb5cfc804e84496bbd8d811a1016d89e575184953e4ed4b60db355f21c","he_nikud":"4d547c65b7af4d7fc8948967c80f914456b2f6c09741d0237ba80187e99b4afa","en":"74afe811a30e7f8d015e2e0187187e0559d923a857fa08b05f70887ca7f94365"},"history":{"earlier_supplied_English":"But the man hardened his heart and turned a stubborn shoulder (Zechariah 7:11; Nehemiah 9:29) , not accepting the Rebbe’s advice. He knew the Rebbe spoke the truth, but refused to take his words to heart.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/38"},"qualifications":[{"id":"author301-origin-sichos-308-position-38","owner":"sichos-308-position-38","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-38","englishUTF8SHA256":"74afe811a30e7f8d015e2e0187187e0559d923a857fa08b05f70887ca7f94365"}},{"owner":"sichos-308-position-39","section":308,"source_index":40,"array_position":39,"event_position":61,"group":"sichos308","anchor":"sichos-308-position-39","he":"ענה ואמר רבנו ז\"ל: זה האיש דומה כמו מי שנטבע במים והולך לאבוד, ובא אחד ופושט ידו ורוצה להוציאו משם, והוא נותן כתף סוררת ופונה ערפו בעזות ואינו רוצה להניח את עצמו לתפס בו להוציאו, ובורח מן הבא להצילו.","he_nikud":"עָנָה וְאָמַר רַבֵּנוּ ז\"ל: זֶה הָאִישׁ דּוֹמֶה כְּמוֹ מִי שֶׁנִּטְבָּע בַּמַּיִם וְהוֹלֵךְ לְאִבּוּד, וּבָא אֶחָד וּפוֹשֵׁט יָדוֹ וְרוֹצֶה לְהוֹצִיאוֹ מִשָּׁם, וְהוּא נוֹתֵן כָּתֵף סוֹרֶרֶת וּפוֹנֶה עָרְפּוֹ בְּעַזּוּת וְאֵינוֹ רוֹצֶה לְהַנִּיחַ אֶת עַצְמוֹ לִתְפֹּס בּוֹ לְהוֹצִיאוֹ, וּבוֹרֵחַ מִן הַבָּא לְהַצִּילוֹ.","en":"Our Rebbe, of blessed memory, answered and said: “This man is like someone who is drowning in water and is going to perish. Someone comes and extends his hand and wants to take him out of there, but he gives a rebellious shoulder and turns his back brazenly, and does not want to allow himself to be grasped to be taken out, and flees from the one who comes to save him.”","field_sha256":{"he":"3f5d6d6beb9ad9d2ff0e2b9415b228c41fd7f0e8fd53fcac26033fa41c8735a6","he_nikud":"69259d1b429fcd3d918c25db236d13b1f07401665d43dfa8612fa70f14b82993","en":"6ef55bfce89a320ff5864f5baaed5932b4468c3421ae2ee98fa339a651238d0f"},"history":{"earlier_supplied_English":"The Rebbe said, “He is like a drowning man who is about to die. A rescuer comes along and extends a hand to lift him from the water. But the drowning man turns a stubborn shoulder and turns his back in arrogance, not wanting to grasp the helping hand. He flees from the one who comes to save him.”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/39"},"qualifications":[{"id":"author301-origin-sichos-308-position-39","owner":"sichos-308-position-39","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-39","englishUTF8SHA256":"6ef55bfce89a320ff5864f5baaed5932b4468c3421ae2ee98fa339a651238d0f"}},{"owner":"sichos-308-position-40","section":308,"source_index":41,"array_position":40,"event_position":62,"group":"sichos308","anchor":"sichos-308-position-40","he":"ולהשומע ינעם בעולם הזה ובעולם הבא:","he_nikud":"וּלְהַשּׁוֹמֵעַ יֻנְעַם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא:","en":"And for the one who heeds, may it be pleasant in this world and in the World to Come:","field_sha256":{"he":"af323d00d209fc966cb5f5d5b7339fc2c2cd544b8340d397dcc0304dbfa6c21f","he_nikud":"9119350ca3d1dd528e11d251cbcf85610bf04859040f941a9cd756244cbd80e9","en":"f7100f4a84ff904f2e5e104dd6e47aae2aad7c6226414704b8e3bd1c7b552a33"},"history":{"earlier_supplied_English":"Heed these words! You will find pleasure both in this world and the next. Finished and completed is the book of Rebbe Nachman's Wisdom with the help of the Blessed God","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/40"},"qualifications":[{"id":"author301-origin-sichos-308-position-40","owner":"sichos-308-position-40","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-308-position-40","owner":"sichos-308-position-40","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The earlier English includes a book-completion statement that is absent from both supplied Hebrew fields of this paragraph. It is preserved in full under the earlier English. Its original placement and ownership have not been established."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-40","englishUTF8SHA256":"f7100f4a84ff904f2e5e104dd6e47aae2aad7c6226414704b8e3bd1c7b552a33"}}],"assets":[{"name":"selected-63.json","url":"/reader/reviewed/sichos-301308-sources/selected-63.json","bytes":156595,"sha256":"16db92faf4beaabd5b83cde3fc0c7fc8eb2db09596de6605adbb6e17519b5b29"},{"name":"sicha-301-original.json","url":"/reader/reviewed/sichos-301308-sources/sicha-301-original.json","bytes":1921,"sha256":"74e1df7ba079cdeb38ef95dcabefb195f702c8b7dbc07e27e81b88657d554d60"},{"name":"sicha-302-original.json","url":"/reader/reviewed/sichos-301308-sources/sicha-302-original.json","bytes":1589,"sha256":"9bb1a110613a68c45b9f89a353db90a5cb840682675e2f02cecb8e96022c5150"},{"name":"sicha-303-original.json","url":"/reader/reviewed/sichos-301308-sources/sicha-303-original.json","bytes":3629,"sha256":"252155f9ad824e3829f2ff827500a2eeee8b3b52e4a0d56f68926f09907ebceb"},{"name":"sicha-304-original.json","url":"/reader/reviewed/sichos-301308-sources/sicha-304-original.json","bytes":4444,"sha256":"b8be79d9b9d41940299c084281d9b75bfb2e988ef20c7919d28c0b2c632b54ce"},{"name":"sicha-305-original.json","url":"/reader/reviewed/sichos-301308-sources/sicha-305-original.json","bytes":2630,"sha256":"703748f0347e62e66a46fc22ffef5c6f8ba959bfefe0f4e9cce26beab84d8e5e"},{"name":"sicha-306-original.json","url":"/reader/reviewed/sichos-301308-sources/sicha-306-original.json","bytes":6529,"sha256":"794cbf5c330c07961490b4e3807425a4e39fa70c9a9046c4ef525d025132b634"},{"name":"sicha-307-original.json","url":"/reader/reviewed/sichos-301308-sources/sicha-307-original.json","bytes":3905,"sha256":"e77014d02b21521d9fde91a1a7c63865d15971309a1b4cb539e99bd29cd5797c"},{"name":"sicha-308-original.json","url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","bytes":61969,"sha256":"dbe79336b12a6c7fa88a54cc7ec2fe68d2e265da079f1a413076b4b28fb2d2e2"}]};
const EXPECTED_BANK={"schema":"qualified-sichos-301308-selected/v1","route":"/reader/reviewed/sichos-301-308/","title":"Sichos HaRan — teachings 301–308","notice":"The supplied Hebrew texts are preserved independently. The current English follows the supplied Hebrew. Earlier English remains available as textual history.","globalQualifications":[{"id":"author301-global-independent-hebrew","placement":"before-owned-body","role":"global-reader-limitation","text":"The unpointed and pointed Hebrew are preserved as independent supplied texts. The English follows the unpointed Hebrew; source notes describe relevant uncertainties. Neither Hebrew text has been silently altered to agree with the other."},{"id":"author301-global-editorial-origin","placement":"before-owned-body","role":"global-reader-limitation","text":"The current English follows the supplied Hebrew. Earlier English is preserved separately as textual history, not as a second current translation."},{"id":"author301-global-citation-limits","placement":"before-owned-body","role":"global-reader-limitation","text":"References retain the detail supplied by the Hebrew, including chapter-only references, combined quotations and abbreviations. Retaining these references does not mean that they have been independently verified or that a reference attached to a combined quotation identifies each part. Additional explanations, identifications and more detailed references in the earlier English remain historical material and have not been independently verified here."},{"id":"author301-global-supplied-source-limits","placement":"before-owned-body","role":"global-reader-limitation","text":"These texts have not been verified against an original printed edition. Preserving the supplied spelling and vowel marks does not certify their accuracy."}],"rows":[{"owner":"sichos-301-position-0","section":301,"position":0,"source_index":1,"fields":{"he":"שמעתי בשמו שאמר: שעקר עבודת איש הישראלי הוא בחרף, לקום בחצות לילה. ובקיץ בעת שהלילה קצר מאד (שאז אין עומדין בחצות (בחוץ לארץ, כמבאר במקום אחר) אז יזהר לעמד בבקר השכם כעלות השחר.","he_nikud":"שָׁמַעְתִּי בִּשְׁמוֹ שֶׁאָמַר: שֶׁעִקָּר עֲבוֹדַת אִישׁ הַיִּשְׂרְאֵלִי הוּא בַּחֹרֶף, לָקוּם בַּחֲצוֹת לַיְלָה. וּבַקַּיִץ בְּעֵת שֶׁהַלַּיְלָה קָצָר מְאֹד (שֶׁאָז אֵין עוֹמְדִין בַּחֲצוֹת (בְּחוּץ לָאָרֶץ, כַּמְבֹאָר בְּמָקוֹם אַחֵר) אָז יִזָּהֵר לַעֲמֹד בַּבֹּקֶר הַשְׁכֵּם כַּעֲלוֹת הַשַּׁחַר.","en":"I heard in the Rebbe’s name that he said: A Jewish man’s main devotion in the winter is to wake up at midnight. And in the summer, when the night is very short (when one does not rise at midnight (in the Diaspora, as explained elsewhere), one should be careful to wake up early in the morning, at dawn."},"history":{"earlier_supplied_English":"I heard in the Rebbe’s name: A Jew’s main devotion in the winter is to wake up at midnight [and say Tikkun Chatzot , the midnight service (cf. Magen Avraham 1:4) ]. In the summer, when the nights are very short [and so awakening at midnight is not practiced in the Diaspora 370 See Likutey Moharan I, 149; Likutey Halakhot , Rosh HaShanah 3:7; She'arit Yisrael 125. ], one should still be careful to wake up early, at the crack of dawn.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-301-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author301-origin-sichos-301-position-0","owner":"sichos-301-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-301-position-0","owner":"sichos-301-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"Both supplied Hebrew fields have nested opening parentheses without a matching outer close; the English keeps that punctuation. “As explained elsewhere” has no more precise reference in this paragraph."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-301-position-0","englishUTF8SHA256":"54f1278e68c6a16a4417c0253ee8b75774a89905eca04346fc68a3e05c7a93e1"}},{"owner":"sichos-302-position-0","section":302,"position":0,"source_index":1,"fields":{"he":"פעם אחת עמדתי לפניו והוא ז\"ל היה מנח על מטתו ונזרקו דבורים אלו מתוך פיו הקדוש ואמר בזו הלשון: העקר הוא: מבטן שאול שועתי (דער עקר איז \"מבטן שאול שועתי\").","he_nikud":"פַּעַם אַחַת עָמַדְתִּי לְפָנָיו וְהוּא ז\"ל הָיָה מֻנָּח עַל מִטָּתוֹ וְנִזְרְקוּ דִּבּוּרִים אֵלּוּ מִתּוֹךְ פִּיו הַקָּדוֹשׁ וְאָמַר בְּזוֹ הַלָּשׁוֹן: הָעִקָּר הוּא: מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי (דֶּער עִקָּר אִיז \"מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי\").","en":"I was once standing before the Rebbe as he, of blessed memory, lay in his bed. These words flew out of his holy mouth, and he said in these words: The crucial thing is: “From the belly of Sheol I cried out” (in Yiddish: “The crucial thing is: ‘From the belly of Sheol I cried out’”)."},"history":{"earlier_supplied_English":"I was once standing before the Rebbe as he lay in his bed. These words flew out of his holy mouth: “ Der iker is: Mi-beten sheol shivati! – The crucial thing is: 'From the belly of hell I cried out!'” (Jonah 2:3; Alim LeTerufah #60) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-302-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author301-origin-sichos-302-position-0","owner":"sichos-302-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-302-position-0","owner":"sichos-302-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"Sheol names the biblical realm of the dead; “hell” is not used here as its exclusive equivalent. The source repeats the statement in Yiddish. Additional references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-302-position-0","englishUTF8SHA256":"b983df4537fb7c0004fc8dd562e5581c0cda65043d42289999003e07fd966d3a"}},{"owner":"sichos-303-position-0","section":303,"position":0,"source_index":1,"fields":{"he":"פעם אחת דבר עמי מענין מאוס תאוה הידוע.","he_nikud":"פַּעַם אַחַת דִּבֵּר עִמִּי מֵעִנְיַן מִאוּס תַּאֲוָה הַיָּדוּעַ.","en":"The Rebbe once spoke to me about the baseness of the well-known desire."},"history":{"earlier_supplied_English":"The Rebbe once spoke to me about the folly of sexual desires.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-303-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author301-origin-sichos-303-position-0","owner":"sichos-303-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-303-position-0","owner":"sichos-303-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew uses “the well-known desire”; the next paragraph discusses sexual misconduct. This paragraph retains the euphemism. An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-303-position-0","englishUTF8SHA256":"45a586b823849a75b29f3bf80776ec40a4ab2642f04559a43a4ce3ea9e54e7b9"}},{"owner":"sichos-303-position-1","section":303,"position":1,"source_index":2,"fields":{"he":"ואמר אז: מי שמהרהר בהרהורי נאוף הוא שוטה. כי הלא אפלו איש פשוט שקורין 'בעל הבית' הוא גם כן אינו חפץ שיהיה נתפס ח\"ו בענין זה. אפלו אם אינו ירא חטא כלל על כל פנים בודאי אינו רוצה שיהיה לו בזיון בזה שיתפסו אותו עם אשה אחרת.","he_nikud":"וְאָמַר אָז: מִי שֶׁמְּהַרְהֵר בְּהִרְהוּרֵי נִאוּף הוּא שׁוֹטֶה. כִּי הֲלֹא אֲפִלּוּ אִישׁ פָּשׁוּט שֶׁקּוֹרִין 'בַּעַל הַבַּיִת' הוּא גַּם כֵּן אֵינוֹ חָפֵץ שֶׁיִּהְיֶה נִתְפָּס ח\"ו בְּעִנְיָן זֶה. אֲפִלּוּ אִם אֵינוֹ יְרֵא חֵטְא כְּלָל עַל כָּל פָּנִים בְּוַדַּאי אֵינוֹ רוֹצֶה שֶׁיִּהְיֶה לוֹ בִּזָּיוֹן בָּזֶה שֶׁיִּתְפְּסוּ אוֹתוֹ עִם אִשָּׁה אַחֶרֶת.","en":"And he said then, “One who occupies himself with lewd thoughts is a fool. For surely even an ordinary person, called a ‘householder,’ would also not want to be caught, Heaven forbid, in this matter. Even if he has no fear of sin at all, at any rate, he certainly does not want the shame of being caught with another woman."},"history":{"earlier_supplied_English":"He said, “One who occupies himself with lewd thoughts is a fool. Even the most ordinary person would not want to be caught doing this. Even if he has no fear of sin, he still has no desire for the shame of being caught with another woman.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-303-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author301-origin-sichos-303-position-1","owner":"sichos-303-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-303-position-1","owner":"sichos-303-position-1","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The English quotation continues across paragraphs. The supplied Hebrew here has no matching opening quotation mark; the English does not establish the original printed punctuation. An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-303-position-1","englishUTF8SHA256":"81213b9193e27bfe806ae6fa09435fe33cf1bd3ca1d45f007790445b6b8167ca"}},{"owner":"sichos-303-position-2","section":303,"position":2,"source_index":3,"fields":{"he":"ואם כן למה לו להרהר ולצער נפשו בחנם?!","he_nikud":"וְאִם כֵּן לָמָּה לוֹ לְהַרְהֵר וּלְצַעֵר נַפְשׁוֹ בְּחִנָּם?!","en":"“So why engage in lustful thoughts? Why trouble your soul for nothing?”"},"history":{"earlier_supplied_English":"“So why engage in lustful thoughts? Why trouble your soul for nothing?”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-303-original.json","original_owner_pointer":"/segments/2"},"required_qualifications":[{"id":"author301-origin-sichos-303-position-2","owner":"sichos-303-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"The earlier English is retained verbatim."},{"id":"author301-source-note-1-sichos-303-position-2","owner":"sichos-303-position-2","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-303-position-2","englishUTF8SHA256":"568d74d69aa4c008fb55e95d27750354e8bfa7ce7cfd84ecdfd279db8180b831"}},{"owner":"sichos-303-position-3","section":303,"position":3,"source_index":4,"fields":{"he":"(וכבר מבאר שהמחשבה ביד האדם להטותה כרצונו וכו'. עין בספרים הנדפסים בכמה מקומות מזה ויערב לך לעד אם תרצה לקבלם באמת).","he_nikud":"(וּכְבָר מְבֹאָר שֶׁהַמַּחֲשָׁבָה בְּיַד הָאָדָם לְהַטּוֹתָה כִּרְצוֹנוֹ וְכוּ'. עַיֵּן בַּסְּפָרִים הַנִּדְפָּסִים בְּכַמָּה מְקוֹמוֹת מִזֶּה וְיֶעֱרַב לְךָ לָעַד אִם תִּרְצֶה לְקַבְּלָם בֶּאֱמֶת).","en":"(And it has already been explained that every person can control his thoughts and direct them as he wishes, etc. See the printed works in several places about this, and it will be pleasant for you forever if you are willing to accept them truly.)"},"history":{"earlier_supplied_English":"We have spoken of the fact that every person can control his thoughts and direct them as he wishes. This is discussed in numerous places in our printed works. 371 Likutey Moharan II, 50; Tzaddik #170; Likutey Halakhot , Bet HaKnesset 5:24; ibid., Minchah 7:10; ibid., Shiluach HaKen 4:2; Alim LeTerufah #6, #15, #117, #260, #295. Accept this advice and you will be worthy of eternal pleasure.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-303-original.json","original_owner_pointer":"/segments/3"},"required_qualifications":[{"id":"author301-origin-sichos-303-position-3","owner":"sichos-303-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-303-position-3","owner":"sichos-303-position-3","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew. Additional explanations and references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-303-position-3","englishUTF8SHA256":"1eafadb4ccb34c85406516dfde86d9e1874f4d5371da08b2781b8d9d9244a5fd"}},{"owner":"sichos-304-position-0","section":304,"position":0,"source_index":1,"fields":{"he":"פעם אחת התלוצץ מזה ואמר שעל זה מבקשים בכל יום \"ואל תביאני לידי נסיון ולא לידי בזיון\". ואמר בזו הלשון: אדער אה נסיון אדער אה בזיון (או נסיון, או בזיון). הינו כי אם לא יעמד בנסיון, יהיה לו בזיון.","he_nikud":"פַּעַם אַחַת הִתְלוֹצֵץ מִזֶּה וְאָמַר שֶׁעַל זֶה מְבַקְּשִׁים בְּכָל יוֹם \"וְאַל תְּבִיאֵנִי לִידֵי נִסָּיוֹן וְלֹא לִידֵי בִּזָּיוֹן\". וְאָמַר בְּזוֹ הַלָּשׁוֹן: אָדֶער אַה נִסָּיוֹן אָדֶער אַה בִּזָּיוֹן (אוֹ נִסָּיוֹן, אוֹ בִּזָּיוֹן). הַיְנוּ כִּי אִם לֹא יַעֲמֹד בַּנִּסָּיוֹן, יִהְיֶה לוֹ בִּזָּיוֹן.","en":"Once the Rebbe ridiculed this and said that concerning this one prays every day, “And do not bring me to a test, nor to disgrace.” And he said in these words, in Yiddish: “Either a test, or else disgrace” (either a test, or disgrace). That is, for if one does not pass the test, one will come to disgrace."},"history":{"earlier_supplied_English":"The Rebbe ridiculed the sexual desire, quoting the words of the morning prayer, “Do not bring me to a test or to disgrace.” He said, “ Ader a nisayon, ader a beziyon – Either a test, or else disgrace.” That is, if you do not pass the test, you will come to disgrace.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-304-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author301-origin-sichos-304-position-0","owner":"sichos-304-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-304-position-0","owner":"sichos-304-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew states the teaching, repeats it in Yiddish, and adds a parenthetical equivalent. The English preserves those repetitions. Additional references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-304-position-0","englishUTF8SHA256":"23a272ba0e4dd1666b87a204413bc0f28d8bfe8b0ab7ac7fb019e5ce352ef5e6"}},{"owner":"sichos-304-position-1","section":304,"position":1,"source_index":2,"fields":{"he":"וכבר מבאר קצת שספר הרבה מענין מאוס תאוה זאת ואמר שאינה תאוה כלל וכו'.","he_nikud":"וּכְבָר מְבֹאָר קְצָת שֶׁסִּפֵּר הַרְבֵּה מֵעִנְיַן מִאוּס תַּאֲוָה זֹאת וְאָמַר שֶׁאֵינָהּ תַּאֲוָה כְּלָל וְכוּ'.","en":"And it has already been partly explained that the Rebbe spoke much about the baseness of this desire, saying that it is really no desire at all, etc."},"history":{"earlier_supplied_English":"We have discussed how the Rebbe spoke of the baseness of this desire, saying that it is really no temptation at all (see “ His Praises ” #16; “ His Wisdom ” #51) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-304-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author301-origin-sichos-304-position-1","owner":"sichos-304-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-304-position-1","owner":"sichos-304-position-1","placement":"after-owning-paragraph","role":"current-source-qualification","text":"Additional explanations and references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-304-position-1","englishUTF8SHA256":"26bdcd9a1ad1607544d4787c294496f4cc233a2ca6145424a58885bf324aba14"}},{"owner":"sichos-304-position-2","section":304,"position":2,"source_index":3,"fields":{"he":"אחר כך אמר: שנמצאים הרבה שמעצם גשמיותם ורגילותם בענין זה, אין מועיל להם כלל מהש ממאסין להם ענין זה, אדרבא באיזה לשון שידברו עמהם מזה יתגברו עליהם ההרהורים יותר. על כן טוב לרב בני אדם לבלי להתחיל לחשב בזה כלל.","he_nikud":"אַחַר כָּךְ אָמַר: שֶׁנִּמְצָאִים הַרְבֵּה שֶׁמֵּעֹצֶם גַּשְׁמִיּוּתָם וּרְגִילוּתָם בְּעִנְיָן זֶה, אֵין מוֹעִיל לָהֶם כְּלָל מַהש ֶּׁמְּמָאֲסִין לָהֶם עִנְיָן זֶה, אַדְּרַבָּא בְּאֵיזֶה לָשׁוֹן שֶׁיְּדַבְּרוּ עִמָּהֶם מִזֶּה יִתְגַּבְּרוּ עֲלֵיהֶם הַהִרְהוּרִים יוֹתֵר. עַל כֵּן טוֹב לְרֹב בְּנֵי אָדָם לִבְלִי לְהַתְחִיל לַחֲשֹׁב בָּזֶה כְּלָל.","en":"Afterward the Rebbe said that there are many people whose bodily involvement and habituation in this matter are so great that explaining its baseness does not help them at all. On the contrary, in whatever language one speaks to them about it, their lewd thoughts become stronger. Therefore it is better for most people not to even begin to think of it at all."},"history":{"earlier_supplied_English":"The Rebbe said, “People are so bound up with their bodily desires, and tied to this one in particular, that it does not help when you explain how base this is. On the contrary, the more you speak of it, the more lewd thoughts they have. In most cases, it is therefore best not to even begin to think of it at all.”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-304-original.json","original_owner_pointer":"/segments/2"},"required_qualifications":[{"id":"author301-origin-sichos-304-position-2","owner":"sichos-304-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-304-position-2","owner":"sichos-304-position-2","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The unpointed Hebrew contains “מהש”, and the pointed text has an irregular corresponding sequence. Both supplied forms are preserved. The English renders the surrounding statement about explaining this matter’s baseness, without claiming a restored Hebrew reading. Additional references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-304-position-2","englishUTF8SHA256":"d60e06dd6279470ddec580346ca71219bf407fd2868c570161cfea10f0308689"}},{"owner":"sichos-304-position-3","section":304,"position":3,"source_index":4,"fields":{"he":"וכמבאר מזה בספר הא\"ב: אל תכנס עם פתוייך בטוען ונטען וכו'.","he_nikud":"וְכַמְבֹאָר מִזֶּה בְּסֵפֶר הא\"ב: אַל תִּכְנֹס עִם פִּתּוּיֶיךָ בְּטוֹעֵן וְנִטְעָן וְכוּ'.","en":"And as is explained about this in the Aleph-Bet Book: “Do not enter into litigation with your temptations,” etc."},"history":{"earlier_supplied_English":"This is explained in Sefer HaMidot : “Do not enter into litigation with your tempter. Thinking about something for any length of time, even of its avoidance, strengthens desire and turns one’s will towards it.” 372 The Aleph-Bet Book , Adultery and Immoral Behavior, A:10.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-304-original.json","original_owner_pointer":"/segments/3"},"required_qualifications":[{"id":"author301-origin-sichos-304-position-3","owner":"sichos-304-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-304-position-3","owner":"sichos-304-position-3","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew addresses plural “temptations”. The earlier English’s singular “tempter” and additional continuation remain accessible as historical wording, not as this paragraph’s current text. Additional references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-304-position-3","englishUTF8SHA256":"f547886b7bcb3c95c93b1a5a5e950fe7d3f41dacef6e687da2ea7ff11821015d"}},{"owner":"sichos-305-position-0","section":305,"position":0,"source_index":1,"fields":{"he":"שיך להשיחות ששמעתי ממנו ז\"ל כמה פעמים שאמר בזה הלשון: אין מה לעשות (מע האט גאר ניט צו טאהן).","he_nikud":"שַׁיָּךְ לְהַשִּׂיחוֹת שֶׁשָּׁמַעְתִּי מִמֶּנּוּ ז\"ל כַּמָּה פְּעָמִים שֶׁאָמַר בְּזֶה הַלָּשׁוֹן: אֵין מַה לַּעֲשׂוֹת (מֶע הָאט גָּאר נִיט צוּ טָאהן).","en":"This relates to the conversations I heard from the Rebbe, of blessed memory, many times when he said in these words: “There is nothing to do” (in Yiddish: “We have nothing at all to do”)."},"history":{"earlier_supplied_English":"Many times the Rebbe said, “ Me hat gar nit tzu tahn – We have nothing at all to do.”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-305-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author301-origin-sichos-305-position-0","owner":"sichos-305-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-305-position-0","owner":"sichos-305-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew describes repeated occasions without giving an exact number."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-305-position-0","englishUTF8SHA256":"30aabd602560bcedefd69d05d3809796a1b009eb2a5d302567c5ac4e399c528a"}},{"owner":"sichos-305-position-1","section":305,"position":1,"source_index":2,"fields":{"he":"(וכבר נדפסו (לעיל רסט רפז) כמה שיחות נפלאות) וכן מבאר בדברי רבותינו ז\"ל במנחות דף צ\"ט: \"תנא דבי רבי ישמעאל – דברי תורה לא יהיה עליך חובה ואי אתה רשאי לפטר עצמך מהן\".","he_nikud":"(וּכְבָר נִדְפְּסוּ (לְעֵיל רסט רפז) כַּמָּה שִׂיחוֹת נִפְלָאוֹת) וְכֵן מְבֹאָר בְּדִבְרֵי רַבּוֹתֵינוּ ז\"ל בִּמְנָחוֹת דַּף צ\"ט: \"תָּנָא דְּבֵי רַבִּי יִשְׁמָעֵאל – דִּבְרֵי תּוֹרָה לֹא יִהְיֶה עָלֶיךָ חוֹבָה וְאִי אַתָּה רַשַּׁאי לִפְטֹר עַצְמְךָ מֵהֶן\".","en":"(And several wondrous conversations have already been printed, above, 269 and 287.) And so it is explained in the words of our Sages, of blessed memory, in Menachos, page 99: “The school of Rabbi Ishmael taught: ‘The words of Torah should not be an obligation upon you, and you are not permitted to exempt yourself from them.’”"},"history":{"earlier_supplied_English":"[The Rebbe said this in relation to his conversations and many of them have already been printed]. We find in the Talmud that the disciples of Rabbi Ishmael taught, “The words of the Torah should not be viewed as an obligation, but one is not permitted to exempt oneself from them” ( Menachot 99b) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-305-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author301-origin-sichos-305-position-1","owner":"sichos-305-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-305-position-1","owner":"sichos-305-position-1","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The supplied Hebrew cites Menachos, page 99, without specifying a side. Earlier English gives 99b and an English comparison text gives 99a; neither side has been independently established here. The source also refers to teachings 269 and 287; those destinations have not been independently checked here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-305-position-1","englishUTF8SHA256":"89f55cf405f7611eab878d68bd03f0ac134fa463481f2d775cc719beb43503b5"}},{"owner":"sichos-305-position-2","section":305,"position":2,"source_index":3,"fields":{"he":"והוא עצה נפלאה למי שמבינה מעט.","he_nikud":"וְהוּא עֵצָה נִפְלָאָה לְמִי שֶׁמְּבִינָהּ מְעַט.","en":"And this is wonderful advice for one who understands it even a little."},"history":{"earlier_supplied_English":"This explains the Rebbe’s statement and is wonderful advice to he who understands it even a little.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-305-original.json","original_owner_pointer":"/segments/2"},"required_qualifications":[{"id":"author301-origin-sichos-305-position-2","owner":"sichos-305-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-305-position-2","englishUTF8SHA256":"62c0cf2aadfb942f1697984a6881b57fd0f5f335e24285b0dc650626d764f4d0"}},{"owner":"sichos-306-position-0","section":306,"position":0,"source_index":1,"fields":{"he":"שיך להא\"ב החדש אות ד' דעת סימן א' המתחיל: דע כי לכל העולמות ולכל נברא יש קומה מיחדת וכו', למשל מין האריה וכו'. וההבדלים כלם הם רמוזים בתמונת האותיות ובצרופיהם. והזוכה להבין את התורה וכו'.","he_nikud":"שַׁיָּךְ לְהָא\"ב הֶחָדָשׁ אוֹת ד' דַּעַת סִימָן א' הַמַּתְחִיל: דַּע כִּי לְכָל הָעוֹלָמוֹת וּלְכָל נִבְרָא יֵשׁ קוֹמָה מְיֻחֶדֶת וְכוּ', לְמָשָׁל מִין הָאַרְיֵה וְכוּ'. וְהַהֶבְדֵּלִים כֻּלָּם הֵם רְמוּזִים בִּתְמוּנַת הָאוֹתִיּוֹת וּבְצֵרוּפֵיהֶם. וְהַזּוֹכֶה לְהָבִין אֶת הַתּוֹרָה וְכוּ'.","en":"This relates to the new Aleph-Bet Book, letter dalet, Knowledge, item 1, which begins: “Know that every world and everything created has its own particular form, etc.; for example, the species of the lion, etc. And all the differences are alluded to in the forms of the letters and their combinations. And one who is worthy of understanding the Torah, etc.”"},"history":{"earlier_supplied_English":"In the second part of Sefer HaMidot, in the category of Da'at (Knowledge), it is written: “Every universe and everything created has its own particular form, … for example, the lion … and the differences between created beings are alluded to in the forms of the letters and their combinations. One who is worthy of understanding the Torah ….” 373 Ibid. , True Knowledge B:1. See Likutey Halakhot , Milah 5:24; ibid., Behemah Tehorah 4:23; Alim LeTerufah #205; Sichot VeSipurim , p. 84, #12.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-306-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author301-origin-sichos-306-position-0","owner":"sichos-306-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-306-position-0","owner":"sichos-306-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The source calls this the new Aleph-Bet Book, letter dalet, Knowledge, item 1. Identification with a particular second-part edition and additional references in the earlier English have not been independently established. An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-306-position-0","englishUTF8SHA256":"6a0689af0a072fe7f12a14f047a6077e055605a5bd5f40b738f8ea155a6cc7ec"}},{"owner":"sichos-306-position-1","section":306,"position":1,"source_index":2,"fields":{"he":"נראה לי שזהו ענין השיחה ששמעתי מפיו הקדוש קדם שבת חנכה תקס\"ה מענין הבריות של העולם, שכל התמונות והצורות של כל בני אדם כלם נכללים בתבת אדם הנאמר בתורה \"נעשה אדם\" (בראשית א־כו). כי בזו התבה אדם שאמר השם יתברך \"נעשה אדם\" בתבה זו בעצמה נכללים כל מיני התמונות של כל בני אדם שבעולם.","he_nikud":"נִרְאֵה לִי שֶׁזֶּהוּ עִנְיַן הַשִּׂיחָה שֶׁשָּׁמַעְתִּי מִפִּיו הַקָּדוֹשׁ קֹדֶם שַׁבָּת חֲנֻכָּה תקס\"ה מֵעִנְיַן הַבְּרִיּוֹת שֶׁל הָעוֹלָם, שֶׁכָּל הַתְּמוּנוֹת וְהַצּוּרוֹת שֶׁל כָּל בְּנֵי אָדָם כֻּלָּם נִכְלָלִים בְּתֵבַת אָדָם הַנֶּאֱמַר בַּתּוֹרָה \"נַעֲשֶׂה אָדָם\" (בְּרֵאשִׁית א־כו). כִּי בְּזוֹ הַתֵּבָה אָדָם שֶׁאָמַר הַשֵּׁם יִתְבָּרַךְ \"נַעֲשֶׂה אָדָם\" בְּתֵבָה זוֹ בְּעַצְמָהּ נִכְלָלִים כָּל מִינֵי הַתְּמוּנוֹת שֶׁל כָּל בְּנֵי אָדָם שֶׁבָּעוֹלָם.","en":"It appears to me that this is the subject of the conversation I heard from the Rebbe’s holy lips before Shabbat Chanukah 5565 regarding the creatures of the world: all the likenesses and forms of all human beings are included in the word adam (man) mentioned in the Torah, “Let us make man” (Genesis 1:26). For in this word adam, of which God, blessed be He, said “Let us make man,” in this very word are included all kinds of likenesses of all human beings in the world."},"history":{"earlier_supplied_English":"This appears to be related to a conversation we heard from Rebbe’s holy lips before Shabbat Chanukah 5565/1804, regarding the creatures in the world. 374 See Likutey Moharan I, 54:3. This lesson was revealed on that same Shabbat Chanukah . The Rebbe said, “Every human likeness is included in the word adam (man) as mentioned in the Torah. God said, ‘Let us make man ( adam ) in our image’ (Genesis 1:26) . As soon as He said the word adam , He included every human likeness in that word.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-306-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author301-origin-sichos-306-position-1","owner":"sichos-306-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-306-position-1","owner":"sichos-306-position-1","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew year תקס״ה is rendered 5565. The earlier English’s civil-year conversion and statement about another lesson’s revelation have not been independently verified here. An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-306-position-1","englishUTF8SHA256":"a26a1d44ea071e4c18857203086590af6f9a5ff4099d92688a58d93e57d2c32b"}},{"owner":"sichos-306-position-2","section":306,"position":2,"source_index":3,"fields":{"he":"וכן תבת בהמה וחיה וכו' הנאמר במעשה בראשית, בזו התבה גם כן נכלל כלהתמונות של כל בהמה וחיה וכן שאר הנבראים.","he_nikud":"וְכֵן תֵּבַת בְּהֵמָה וְחַיָּה וְכוּ' הַנֶּאֱמָר בְּמַעֲשֵׂה בְּרֵאשִׁית, בְּזוֹ הַתֵּבָה גַּם כֵּן נִכְלָל כָּלהַתְּמוּנוֹת שֶׁל כָּל בְּהֵמָה וְחַיָּה וְכֵן שְׁאָר הַנִּבְרָאִים.","en":"And likewise the word for animal and beast, etc., mentioned in the account of Creation: in this word too are included all the forms of every animal and beast, and likewise the other created beings."},"history":{"earlier_supplied_English":"“The same is true of such words as behemah (animal) and chayah (beast) used in the account of creation. These words include the forms of every animal and beast. The same is true of everything else created.”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-306-original.json","original_owner_pointer":"/segments/2"},"required_qualifications":[{"id":"author301-origin-sichos-306-position-2","owner":"sichos-306-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-306-position-2","owner":"sichos-306-position-2","placement":"after-owning-paragraph","role":"current-source-qualification","text":"Both supplied Hebrew fields fuse the words for “all the forms”. The source uses a singular “word” while naming animal categories; the English retains that number without reconstructing the Hebrew. An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-306-position-2","englishUTF8SHA256":"b93f754f7280528fb2af7a3b5ff8cb44f7d8437df48e3f864aeafca5066d3e86"}},{"owner":"sichos-306-position-3","section":306,"position":3,"source_index":4,"fields":{"he":"והאריך בשיחה זו.","he_nikud":"וְהֶאֱרִיךְ בְּשִׂיחָה זוֹ.","en":"And the Rebbe spoke at length on this topic."},"history":{"earlier_supplied_English":"The Rebbe spoke at length on this topic.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-306-original.json","original_owner_pointer":"/segments/3"},"required_qualifications":[{"id":"author301-origin-sichos-306-position-3","owner":"sichos-306-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-306-position-3","owner":"sichos-306-position-3","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-306-position-3","englishUTF8SHA256":"d7e7a4f0c574efc0cc3b502fe410e814dd94477c8a48693de780974c608098de"}},{"owner":"sichos-306-position-4","section":306,"position":4,"source_index":5,"fields":{"he":"ואמר אז: שיש חכמות אפלו בזה העולם שיכולין לחיות בהם לבד בלי שום אכילה ושתיה. כי יש דברים נפלאים וחכמות עליונות ונוראות אפלו בזה העולם שיכולין לחיות בהם לבד בלי שום אכילה ושתיה.","he_nikud":"וְאָמַר אָז: שֶׁיֵּשׁ חָכְמוֹת אֲפִלּוּ בְּזֶה הָעוֹלָם שֶׁיְּכוֹלִין לִחְיוֹת בָּהֶם לְבַד בְּלִי שׁוּם אֲכִילָה וּשְׁתִיָּה. כִּי יֵשׁ דְּבָרִים נִפְלָאִים וְחָכְמוֹת עֶלְיוֹנוֹת וְנוֹרָאוֹת אֲפִלּוּ בְּזֶה הָעוֹלָם שֶׁיְּכוֹלִין לִחְיוֹת בָּהֶם לְבַד בְּלִי שׁוּם אֲכִילָה וּשְׁתִיָּה.","en":"And he then said that there are categories of wisdom, even in this world, on which alone one can live, without any eating or drinking. For there are wonderful things and lofty and awesome categories of wisdom, even in this world, on which alone one can live, without any eating or drinking."},"history":{"earlier_supplied_English":"He then said, “There are categories of wisdom, even in this world, which can sustain a person without any other nourishment. There are such awesomely wonderful categories of wisdom even in this world. A man can live without eating or drinking with such wisdom alone” (see “ His Wisdom ” #181) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-306-original.json","original_owner_pointer":"/segments/4"},"required_qualifications":[{"id":"author301-origin-sichos-306-position-4","owner":"sichos-306-position-4","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-306-position-4","owner":"sichos-306-position-4","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew. Additional explanations and references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-306-position-4","englishUTF8SHA256":"abc33990d5f2eab58e97156d03c9f73a13b4d83b1b927938bdbdc0abdb13752d"}},{"owner":"sichos-306-position-5","section":306,"position":5,"source_index":6,"fields":{"he":"והאריך בשיחה זו הרבה ולא זכינו לכתבה:","he_nikud":"וְהֶאֱרִיךְ בְּשִׂיחָה זוֹ הַרְבֵּה וְלֹא זָכִינוּ לְכָתְבָהּ:","en":"And the Rebbe spoke at great length in this conversation, but we were not worthy of recording it:"},"history":{"earlier_supplied_English":"The Rebbe spoke at length, but we were not worthy of recording the rest.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-306-original.json","original_owner_pointer":"/segments/5"},"required_qualifications":[{"id":"author301-origin-sichos-306-position-5","owner":"sichos-306-position-5","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-306-position-5","owner":"sichos-306-position-5","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-306-position-5","englishUTF8SHA256":"b009d85fe46721610ed1ff4063b7ec52f3f598b6fadbdd653baf53176149723d"}},{"owner":"sichos-307-position-0","section":307,"position":0,"source_index":1,"fields":{"he":"לענין מה שדרך העולם לומר בכל שנה ובכל עת שעכשו אינם עתים טובות ובשנים הקודמים היה טוב יותר וכו'.","he_nikud":"לְעִנְיַן מַה שֶּׁדֶּרֶךְ הָעוֹלָם לוֹמַר בְּכָל שָׁנָה וּבְכָל עֵת שֶׁעַכְשָׁו אֵינָם עִתִּים טוֹבוֹת וּבַשָּׁנִים הַקּוֹדְמִים הָיָה טוֹב יוֹתֵר וְכוּ'.","en":"Regarding what people commonly say every year and at every time: times are not good now and previous years were better, etc."},"history":{"earlier_supplied_English":"Every year, people say that previous years were better and times are not as good as they were before.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-307-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author301-origin-sichos-307-position-0","owner":"sichos-307-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-307-position-0","owner":"sichos-307-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-307-position-0","englishUTF8SHA256":"22641acc36decf9c04ffc7b172e7c74b2139b7ed8fc862f06615ea67c247ac71"}},{"owner":"sichos-307-position-1","section":307,"position":1,"source_index":2,"fields":{"he":"כידוע שיחות כאלו בין רב העולם, דברנו עמו מזה הרבה. ורב השיחה היה שספרו לפניו הרבה שבימים הראשונים הטובים היה הכל בזול גדול הרבה יותר משל עכשו. כי לא היה אז נגידים ועשירים גדולים כמו עכשו. ומה שמוציא עכשו בעל הבית פשוט ואפלו מקבל חשוב הוא יותר מההוצאות של הנגידים, שבשנים הקודמים כידוע ומפרסם כל זה.","he_nikud":"כַּיָּדוּעַ שִׂיחוֹת כָּאֵלּוּ בֵּין רֹב הָעוֹלָם, דִּבַּרְנוּ עִמּוֹ מִזֶּה הַרְבֵּה. וְרֹב הַשִּׂיחָה הָיָה שֶׁסִּפְּרוּ לְפָנָיו הַרְבֵּה שֶׁבַּיָּמִים הָרִאשׁוֹנִים הַטּוֹבִים הָיָה הַכֹּל בְּזוֹל גָּדוֹל הַרְבֵּה יוֹתֵר מִשֶּׁל עַכְשָׁו. כִּי לֹא הָיָה אָז נְגִידִים וַעֲשִׁירִים גְּדוֹלִים כְּמוֹ עַכְשָׁו. וּמַה שֶּׁמּוֹצִיא עַכְשָׁו בַּעַל הַבַּיִת פָּשׁוּט וַאֲפִלּוּ מְקַבֵּל חָשׁוּב הוּא יוֹתֵר מֵהַהוֹצָאוֹת שֶׁל הַנְּגִידִים, שֶׁבַּשָּׁנִים הַקּוֹדְמִים כַּיָּדוּעַ וּמְפֻרְסָם כָּל זֶה.","en":"As is known, such discussions are common among most people; we spoke with him about this at length. Most of the conversation consisted of their telling him repeatedly that in the good old days everything was far cheaper than it is now. For there were not then great magnates and rich men as there are now. And what a simple householder, and even an important recipient [of support], spends now is more than the expenditures of the magnates in former years, as all this is well known and widely recognized."},"history":{"earlier_supplied_English":"The Rebbe spoke to us about this at length. He said that people might say that things were much cheaper in the good old days, but then again, people did not have as much money as they have now. A simple householder, even one living from charity, spends more today than the wealthy of yesteryear.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-307-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author301-origin-sichos-307-position-1","owner":"sichos-307-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-307-position-1","owner":"sichos-307-position-1","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew describes an “important recipient”; whether this refers to the recipient’s standing or the scale of what he receives is not clear. “[Of support]” is explanatory wording. The English leaves that distinction unresolved."},{"id":"author301-source-note-2-sichos-307-position-1","owner":"sichos-307-position-1","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew. Additional explanations and references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-307-position-1","englishUTF8SHA256":"727be8390c2f191cf343a2f55748a5c540673e0c5a828dcbcb0894f43ba5bac2"}},{"owner":"sichos-307-position-2","section":307,"position":2,"source_index":3,"fields":{"he":"ענה ואמר: הלא אדרבא, השם יתברך מנהיג עתה העולם יפה יותר מקדם! ואמר בזה הלשון: אדרבא דער אייבערשטער פירט היינט שעניר דיא וועלט.","he_nikud":"עָנָה וְאָמַר: הֲלֹא אַדְּרַבָּא, הַשֵּׁם יִתְבָּרַךְ מַנְהִיג עַתָּה הָעוֹלָם יָפֶה יוֹתֵר מִקֹּדֶם! וְאָמַר בְּזֶה הַלָּשׁוֹן: אַדְּרַבָּא דֶּער אֵייבֶּערְשְׁטֶער פִירְט הַיינְט שֶׁענֶיר דִיא וֶועלְט.","en":"The Rebbe answered, “Surely, on the contrary, God, blessed be He, now directs the world better than before!” And he said in these words, in Yiddish: “On the contrary, God now directs the world better.”"},"history":{"earlier_supplied_English":"He said, “ Aderaba. Der Eibershter firt heint sheiner die velt – The opposite is true. God now directs the world better than ever.” 375 See Sichot VeSipurim , p. 212, #33; above, note 192.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-307-original.json","original_owner_pointer":"/segments/2"},"required_qualifications":[{"id":"author301-origin-sichos-307-position-2","owner":"sichos-307-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-307-position-2","owner":"sichos-307-position-2","placement":"after-owning-paragraph","role":"current-source-qualification","text":"An English comparison text gives a different teaching under the same number and has not been used to replace this Hebrew. Additional explanations and references in the earlier English have not been independently verified here."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-307-position-2","englishUTF8SHA256":"6f95089329d3c5dc609331af42906a7d3912d219a3a75086c9739e1840e0cda4"}},{"owner":"sichos-308-position-0","section":308,"position":0,"source_index":1,"fields":{"he":"ויש לנו בזה שיחות הרבה, שכל דבורים ושיחות כאלו של העולם הכל הם מן היצר הרע, שמרבה שיחות כאלה להכביד הצער ולהגדיל דאגת הפרנסה כאלו עכשו ח\"ו, אפס תקוה.","he_nikud":"וְיֵשׁ לָנוּ בָּזֶה שִׂיחוֹת הַרְבֵּה, שֶׁכָּל דִּבּוּרִים וְשִׂיחוֹת כָּאֵלּוּ שֶׁל הָעוֹלָם הַכֹּל הֵם מִן הַיֵּצֶר הָרָע, שֶׁמַּרְבֶּה שִׂיחוֹת כָּאֵלֶּה לְהַכְבִּיד הַצַּעַר וּלְהַגְדִּיל דַּאֲגַת הַפַּרְנָסָה כְּאִלּוּ עַכְשָׁו ח\"ו, אָפֵס תִּקְוָה.","en":"And we have many discussions about this: all such words and discussions of the world are entirely from the evil inclination, which multiplies such discussions to increase the pain and magnify the worry about livelihood, as though now, Heaven forbid, there were no hope."},"history":{"earlier_supplied_English":"These are among the many thoughts which the Rebbe shared with us regarding the above. All this talk about the good old days is the work of the Evil One. He wants people to speak like this to make them suffer and worry all the more about their livelihoods. He would like to make them feel that there is no hope at all now, Heaven forbid.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/0"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-0","owner":"sichos-308-position-0","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-308-position-0","owner":"sichos-308-position-0","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The supplied Hebrew says “we have many discussions about this” without naming that plural speaking voice. The English retains “we” without attributing those words specifically to the Rebbe."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-0","englishUTF8SHA256":"f128bdcf73aac0160db3392e68bf0940b1dd41b3078443fea31741321c8fd557"}},{"owner":"sichos-308-position-1","section":308,"position":1,"source_index":2,"fields":{"he":"ובאמת הוא שקר וכזב כי השם יתברך מפרנס ומכלכל העולם תמיד ובכל דור ובכל שנה נמצאים עולים ויורדים. ואם נסתכל היטב בכל שנה ובכל עת, בודאי נמצא תמיד אנשים רבים שהיו עניים ומשרתים וכיוצא בשנים הקודמים, ועכשו נתעשרו. וגם הם רבם אומרים שהשנים אינם מתקנות עתה כמקדם, מחמת שרוצים בכל פעם עשירות יותר, ומנהיגים בביתם בגדולות יותר, עד שהוצאתם מרבה. ואומרים שעתה אינם שנים טובות כמקדם, אף על פי שאנו זוכרים שזה סמוך לפני איזה שנים היו עניים או משרתים וכיוצא בהם.","he_nikud":"וּבֶאֱמֶת הוּא שֶׁקֶר וְכָזָב כִּי הַשֵּׁם יִתְבָּרַךְ מְפַרְנֵס וּמְכַלְכֵּל הָעוֹלָם תָּמִיד וּבְכָל דּוֹר וּבְכָל שָׁנָה נִמְצָאִים עוֹלִים וְיוֹרְדִים. וְאִם נִסְתַּכֵּל הֵיטֵב בְּכָל שָׁנָה וּבְכָל עֵת, בְּוַדַּאי נִמְצָא תָּמִיד אֲנָשִׁים רַבִּים שֶׁהָיוּ עֲנִיִּים וּמְשָׁרְתִים וְכַיּוֹצֵא בַּשָּׁנִים הַקּוֹדְמִים, וְעַכְשָׁו נִתְעַשְּׁרוּ. וְגַם הֵם רֻבָּם אוֹמְרִים שֶׁהַשָּׁנִים אֵינָם מְתֻקָּנוֹת עַתָּה כְּמִקֹּדֶם, מֵחֲמַת שֶׁרוֹצִים בְּכָל פַּעַם עֲשִׁירוּת יוֹתֵר, וּמַנְהִיגִים בְּבֵיתָם בִּגְדוֹלוֹת יוֹתֵר, עַד שֶׁהוֹצָאָתָם מְרֻבָּה. וְאוֹמְרִים שֶׁעַתָּה אֵינָם שָׁנִים טוֹבוֹת כְּמִקֹּדֶם, אַף עַל פִּי שֶׁאָנוּ זוֹכְרִים שֶׁזֶּה סָמוּךְ לִפְנֵי אֵיזֶה שָׁנִים הָיוּ עֲנִיִּים אוֹ מְשָׁרְתִים וְכַיּוֹצֵא בָּהֶם.","en":"But in truth it is falsehood and lies, for God, blessed be He, continuously provides for and sustains the world, and in every generation and every year there are those who rise and those who fall. And if we look carefully at every year and every time, we will certainly always find many people who were poor and servants and the like in previous years and have now become wealthy. And even they, for the most part, say that times are not as good now as before, because they want more wealth each time and conduct their households on a grander scale, until their expenses are great. And they say that now the years are not as good as before, even though we remember that only some years ago they were poor or servants or the like."},"history":{"earlier_supplied_English":"This is all false. God continuously sustains the world and people rise and fall financially in every generation. If you look carefully at any period, you will find people who were poor, with menial jobs, who became wealthy. Yet they too claim that times are not as good as before – because they always want more. Now that they have tasted wealth, they are no longer satisfied and want more all the time. They now live ostentatiously and cannot meet their expenses, so they complain that times are not as good as before. But we ourselves recall that not too many years ago, most of these complainers were poor or working as domestics or the like.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/1"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-1","owner":"sichos-308-position-1","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-1","englishUTF8SHA256":"eca605b34885535164f2cc3373b344ba8a8f4687bd259ed6a5fa586b36bd8153"}},{"owner":"sichos-308-position-2","section":308,"position":2,"source_index":3,"fields":{"he":"ויהיה איך שיהיה, מאי נפקא מנה, מה שצועקים בכל פעם שהימים הראשונים היו טובים מאלה. וכבר צוח שלמה על זה וסתר דבריהם. ואמר (קהלת ז): \"אל תאמר שהימים הראשונים היו טובים מאלה, כי לא מחכמה שאלת על זה\".","he_nikud":"וְיִהְיֶה אֵיךְ שֶׁיִּהְיֶה, מַאי נָפְקָא מִנָּהּ, מַה שֶּׁצּוֹעֲקִים בְּכָל פַּעַם שֶׁהַיָּמִים הָרִאשׁוֹנִים הָיוּ טוֹבִים מֵאֵלֶּה. וּכְבָר צָוַח שְׁלֹמֹה עַל זֶה וְסָתַר דִּבְרֵיהֶם. וְאָמַר (קֹהֶלֶת ז): \"אַל תֹּאמַר שֶׁהַיָּמִים הָרִאשׁוֹנִים הָיוּ טוֹבִים מֵאֵלֶּה, כִּי לֹא מֵחָכְמָה שָׁאַלְתָּ עַל זֶה\".","en":"And however it may be, what difference does it make that they constantly cry out that the former days were better than these? Solomon already cried out about this and refuted their words. And he said (Ecclesiastes 7): “Do not say that the former days were better than these, for it is not out of wisdom that you ask about this.”"},"history":{"earlier_supplied_English":"Whether or not this is the fact, what use is it always to cry that the past was better? The wise King Solomon refuted this idea long ago when he said, “Do not say that the former times were better than these, for it is not out of wisdom that you ask this” (Ecclesiastes 7:10) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/2"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-2","owner":"sichos-308-position-2","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-2","englishUTF8SHA256":"9f597d05fc248779cb4252a5c1243a29d6ef73d237576515c9d1727af3a79af8"}},{"owner":"sichos-308-position-3","section":308,"position":3,"source_index":4,"fields":{"he":"ואף על פי שרש\"י פרש שם כי הכל לפי זכות הדורות, אף על פי כן הרבה פנים לתורה ואין מקרא יוצא מדי פשוטו, כי שלמה המלך, ע\"ה, שהיה חכם גדול מכל אדם אמר בחכמתו ורוח קדשו שזה שטות גדול מה שאומרים שהימים הראשונים היו טובים מאלה. כי בכל פעם אומרים כך. ובאמת אנו רואים שבכל פעם העולם נתעשר יותר, ומתנהג העולם בגדולות ובהוצאה מרבה יותר משנים קדמוניות:","he_nikud":"וְאַף עַל פִּי שֶׁרַשִׁ\"י פֵּרֵשׁ שָׁם כִּי הַכֹּל לְפִי זְכוּת הַדּוֹרוֹת, אַף עַל פִּי כֵן הַרְבֵּה פָּנִים לַתּוֹרָה וְאֵין מִקְרָא יוֹצֵא מִדֵּי פְּשׁוּטוֹ, כִּי שְׁלֹמֹה הַמֶּלֶךְ, ע\"ה, שֶׁהָיָה חָכָם גָּדוֹל מִכָּל אָדָם אָמַר בְּחָכְמָתוֹ וְרוּחַ קָדְשׁוֹ שֶׁזֶּה שְׁטוּת גָּדוֹל מַה שֶּׁאוֹמְרִים שֶׁהַיָּמִים הָרִאשׁוֹנִים הָיוּ טוֹבִים מֵאֵלֶּה. כִּי בְּכָל פַּעַם אוֹמְרִים כָּךְ. וּבֶאֱמֶת אָנוּ רוֹאִים שֶׁבְּכָל פַּעַם הָעוֹלָם נִתְעַשֵּׁר יוֹתֵר, וּמִתְנַהֵג הָעוֹלָם בִּגְדוֹלוֹת וּבְהוֹצָאָה מְרֻבָּה יוֹתֵר מִשָּׁנִים קַדְמוֹנִיּוֹת:","en":"And although Rashi explained there that everything depends on the merit of the generations, nevertheless the Torah has many faces, and scripture does not depart from its plain meaning. For King Solomon, peace be upon him, who was wiser than all men, said in his wisdom and holy spirit that it is great foolishness to say that the former days were better than these. For people say this all the time. And in truth we see that each time the world becomes wealthier and conducts itself on a grander scale and with greater expenditure than in earlier years:"},"history":{"earlier_supplied_English":"Rashi may interpret this verse to teach us that everything depends on the merit of each generation. Still, “The Torah has many faces” ( Bamidbar Rabbah 13:15) , and, “The scripture does not depart from its simple meaning” ( Shabbat 63a; Yebamot 24a) . King Solomon was the wisest of all men and spoke with Divine inspiration. He said that it is great foolishness to say, “The former times were better than these.” In every generation, there have been people who say this. But if you look closely into the matter, you will see that the world is constantly becoming more prosperous. People constantly live better and spend more than in the past.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/3"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-3","owner":"sichos-308-position-3","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-3","englishUTF8SHA256":"5448d4bda936e08ff865a66c287b8cf7a72b1ba9504f6475e474ba14007adb14"}},{"owner":"sichos-308-position-4","section":308,"position":4,"source_index":5,"fields":{"he":"ובאמת מאי נפקא מנה בזה? אדרבא, אם עכשו העולם בדחקות יותר צריכים לברח להשם יתברך ולעסק בתורה ועבודה. כי אין מקום לברח מצרות ויסורי עולם הזה רק אל השם יתברך ואל התורה כי \"אדם לעמל יולד\" (איוב ה) וכמו שכתוב במדרש (סנהדרין צט:): 'אדם לעמל יולד, אשרי מי שעמלו בתורה'.","he_nikud":"וּבֶאֱמֶת מַאי נָפְקָא מִנָּהּ בָּזֶה? אַדְּרַבָּא, אִם עַכְשָׁו הָעוֹלָם בְּדַחֲקוּת יוֹתֵר צְרִיכִים לִבְרֹחַ לְהַשֵּׁם יִתְבָּרַךְ וְלַעֲסֹק בְּתוֹרָה וַעֲבוֹדָה. כִּי אֵין מָקוֹם לִבְרֹחַ מִצָּרוֹת וְיִסּוּרֵי עוֹלָם הַזֶּה רַק אֶל הַשֵּׁם יִתְבָּרַךְ וְאֶל הַתּוֹרָה כִּי \"אָדָם לֶעָמָל יוּלָד\" (אִיּוּב ה) וּכְמוֹ שֶׁכָּתוּב בַּמִּדְרָשׁ (סַנְהֶדְרִין צט:): 'אָדָם לֶעָמָל יוּלָד, אַשְׁרֵי מִי שֶׁעֲמָלוֹ בַּתּוֹרָה'.","en":"And in truth, what difference does this make? On the contrary, if the world is now in greater straits, one must flee to God, blessed be He, and engage in Torah and service. For there is no place to flee from the troubles and sufferings of this world except to God, blessed be He, and to the Torah, for “man is born to toil” (Job 5). And as it is written in the Midrash (Sanhedrin 99b): ‘Man is born to toil; fortunate is one whose toil is in Torah.’"},"history":{"earlier_supplied_English":"What difference does it really make? If the world were really to be poorer now than before, that is all the more reason to flee to God and involve yourself in Torah and devotion. If there is suffering and trouble in the world, the only place to escape is to God and His Torah. It is written, “For man is born to struggle” (Job 5:7) . The Midrash remarks, “'Man is born to struggle': Happy is he who struggles with the Torah” (cf. Sanhedrin 99b) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/4"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-4","owner":"sichos-308-position-4","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-308-position-4","owner":"sichos-308-position-4","placement":"after-owning-paragraph","role":"current-source-qualification","text":"Greater hardship is introduced conditionally; the following statement that refuge is in God and Torah is not conditional."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-4","englishUTF8SHA256":"ef5b62283e108354aaa0c04704e872633852a90e1dad6290c8d80445dd54f69e"}},{"owner":"sichos-308-position-5","section":308,"position":5,"source_index":6,"fields":{"he":"פרוש: מאחר שאיך שיהיה, אם יהיה עשיר או עני וכו' אף על פי כן בודאי יהיה לו עמל וכעס כל ימיו כי צרות ויסורי כל אדם רבים מאד וכמו שכתוב \"גם כל ימיו כעס ומכאובות\" וכו' (קהלת ב־כג).","he_nikud":"פֵּרוּשׁ: מֵאַחַר שֶׁאֵיךְ שֶׁיִּהְיֶה, אִם יִהְיֶה עָשִׁיר אוֹ עָנִי וְכוּ' אַף עַל פִּי כֵן בְּוַדַּאי יִהְיֶה לוֹ עָמָל וָכַעַס כָּל יָמָיו כִּי צָרוֹת וְיִסּוּרֵי כָּל אָדָם רַבִּים מְאֹד וּכְמוֹ שֶׁכָּתוּב \"גַּם כָּל יָמָיו כַּעַס וּמַכְאוֹבוֹת\" וְכוּ' (קֹהֶלֶת ב־כג).","en":"The meaning is: since, however it may be, whether one is rich or poor, etc., nevertheless one will certainly have toil and vexation all one's days, for the troubles and sufferings of every person are very many. And as it is written: “And all his days are vexation and pain,” etc. (Ecclesiastes 2:23)."},"history":{"earlier_supplied_English":"Whether you are rich or poor, your life will be filled with toil and frustration. Man’s lot is suffering and pain, as it is written, “For all his days are vexatious and painful” (Ecclesiastes 2:23) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/5"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-5","owner":"sichos-308-position-5","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-5","englishUTF8SHA256":"3de65abecc28e052bb8915be64b17d53117e68bd0d1461e1eb7cafe4fb6892ee"}},{"owner":"sichos-308-position-6","section":308,"position":6,"source_index":7,"fields":{"he":"וכמובא בשל\"ה (ח\"ב קלח.) בלשון חרוז: \"אין רגע בלא פגע אין שעה וכו' אין יום וכו'\" על כן בודאי אשרי מי שבורח מזה העמל של פגעי העולם הזה אל עמל התורה, ואז בודאי אשרי וטוב לו בעולם הזה ובעולם הבא.","he_nikud":"וְכַמּוּבָא בַּשְּׁלָ\"ה (ח\"ב קלח.) בִּלְשׁוֹן חָרוּז: \"אֵין רֶגַע בְּלֹא פֶּגַע אֵין שָׁעָה וְכוּ' אֵין יוֹם וְכוּ'\" עַל כֵּן בְּוַדַּאי אַשְׁרֵי מִי שֶׁבּוֹרֵחַ מִזֶּה הֶעָמָל שֶׁל פִּגְעֵי הָעוֹלָם הַזֶּה אֶל עֲמַל הַתּוֹרָה, וְאָז בְּוַדַּאי אַשְׁרֵי וְטוֹב לוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.","en":"And as it is brought in the Shelah (part 2, 138a) in rhyme: “There is no moment without misfortune, no hour, etc., no day, etc.” Therefore, certainly fortunate is one who flees from this toil of the misfortunes of this world to the toil of Torah. And then certainly fortunate is he and it is good for him in this world and in the World to Come."},"history":{"earlier_supplied_English":"In the holy Shelah , 376 Shelah 2:138a. See above, note 288. we find a verse: Ein rega belo pega Ein sha’ah belo ra’ah Ein yom belo reses ve'ayom There is no moment Without its torment There is no hour That is not sour There is no day Without dismay. Happy is the man who flees from the struggles of this troublesome world for the toil of Torah. He will be “happy and prosperous” – happy in this world and prosperous in the World to Come ( Avot 6:4; Berakhot 8a) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/6"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-6","owner":"sichos-308-position-6","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-6","englishUTF8SHA256":"afaa1a285da3e52e9aba1ff6034e39e1566419b4e54c25362ee360839fc7273f"}},{"owner":"sichos-308-position-7","section":308,"position":7,"source_index":8,"fields":{"he":"אבל בזה שאומר שהימים הראשונים היה טובים מאלה, ובגדל דאגתו וטרדתו וצערו על פרנסתו וממון בכל פעם יותר ויותר, בזה לא יפעל כלום רק מבלה ימיו בצער ודאגה וכעס ומכאובות ומבטל עצמו מהתורה ותפלה וכו' מחמת דאגות ושיחות ושטותים כאלו. ולבסוף (קהלת ה): \"מאומה לא ישא בעמלו\". כי (קהלת ו): \"בהבל בא ובחשך ילך\" וכו'.","he_nikud":"אֲבָל בָּזֶה שֶׁאוֹמֵר שֶׁהַיָּמִים הָרִאשׁוֹנִים הָיָה טוֹבִים מֵאֵלֶּה, וּבְגֹדֶל דַּאֲגָתוֹ וְטִרְדָּתוֹ וְצַעֲרוֹ עַל פַּרְנָסָתוֹ וּמָמוֹן בְּכָל פַּעַם יוֹתֵר וְיוֹתֵר, בָּזֶה לֹא יִפְעַל כְּלוּם רַק מְבַלֶּה יָמָיו בְּצַעַר וּדְאָגָה וְכַעַס וּמַכְאוֹבוֹת וּמְבַטֵּל עַצְמוֹ מֵהַתּוֹרָה וּתְפִלָּה וְכוּ' מֵחֲמַת דְּאָגוֹת וְשִׂיחוֹת וּשְׁטוּתִים כָּאֵלּוּ. וּלְבַסּוֹף (קֹהֶלֶת ה): \"מְאוּמָה לֹא יִשָּׂא בַּעֲמָלוֹ\". כִּי (קֹהֶלֶת ו): \"בְּהֶבֶל בָּא וּבַחֹשֶׁךְ יֵלֵךְ\" וְכוּ'.","en":"But by saying that the former days were better than these, and with his worry and preoccupation and pain about his livelihood and money growing greater and greater each time, he will accomplish nothing through this. He only spends his days in pain and worry and vexation and suffering, and keeps himself from Torah and prayer, etc., because of such worries and discussions and foolishness. And in the end (Ecclesiastes 5): “He will carry nothing away from his toil.” For (Ecclesiastes 6): “In vanity he comes, and in darkness he goes,” etc."},"history":{"earlier_supplied_English":"The person who says that “the first days are better than these” and worries, and is constantly anxious about his finances, accomplishes nothing. His attitude causes him to struggle more and more to earn a living and waste his days in worry and vexation. This foolishness keeps him from Torah and prayer, and regarding his end, it is written, “He takes away nothing for his effort” (Ecclesiastes 5:14) . It is also written, “For in vanity he comes, and in darkness he leaves” (ibid., 6:4) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/7"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-7","owner":"sichos-308-position-7","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-7","englishUTF8SHA256":"fb2561faeefad4291a05cadf7f0101981e769c6fbdc89b4999b95112bdf966cd"}},{"owner":"sichos-308-position-8","section":308,"position":8,"source_index":9,"fields":{"he":"כי באמת מי שיש לו עינים לראות ולב להבין האמת לאמתו יבין בשכל ויראה שגם בימים הראשונים היה העולם מלא דאגות וטרדות הפרנסה, וכמו שאנו רואים בכל הספרים שנתחברו לפני מאות שנים שרבם ככלם כותבים בהקדמותיהם שהיה להם צרות רבות בימיהם וחסרון כיס ודחקות הפרנסה הקשה מכלם, ואף על פי כן חברו ספרים קדושים הרבה כי (קהלת א): \"מה שהיה הוא שיהיה\" וכו'.","he_nikud":"כִּי בֶּאֱמֶת מִי שֶׁיֵּשׁ לוֹ עֵינַיִם לִרְאוֹת וְלֵב לְהָבִין הָאֱמֶת לַאֲמִתּוֹ יָבִין בְּשֵׂכֶל וְיִרְאֶה שֶׁגַּם בַּיָּמִים הָרִאשׁוֹנִים הָיָה הָעוֹלָם מָלֵא דַּאֲגוֹת וְטִרְדוֹת הַפַּרְנָסָה, וּכְמוֹ שֶׁאָנוּ רוֹאִים בְּכָל הַסְּפָרִים שֶׁנִּתְחַבְּרוּ לִפְנֵי מֵאוֹת שָׁנִים שֶׁרֻבָּם כְּכֻלָּם כּוֹתְבִים בְּהַקְדָּמוֹתֵיהֶם שֶׁהָיָה לָהֶם צָרוֹת רַבּוֹת בִּימֵיהֶם וְחֶסְרוֹן כִּיס וְדַחֲקוּת הַפַּרְנָסָה הַקָּשָׁה מִכֻּלָּם, וְאַף עַל פִּי כֵן חִבְּרוּ סְפָרִים קְדוֹשִׁים הַרְבֵּה כִּי (קֹהֶלֶת א): \"מַה שֶּׁהָיָה הוּא שֶׁיִּהְיֶה\" וְכוּ'.","en":"For in truth, one who has eyes to see and a heart to understand the truth in its fullness will understand with his intellect and see that in the former days too the world was full of worries and preoccupations about livelihood. And as we see in all the books composed hundreds of years ago, most—almost all—write in their introductions that they had many troubles in their days, and lack of money and the difficulty of livelihood were the hardest of them all. And nevertheless they composed many holy books, for (Ecclesiastes 1): “What was is what will be,” etc."},"history":{"earlier_supplied_English":"If you have eyes to see and a heart to understand, you will perceive that the past had as much suffering and troubles as the present. Look in books written hundreds of years ago and you will find that their authors also suffered from poverty and endured the most difficult struggles just to earn a livelihood. This did not deter them and they still wrote many holy books. It is written, “What was, that is what will be … there is nothing new under the sun” (ibid., 1:9) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/8"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-8","owner":"sichos-308-position-8","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-8","englishUTF8SHA256":"aa8ed6dfe7a62c31ce5991819122a054969a02710cdcee7b74e2b90bae45187b"}},{"owner":"sichos-308-position-9","section":308,"position":9,"source_index":10,"fields":{"he":"והכלל: שגם בימים הראשונים היה העולם מלא דאגות פרנסה כמו שכתב שלמה המלך, ע\"ה (קהלת ב): \"גם כל ימיו כעס ומכאובות\" וכו'. וכתיב \"אדם לעמל יולד קצר ימים ושבע רגז\" וכו'. וכיוצא כאלה פסוקים הרבה.","he_nikud":"וְהַכְּלָל: שֶׁגַּם בַּיָּמִים הָרִאשׁוֹנִים הָיָה הָעוֹלָם מָלֵא דַּאַגוֹת פַּרְנָסָה כְּמוֹ שֶׁכָּתַב שְׁלֹמֹה הַמֶּלֶךְ, ע\"ה (קֹהֶלֶת ב): \"גַּם כָּל יָמָיו כַּעַס וּמַכְאוֹבוֹת\" וְכוּ'. וּכְתִיב \"אָדָם לְעָמָל יוּלָד קְצַר יָמִים וּשְׂבַע רֹגֶז\" וְכוּ'. וְכַיּוֹצֵא כָּאֵלֶּה פְּסוּקִים הַרְבֵּה.","en":"And the general rule is that in the former days too the world was full of worries about livelihood, as King Solomon, peace be upon him, wrote (Ecclesiastes 2): “And all his days are vexation and pain,” etc. And it is written: “Man is born to toil, short of days and full of trouble,” etc. And there are many similar verses."},"history":{"earlier_supplied_English":"Life was difficult even in the “good old days.” How many years ago did King Solomon write of man, “For all his days are vexation and pain”? How many years ago did the Book of Job say, “Man is born to struggle – of few days and full of trouble” (Job 14:1) ? The scriptures wrote about this long ago.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/9"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-9","owner":"sichos-308-position-9","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-9","englishUTF8SHA256":"024ba44c5d937e6b863f9a8d342292a787ba18fbdc709789240a927844881915"}},{"owner":"sichos-308-position-10","section":308,"position":10,"source_index":11,"fields":{"he":"וגם אז נדמה לכל אחד שבצוק העתים כאלה צריכים לדאג רק על הפרנסה ועל ידי זה אבדו ימיהם והלכו מן העולם בלא חמדה.","he_nikud":"וְגַם אָז נִדְמֶה לְכָל אֶחָד שֶׁבְּצוּק הָעִתִּים כָּאֵלֶּה צְרִיכִים לִדְאֹג רַק עַל הַפַּרְנָסָה וְעַל יְדֵי זֶה אָבְדוּ יְמֵיהֶם וְהָלְכוּ מִן הָעוֹלָם בְּלֹא חֶמְדָּה.","en":"And even then it seemed to each person that in such difficult times one must worry only about livelihood, and through this they lost their days and departed from the world without delight."},"history":{"earlier_supplied_English":"Even then, many people thought that times were troublesome (Daniel 9:25) and that one must only worry about his livelihood. These people lost their days and departed from this world without joy or pleasure (II Chronicles 21:20) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/10"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-10","owner":"sichos-308-position-10","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-10","englishUTF8SHA256":"bb6f19de55a741f5c0314a104df3a3cc3fe8608f0244899dede0adc025bf873d"}},{"owner":"sichos-308-position-11","section":308,"position":11,"source_index":12,"fields":{"he":"ואף על פי כן נמצא בכל דור צדיקים ויראים וכשרים שלא השגיחו על זה וברחו מן העמל של עולם הזה לעמל התורה ועבודה וזכו להם ולדורותיהם וכו' אשרי להם.","he_nikud":"וְאַף עַל פִּי כֵן נִמְצָא בְּכָל דּוֹר צַדִּיקִים וִירֵאִים וּכְשֵׁרִים שֶׁלֹּא הִשְׁגִּיחוּ עַל זֶה וּבָרְחוּ מִן הֶעָמָל שֶׁל עוֹלָם הַזֶּה לַעֲמַל הַתּוֹרָה וַעֲבוֹדָה וְזָכוּ לָהֶם וּלְדוֹרוֹתֵיהֶם וְכוּ' אַשְׁרֵי לָהֶם.","en":"And nevertheless, in every generation there were righteous, God-fearing and upright people who paid no attention to this and fled from the toil of this world to the toil of Torah and service, and merited for themselves and for their generations, etc. Fortunate are they."},"history":{"earlier_supplied_English":"But each generation also had God-fearing men and tzaddikim. They paid no attention to these concerns and escaped the struggles of the world to toil in Torah and devotion. They achieved for themselves and for their children. Fortunate are they.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/11"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-11","owner":"sichos-308-position-11","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-11","englishUTF8SHA256":"f739b5bf82f17d26613e43cea4deb0f3731acde7cc755e0077d6a850d172103d"}},{"owner":"sichos-308-position-12","section":308,"position":12,"source_index":13,"fields":{"he":"וכן עכשו בודאי הבחירה חפשית ובודאי יש כח עתה גם עתה לכל אחד ואחד לברח מדאגות ושיחות של צער כאלה, לברח מהם ולבטח בה' ולקבל על עצמו עמל התורה תחת עמל המר של דאגת העולם הזה. ובודאי יפרנסו השם יתברך, כי השם יתברך מפרנס העולם תמיד כאז כן עתה. אדרבא, השם יתברך מנהיג העולם בכל פעם יפה יותר.","he_nikud":"וְכֵן עַכְשָׁו בְּוַדַּאי הַבְּחִירָה חָפְשִׁית וּבְוַדַּאי יֵשׁ כֹּחַ עַתָּה גַּם עַתָּה לְכָל אֶחָד וְאֶחָד לִבְרֹחַ מִדְּאָגוֹת וְשִׂיחוֹת שֶׁל צַעַר כָּאֵלֶּה, לִבְרֹחַ מֵהֶם וְלִבְטֹחַ בַּה' וּלְקַבֵּל עַל עַצְמוֹ עֲמַל הַתּוֹרָה תַּחַת עָמָל הַמַּר שֶׁל דַּאֲגַת הָעוֹלָם הַזֶּה. וּבְוַדַּאי יְפַרְנְסוֹ הַשֵּׁם יִתְבָּרַךְ, כִּי הַשֵּׁם יִתְבָּרַךְ מְפַרְנֵס הָעוֹלָם תָּמִיד כְּאָז כֵּן עַתָּה. אַדְּרַבָּא, הַשֵּׁם יִתְבָּרַךְ מַנְהִיג הָעוֹלָם בְּכָל פַּעַם יָפֶה יוֹתֵר.","en":"And likewise now, certainly choice is free, and certainly there is strength now, even now, for each and every person to flee from such worries and painful discussions—to flee from them and trust in God and take upon himself the toil of Torah in place of the bitter toil of worry about this world. And certainly God, blessed be He, will provide for him, for God, blessed be He, sustains the world always, then as now. On the contrary, God, blessed be He, directs the world more beautifully each time."},"history":{"earlier_supplied_English":"Even today, you have free will. You have the power to escape from these painful discussions and from worries. You can flee from them and trust in God, abandoning the struggles of this bitter world and involving yourself in the work of Torah. God will certainly sustain you. Does He not sustain the entire world, now as always? And now God directs the world better than ever before.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/12"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-12","owner":"sichos-308-position-12","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-12","englishUTF8SHA256":"a8400082f6bf60615cd3c6dc509eb860dd51595598dae7dd8e5423a02e98c956"}},{"owner":"sichos-308-position-13","section":308,"position":13,"source_index":14,"fields":{"he":"הכלל: שהעולם הזה מלא דאגות ויגונות וצער ויסורים תמיד כמו אז כמו עתה וכמו שנגזר מחטא אדם הראשון (בראשית ג): \"בעצבון תאכלנה\", \"בזעת אפך תאכל לחם\". ואין מקום לברח מהעצבון והדאגות האלו המקצרים ומכלים ימי האדם, אין מקום לברח מהם כי אם אל השם יתברך ואל התורה וכנ\"ל.","he_nikud":"הַכְּלָל: שֶׁהָעוֹלָם הַזֶּה מָלֵא דְּאָגוֹת וִיגוֹנוֹת וְצַעַר וְיִסּוּרִים תָּמִיד כְּמוֹ אָז כְּמוֹ עַתָּה וּכְמוֹ שֶׁנִּגְזַר מֵחֵטְא אָדָם הָרִאשׁוֹן (בְּרֵאשִׁית ג): \"בְּעִצָּבוֹן תֹּאכֲלֶנָּה\", \"בְּזֵעַת אַפֶּךָ תֹּאכַל לֶחֶם\". וְאֵין מָקוֹם לִבְרֹחַ מֵהָעִצָּבוֹן וְהַדְּאָגוֹת הָאֵלּוּ הַמְקַצְּרִים וּמְכַלִּים יְמֵי הָאָדָם, אֵין מָקוֹם לִבְרֹחַ מֵהֶם כִּי אִם אֶל הַשֵּׁם יִתְבָּרַךְ וְאֶל הַתּוֹרָה וכנ\"ל.","en":"The general rule is that this world is always full of worries and sorrows and pain and sufferings, then as now, as was decreed because of the sin of the first Adam (Genesis 3): “In pain you shall eat of it,” “By the sweat of your brow you shall eat bread.” And there is no place to flee from this anguish and these worries that shorten and consume a person's days—there is no place to flee from them except to God, blessed be He, and to the Torah, as mentioned above."},"history":{"earlier_supplied_English":"This world was always filled with worries and suffering. Things have not changed. It is written, “In pain you shall eat” (Genesis 3:17) , and, “By the sweat of your brow you shall eat bread” (ibid., 3:19) . This was decreed since Adam’s sin and there is no place to escape. These worries and pains destroy a man’s life; the only shelter is God and His Torah.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/13"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-13","owner":"sichos-308-position-13","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-13","englishUTF8SHA256":"73b95b3c352218a450f381197966eb4aad31b4c7c5b451fe1656822012babfa2"}},{"owner":"sichos-308-position-14","section":308,"position":14,"source_index":15,"fields":{"he":"וכבר דברנו, שזהו מה שאמרו רבותינו ז\"ל במשנה (אבות ו): 'כך הוא דרכה של תורה פת במלח תאכל, ומים במשורה תשתה, ועל הארץ תישן, וחיי צער תחיה, ובתורה אתה עמל. אם אתה עושה כן אשריך וטוב לך. אשריך בעולם הזה וטוב לך לעולם הבא'.","he_nikud":"וּכְבָר דִּבַּרְנוּ, שֶׁזֶּהוּ מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ ז\"ל בַּמִּשְׁנָה (אָבוֹת ו): 'כָּךְ הוּא דַּרְכָּהּ שֶׁל תּוֹרָה פַּת בַּמֶּלַח תֹּאכַל, וּמַיִם בַּמְּשׂוּרָה תִּשְׁתֶּה, וְעַל הָאָרֶץ תִּישַׁן, וְחַיֵּי צַעַר תִּחְיֶה, וּבַתּוֹרָה אַתָּה עָמֵל. אִם אַתָּה עוֹשֶׂה כֵּן אַשְׁרֶיךָ וְטוֹב לָךְ. אַשְׁרֶיךָ בָּעוֹלָם הַזֶּה וְטוֹב לָךְ לָעוֹלָם הַבָּא'.","en":"And we have already discussed that this is what our Sages, of blessed memory, said in the Mishnah (Avos 6): ‘Thus is the way of Torah: bread with salt you shall eat, and measured water you shall drink, and on the ground you shall sleep, and a life of privation you shall live, and in the Torah you toil. If you do so, fortunate are you and it is good for you. Fortunate are you in this world, and it is good for you in the World to Come.’"},"history":{"earlier_supplied_English":"The Mishnah teaches, “Thus is the way of Torah: Bread with salt you shall eat, measured water shall you drink, on the ground you shall sleep, and a life of privation you shall live, while in the Torah you shall toil. If you do so, 'you shall be happy, and it shall be good for you' (Psalms 128:2) . 'You shall be happy'. in this world – 'and it shall be good for you' in the World to Come” ( Avot 6:4) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/14"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-14","owner":"sichos-308-position-14","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-14","englishUTF8SHA256":"7a9bf90a84093023210a94a565ae8483606732c4190be3d5ad22ea09f851afc8"}},{"owner":"sichos-308-position-15","section":308,"position":15,"source_index":16,"fields":{"he":"ומקשין ההמון עם: איך שיך אשריך בעולם הזה מאחר שצריך לסבל עמל כזה לאכל פת במלח וכו'? וכבר מבאר באיזה ספרים איזה תרוצים דחוקים בדרך דרש, אבל באמת מי שיש לו עינים ולב להסתכל בעניני עולם הזה באמת, מי שזכה לינק באמת מתורותיו ושיחותיו ומעשיותיו הנוראים של רבנו הקדוש והנורא זכר צדיק וקדוש לברכה, אצלו מבאר המשנה בפשיטות גמור ויכולין להסביר הדבר לכל בר שכל אמתי הבקי קצת בטוב הנהגת העולם.","he_nikud":"וּמַקְשִׁין הַהֲמוֹן עָם: אֵיךְ שַׁיָּךְ אַשְׁרֶיךָ בָּעוֹלָם הַזֶּה מֵאַחַר שֶׁצָּרִיךְ לִסְבֹּל עָמָל כָּזֶה לֶאֱכֹל פַּת בַּמֶּלַח וְכוּ'? וּכְבָר מְבֹאָר בְּאֵיזֶה סְפָרִים אֵיזֶה תֵּרוּצִים דְּחוּקִים בְּדֶרֶךְ דְּרָשׁ, אֲבָל בֶּאֱמֶת מִי שֶׁיֵּשׁ לוֹ עֵינַיִם וְלֵב לְהִסְתַּכֵּל בְּעִנְיְנֵי עוֹלָם הַזֶּה בֶּאֱמֶת, מִי שֶׁזָּכָה לִינֹק בֶּאֱמֶת מִתּוֹרוֹתָיו וְשִׂיחוֹתָיו וּמַעֲשִׂיּוֹתָיו הַנּוֹרָאִים שֶׁל רַבֵּנוּ הַקָּדוֹשׁ וְהַנּוֹרָא זֵכֶר צַדִּיק וְקָדוֹשׁ לִבְרָכָה, אֶצְלוֹ מְבֹאָר הַמִּשְׁנָה בִּפְשִׁיטוּת גָּמוּר וִיכוֹלִין לְהַסְבִּיר הַדָּבָר לְכָל בַּר שֵׂכֶל אֲמִתִּי הַבָּקִי קְצָת בְּטוּב הַנְהָגַת הָעוֹלָם.","en":"And the common people object: how can ‘fortunate are you in this world’ apply when one must endure such toil, eating bread with salt, etc.? And some strained answers by way of homily have already been explained in some books. But in truth, one who has eyes and a heart to look truthfully at the matters of this world, one who has truly merited to draw nourishment from the awesome teachings and discussions and stories of our holy and awesome Rebbe, may the memory of the righteous and holy one be for a blessing—for him the Mishnah is explained with complete simplicity. And the matter can be explained to any person of true intellect who is somewhat familiar with the good conduct of the world."},"history":{"earlier_supplied_English":"People find this difficult to understand. After telling us the struggles we must endure – “bread with salt you shall eat” – how can the Mishnah state, “'You shall be happy' – in this world\"? Many writers attempt to resolve this by way of homily, but their explanations remain strained. In fact, there really is no question. If you have eyes to see and a heart that truly understands the world, you know this. If you have absorbed the wisdom contained in the Rebbe’s awesome teachings, you know the truth. The Mishnah means exactly what it says.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/15"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-15","owner":"sichos-308-position-15","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-15","englishUTF8SHA256":"f56025448f7c4a510c3154dbd7aaccd1261f31c9fa5adc378fc60b4551e481a3"}},{"owner":"sichos-308-position-16","section":308,"position":16,"source_index":17,"fields":{"he":"כי כל העשירים והגבירים הגדולים מודים שהעולם הזה מלא יגונות ויסורים. כי דאגותיהם ויסוריהם רבות מאד מאד בכל פעם ובכל יום ובכל שעה, וכמו שאמרו רבותינו ז\"ל (שם ב־ז): 'מרבה נכסים מרבה דאגה' ואף על פי שההמון עם העניים אינם מבינים זאת ונדמה להם שאם היה להם עשירות לא היה להם דאגות, אבל באמת הם טועים הרבה בזה וכנראה בחוש וכמו שאמרו רבותינו ז\"ל.","he_nikud":"כִּי כָּל הָעֲשִׁירִים וְהַגְּבִירִים הַגְּדוֹלִים מוֹדִים שֶׁהָעוֹלָם הַזֶּה מָלֵא יְגוֹנוֹת וְיִסּוּרִים. כִּי דַּאֲגוֹתֵיהֶם וְיִסּוּרֵיהֶם רַבּוֹת מְאֹד מְאֹד בְּכָל פַּעַם וּבְכָל יוֹם וּבְכָל שָׁעָה, וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ ז\"ל (שָׁם ב־ז): 'מַרְבֶּה נְכָסִים מַרְבֶּה דְּאָגָה' וְאַף עַל פִּי שֶׁהַהֲמוֹן עַם הָעֲנִיִּים אֵינָם מְבִינִים זֹאת וְנִדְמֶה לָהֶם שֶׁאִם הָיָה לָהֶם עֲשִׁירוּת לֹא הָיָה לָהֶם דְּאָגוֹת, אֲבָל בֶּאֱמֶת הֵם טוֹעִים הַרְבֵּה בָּזֶה וְכַנִּרְאֶה בְּחוּשׁ וּכְמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ ז\"ל.","en":"For all the wealthy and the great magnates acknowledge that this world is full of sorrows and sufferings. For their worries and sufferings are very, very many at every time and every day and every hour, as our Sages, of blessed memory, said (ibid., 2:7): ‘More possessions, more worry.’ And although the common poor people do not understand this and it seems to them that if they had wealth they would have no worries, in truth they are greatly mistaken about this, as is evident to the senses and as our Sages, of blessed memory, said."},"history":{"earlier_supplied_English":"The wealthiest men in the world will tell you that the world is filled with worry and suffering. The rich suffer as much as everyone else. Thus, our Sages teach, “The more possessions, the more worry” (ibid., 2:7) . The poor may not realize this. They may think that they would no longer have problems if they were wealthy. But they are sadly mistaken, as we can see with our own eyes. The truth is as our Sages have taught it. Whether you are rich or poor, you cannot avoid worries. The world is filled with pain and suffering and there is no avenue of escape.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/16"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-16","owner":"sichos-308-position-16","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-16","englishUTF8SHA256":"11cbe379570879f8289311c2500252505fb7b6188d591fc9b8d54db6853eedbf"}},{"owner":"sichos-308-position-17","section":308,"position":17,"source_index":18,"fields":{"he":"והעניים והבעלי בתים יש להם גם כן בודאי דאגות הרבה וכנזכר לעיל. על כן אין מקום לברח מיסורי עולם הזה המלא מכאובות יסורים מיסורים שונים, הן בענין פרנסה הן בענין צער ויסורים מאשתו ובניו, ולהנשים נדמה שיש להם מבעליהם יסורים, והן בענין יסורים ומכאובים ממש. שנמצאים הרבה סובלי חלאים ומכות מפלאות רחמנא לצלן בעולם הן על כל אלה וכיוצא בהם, אין מקום לברח מכל זה כי אם אל התורה.","he_nikud":"וְהָעֲנִיִּים וְהַבַּעֲלֵי בָּתִּים יֵשׁ לָהֶם גַּם כֵּן בְּוַדַּאי דְּאָגוֹת הַרְבֵּה וְכַנִּזְכַּר לְעֵיל. עַל כֵּן אֵין מָקוֹם לִבְרֹחַ מִיִּסּוּרֵי עוֹלָם הַזֶּה הַמָּלֵא מַכְאוֹבוֹת יִסּוּרִים מִיִּסּוּרִים שׁוֹנִים, הֵן בְּעִנְיַן פַּרְנָסָה הֵן בְּעִנְיַן צַעַר וְיִסּוּרִים מֵאִשְׁתּוֹ וּבָנָיו, וּלְהַנָּשִׁים נִדְמֶה שֶׁיֵּשׁ לָהֶם מִבַּעֲלֵיהֶם יִסּוּרִים, וְהֵן בְּעִנְיַן יִסּוּרִים וּמַכְאוֹבִים מַמָּשׁ. שֶׁנִּמְצָאִים הַרְבֵּה סוֹבְלֵי חֲלָאִים וּמַכּוֹת מֻפְלָאוֹת רַחֲמָנָא לִצְלַן בָּעוֹלָם הֵן עַל כָּל אֵלֶּה וְכַיּוֹצֵא בָּהֶם, אֵין מָקוֹם לִבְרֹחַ מִכָּל זֶה כִּי אִם אֶל הַתּוֹרָה.","en":"And the poor and the householders also certainly have many worries, as mentioned above. Therefore there is no place to flee from the sufferings of this world, which is full of pains and sufferings of various kinds: whether about livelihood, or about pain and suffering from one's wife and children—and women think that they have suffering from their husbands—or about actual sufferings and pains. For many who suffer from illnesses and extraordinary afflictions, the Merciful One protect us, are found in the world. From all these and the like, there is no place to flee from all of this except to the Torah."},"history":{"earlier_supplied_English":"If you are a man, you worry about earning a livelihood. You are concerned about your wife and children. If you are a woman, you imagine that you are troubled by your husband. Then, there is the real suffering and pain of those who suffer because of serious sickness and And misfortune. Heaven help us. There is no escape – except in the Torah.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/17"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-17","owner":"sichos-308-position-17","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-17","englishUTF8SHA256":"bf92ae58a70c57b3811986069c025ff507c96414842cfe6f467493f0e2ad0ba7"}},{"owner":"sichos-308-position-18","section":308,"position":18,"source_index":19,"fields":{"he":"כי כל מי שרוצה שיהיה לו טוב בעולם הזה שיחיה בנחת בלי צער הוא מלא צרות תמיד. כי כל מה שמקוה לטוב – בא להפך. ואפלו אם יהיה לו לפעמים איזה טוב מדמה, הוא בודאי מערב ביגונות תמיד כידוע בחוש למסתכל על האמת.","he_nikud":"כִּי כָּל מִי שֶׁרוֹצֶה שֶׁיִּהְיֶה לוֹ טוֹב בָּעוֹלָם הַזֶּה שֶׁיִּחְיֶה בְּנַחַת בְּלִי צַעַר הוּא מָלֵא צָרוֹת תָּמִיד. כִּי כָּל מַה שֶּׁמְּקַוֶּה לְטוֹב – בָּא לְהֵפֶךְ. וַאֲפִלּוּ אִם יִהְיֶה לוֹ לִפְעָמִים אֵיזֶה טוֹב מְדֻמֶּה, הוּא בְּוַדַּאי מְעֹרָב בִּיגוֹנוֹת תָּמִיד כַּיָּדוּעַ בְּחוּשׁ לַמִּסְתַּכֵּל עַל הָאֱמֶת.","en":"For everyone who wants to have good in this world, to live at ease without pain, is always full of troubles. For everything he hopes will be good turns out the opposite. And even if he sometimes has some imagined good, it is certainly always mixed with sorrows, as is evident to the senses of one who looks at the truth."},"history":{"earlier_supplied_English":"If you desire the good of this world and want to live at ease without troubles, you will be constantly frustrated. The more you seek good, the more you will find the opposite. Everything you manage to grasp will be diluted with suffering. Look with truth and you will see this yourself.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/18"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-18","owner":"sichos-308-position-18","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-18","englishUTF8SHA256":"9d0e48ee5ef67859521ba98a4ff50298d13442092498854d811fec1600f46ca4"}},{"owner":"sichos-308-position-19","section":308,"position":19,"source_index":20,"fields":{"he":"על כן בעולם הזה \"אין חכמה ואין תבונה ואין עצה\" (משלי כא) לחיות בנחת, כי אם כשמתרצה באמת להסתפק בתכלית המעוט ולחיות חיי צער, כמו שאמרו שם במשנה הנ\"ל: פת במלח תאכל וכו'. שאז דיקא כשמקבל על עצמו כל הדחקות וחיי צער ולסבל הכל ולעסק בתורה כמו שכתוב שם: 'ובתורה אתה עמל', אז דיקא יש לו חיות גם בעולם הזה.","he_nikud":"עַל כֵּן בָּעוֹלָם הַזֶּה \"אֵין חָכְמָה וְאֵין תְּבוּנָה וְאֵין עֵצָה\" (מִשְׁלֵי כא) לִחְיוֹת בְּנַחַת, כִּי אִם כְּשֶׁמִּתְרַצֶּה בֶּאֱמֶת לְהִסְתַּפֵּק בְּתַכְלִית הַמִּעוּט וְלִחְיוֹת חַיֵּי צַעַר, כְּמוֹ שֶׁאָמְרוּ שָׁם בַּמִּשְׁנָה הַנַּ\"ל: פַּת בַּמֶּלַח תֹּאכַל וְכוּ'. שֶׁאָז דַּיְקָא כְּשֶׁמְּקַבֵּל עַל עַצְמוֹ כָּל הַדַּחֲקוּת וְחַיֵּי צַעַר וְלִסְבֹּל הַכֹּל וְלַעֲסֹק בַּתּוֹרָה כְּמוֹ שֶׁכָּתוּב שָׁם: 'וּבַתּוֹרָה אַתָּה עָמֵל', אָז דַּיְקָא יֵשׁ לוֹ חִיּוּת גַּם בָּעוֹלָם הַזֶּה.","en":"Therefore in this world “there is no wisdom and no understanding and no counsel” (Proverbs 21) for living at ease, except when one is truly willing to be satisfied with the absolute minimum and live a life of privation, as they said there in the above-mentioned Mishnah: bread with salt you shall eat, etc. For precisely then, when one accepts upon himself all the hardship and a life of privation, and to endure everything and engage in Torah, as it is written there: ‘and in the Torah you toil’—precisely then he has vitality even in this world."},"history":{"earlier_supplied_English":"It is written, “There is no wisdom, understanding or counsel against God” (Proverbs 21:30) . The only way to be at ease is to be willing to subsist on an absolute minimum. Firmly resolve to follow the dictum of the Mishnah, “Bread with salt you shall eat … a life of privation shall you live.” Accept upon yourself a life of deprivation and hardship in order to involve yourself in the Torah – “in the Torah you shall toil.”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/19"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-19","owner":"sichos-308-position-19","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-19","englishUTF8SHA256":"4e542b51dba0cd9d8d99b3947ac0c1e845613821af070d10104135089968a405"}},{"owner":"sichos-308-position-20","section":308,"position":20,"source_index":21,"fields":{"he":"ואשרי לו גם בעולם הזה. כמו שכתוב שם 'אם אתה עושה כן אשריך בעולם הזה' ודאי.","he_nikud":"וְאַשְׁרֵי לוֹ גַּם בָּעוֹלָם הַזֶּה. כְּמוֹ שֶׁכָּתוּב שָׁם 'אִם אַתָּה עוֹשֶׂה כֵּן אַשְׁרֶיךָ בָּעוֹלָם הַזֶּה' וַדַּאי.","en":"And fortunate is he even in this world, as it is written there: ‘If you do so, fortunate are you in this world’—certainly."},"history":{"earlier_supplied_English":"Only then will you have life, even in this world. “If you do so, 'you shall be happy' … in this world.” This is certainly true.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/20"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-20","owner":"sichos-308-position-20","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-20","englishUTF8SHA256":"31df9bca97aa568406e9d2688ffaddac42ea27cb3baea9810a1f83b5c504baeb"}},{"owner":"sichos-308-position-21","section":308,"position":21,"source_index":22,"fields":{"he":"כי לא יהיה לו שום יסורים מפגעי העולם הזה המרבים אצל כל אדם מאד מאחר שמקבל על עצמו הכל בשביל התורה וכל חיותו וטובו הוא התורה שהוא טוב אמתי ואז בודאי חייו חיים אמתיים ואשרי לו גם בעולם הזה.","he_nikud":"כִּי לֹא יִהְיֶה לוֹ שׁוּם יִסּוּרִים מִפִּגְעֵי הָעוֹלָם הַזֶּה הַמְּרֻבִּים אֵצֶל כָּל אָדָם מְאֹד מֵאַחַר שֶׁמְּקַבֵּל עַל עַצְמוֹ הַכֹּל בִּשְׁבִיל הַתּוֹרָה וְכָל חִיּוּתוֹ וְטוּבוֹ הוּא הַתּוֹרָה שֶׁהוּא טוֹב אֲמִתִּי וְאָז בְּוַדַּאי חַיָּיו חַיִּים אֲמִתִּיִּים וְאַשְׁרֵי לוֹ גַּם בָּעוֹלָם הַזֶּה.","en":"For he will have no suffering from the misfortunes of this world, which are very numerous for every person, since he accepts everything upon himself for the sake of Torah. And all his vitality and good is the Torah, which is true good. And then certainly his life is true life, and fortunate is he even in this world."},"history":{"earlier_supplied_English":"No longer will you suffer from worldly troubles. You have already accepted them upon yourself for the sake of the Torah. All your life – all your good – is the true good. Thus, your life is a true life. Happy are you – even in this world.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/21"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-21","owner":"sichos-308-position-21","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-21","englishUTF8SHA256":"f35fe8c6176d18d192035433bc1b36aef0f6d2210dc57b3477b94f6d4d7d00ae"}},{"owner":"sichos-308-position-22","section":308,"position":22,"source_index":23,"fields":{"he":"אבל הרוצה תענוגי עולם הזה, ולחיות בנחת בעולם הזה, בודאי חייו מרים ומרורים מאד. כי אפלו 'רוח קימעא עוכרתו' (סוטה ה.). כי תכף כשבא עליו דבר נגד רצונו, יש לו צער ויסורים.","he_nikud":"אֲבָל הָרוֹצֶה תַּעֲנוּגֵי עוֹלָם הַזֶּה, וְלִחְיוֹת בְּנַחַת בָּעוֹלָם הַזֶּה, בְּוַדַּאי חַיָּיו מָרִים וּמְרוֹרִים מְאֹד. כִּי אֲפִלּוּ 'רוּחַ קִימְעָא עוֹכַרְתּוֹ' (סוֹטָה ה.). כִּי תֵּכֶף כְּשֶׁבָּא עָלָיו דָּבָר נֶגֶד רְצוֹנוֹ, יֵשׁ לוֹ צַעַר וְיִסּוּרִים.","en":"But one who wants the pleasures of this world and to live at ease in this world certainly has a very bitter and embittered life. For even ‘a slight breeze disturbs him’ (Sotah 5a). For immediately when something contrary to his will comes upon him, he has pain and suffering."},"history":{"earlier_supplied_English":"The man who wants to live at ease in this world and enjoy its delights will find only bitterness. “Even the slightest breeze will upset him” ( Sotah 5a) . The smallest happening contrary to his wishes will cause him to suffer greatly.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/22"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-22","owner":"sichos-308-position-22","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-22","englishUTF8SHA256":"46b50aaf3172311f523fa8ccba3cc7c6f58c0c50b0345c9291a306b6c8ac07a6"}},{"owner":"sichos-308-position-23","section":308,"position":23,"source_index":24,"fields":{"he":"וזה אי אפשר שיתנהג הכל כרצונו אפלו אם יהיה גביר ואדון ומושל, כי עולם הזה מלא יסורים כנ\"ל.","he_nikud":"וְזֶה אִי אֶפְשָׁר שֶׁיִּתְנַהֵג הַכֹּל כִּרְצוֹנוֹ אֲפִלּוּ אִם יִהְיֶה גְּבִיר וְאָדוֹן וּמוֹשֵׁל, כִּי עוֹלָם הַזֶּה מָלֵא יִסּוּרִים כַּנַּ\"ל.","en":"And it is impossible that everything should go according to his will, even if he is a magnate and a lord and a ruler, for this world is full of sufferings, as mentioned above."},"history":{"earlier_supplied_English":"You may be immensely rich and powerful. You may be a lord or a king. It is still impossible for everything to be as you want, in a world filled with suffering.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/23"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-23","owner":"sichos-308-position-23","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-308-position-23","owner":"sichos-308-position-23","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew word translated “ruler” does not identify a particular office or person."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-23","englishUTF8SHA256":"055b672b4ebd9d2dbb71e6d83ef990e2bdc0fd086043055ba7dd64a166898e97"}},{"owner":"sichos-308-position-24","section":308,"position":24,"source_index":25,"fields":{"he":"על כן אין מקום לברח מעמל עולם הזה, ויסוריו כי אם אל עמל התורה, לקבל על עצמו לילך בדרכה של התורה, לאכל פת במלח וכו'. ואז אשרי וטוב לו. אשריו בעולם הזה ודאי והדברים מובנים היטב לבקי קצת ביסורי עולם הזה ודאגותיו הרבים ומסתכל על האמת.","he_nikud":"עַל כֵּן אֵין מָקוֹם לִבְרֹחַ מֵעֲמַל עוֹלָם הַזֶּה, וְיִסּוּרָיו כִּי אִם אֶל עֲמַל הַתּוֹרָה, לְקַבֵּל עַל עַצְמוֹ לֵילֵךְ בְּדַרְכָּהּ שֶׁל הַתּוֹרָה, לֶאֱכֹל פַּת בַּמֶּלַח וְכוּ'. וְאָז אַשְׁרֵי וְטוֹב לוֹ. אַשְׁרָיו בָּעוֹלָם הַזֶּה וַדַּאי וְהַדְּבָרִים מוּבָנִים הֵיטֵב לַבָּקִי קְצָת בְּיִסּוּרֵי עוֹלָם הַזֶּה וְדַאֲגוֹתָיו הָרַבִּים וּמִסְתַּכֵּל עַל הָאֱמֶת.","en":"Therefore there is no place to flee from the toil of this world and its sufferings except to the toil of Torah: to accept upon oneself to walk in the way of Torah, to eat bread with salt, etc. And then fortunate is he and it is good for him. Fortunate is he in this world—certainly. And these matters are well understood by one who is somewhat familiar with the sufferings of this world and its many worries, and who looks at the truth."},"history":{"earlier_supplied_English":"The only way to escape this suffering is in the Torah. Accept the way of the Torah, eating bread with salt …. Then you will be happy and it will be good for you. Happy – even in this world. Look at the truth. Understand well the troubles of this world. You will certainly see the truth of this.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/24"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-24","owner":"sichos-308-position-24","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-24","englishUTF8SHA256":"d0de8d063c8ab989f746a36beafcc6e607dfee5ea8a83e1da69280ff46a5a886"}},{"owner":"sichos-308-position-25","section":308,"position":25,"source_index":26,"fields":{"he":"(ועין מזה בשיחותיו של רבנו ז\"ל, הנדפסים אצל הספורי מעשיות לעיל, ועין בהמעשה של החכם והתם וכו').","he_nikud":"(וְעַיֵּן מִזֶּה בְּשִׂיחוֹתָיו שֶׁל רַבֵּנוּ ז\"ל, הַנִּדְפָּסִים אֵצֶל הַסִּפּוּרֵי מַעֲשִׂיּוֹת לְעֵיל, וְעַיֵּן בְּהַמַּעֲשֶׂה שֶׁל הֶחָכָם וְהַתָּם וְכוּ').","en":"(And see about this in the discussions of our Rebbe, of blessed memory, printed with the Stories above; and see in the story of the Wise Man and the Simple Man, etc.)"},"history":{"earlier_supplied_English":"You will find many of these [ideas] in the Rebbe’s teachings, especially those printed together with the Sipurey Ma'asiot . 377 All the Sichot up to #116 were originally printed with the Sipurey Ma'asiot . See note 298. They are also brought out most forcefully in the tale of “The Sophisticate and the Simpleton” ( Rabbi Nachman’s Stories #9) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/25"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-25","owner":"sichos-308-position-25","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-25","englishUTF8SHA256":"5f12f26d51e499b868f32b0ca1842b73b9835ba9eba9cdc194e9440df18c329b"}},{"owner":"sichos-308-position-26","section":308,"position":26,"source_index":27,"fields":{"he":"אפלו חכמי המחקרים של אמות העולם מודים לכל זה, שהעולם הזה מלא יסורים תמיד וכמבאר בספריהם הרבה מזה. ואמרו: שאין טוב בעולם הזה כי אם הסבל. דהינו שצריכין בעולם הזה לקבל על עצמו לסבל כל מה שיעבר עליו וכו'.","he_nikud":"אֲפִלּוּ חַכְמֵי הַמְחַקְּרִים שֶׁל אֻמּוֹת הָעוֹלָם מוֹדִים לְכָל זֶה, שֶׁהָעוֹלָם הַזֶּה מָלֵא יִסּוּרִים תָּמִיד וְכַמְבֹאָר בְּסִפְרֵיהֶם הַרְבֵּה מִזֶּה. וְאָמְרוּ: שֶׁאֵין טוֹב בָּעוֹלָם הַזֶּה כִּי אִם הַסֵּבֶל. דְּהַיְנוּ שֶׁצְּרִיכִין בָּעוֹלָם הַזֶּה לְקַבֵּל עַל עַצְמוֹ לִסְבֹּל כָּל מַה שֶּׁיַּעֲבֹר עָלָיו וְכוּ'.","en":"Even the scholars of inquiry among the nations of the world acknowledge all this: that this world is always full of sufferings, as much about this is explained in their books. And they said that there is no good in this world except endurance. That is, in this world one must accept upon oneself to endure everything that happens to one, etc."},"history":{"earlier_supplied_English":"Even pagan philosophers realized that the world is filled with suffering and discussed it often in their works. They came to the conclusion that the only solution is stoic forbearance. That person must accept upon himself to endure all that happens to him ( Alim LeTerufah #441) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/26"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-26","owner":"sichos-308-position-26","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-26","englishUTF8SHA256":"f0b1fe4d8f0fa60ac079641591a44f2b8901f1b3d0fc09bf0e8f0a3adda08a27"}},{"owner":"sichos-308-position-27","section":308,"position":27,"source_index":28,"fields":{"he":"אבל כל דבריהם אינם מועילים להעולם בלא התורה הקדושה שזכינו אנחנו בני ישראל. כי אין אדם זוכה לזה שיקבל על עצמו הסבל בעולם הזה ושלא יטרידוהו צרות העולם הזה כי אם על ידי התורה הקדושה.","he_nikud":"אֲבָל כָּל דִּבְרֵיהֶם אֵינָם מוֹעִילִים לְהָעוֹלָם בְּלֹא הַתּוֹרָה הַקְּדוֹשָׁה שֶׁזָּכִינוּ אֲנַחְנוּ בְּנֵי יִשְׂרָאֵל. כִּי אֵין אָדָם זוֹכֶה לָזֶה שֶׁיְּקַבֵּל עַל עַצְמוֹ הַסֵּבֶל בָּעוֹלָם הַזֶּה וְשֶׁלֹּא יַטְרִידוּהוּ צָרוֹת הָעוֹלָם הַזֶּה כִּי אִם עַל יְדֵי הַתּוֹרָה הַקְּדוֹשָׁה.","en":"But all their words are of no avail to the world without the holy Torah that we, the children of Israel, have merited. For no person merits to accept upon himself endurance in this world and not be disturbed by the troubles of this world except through the holy Torah."},"history":{"earlier_supplied_English":"But all their words are of no avail in a world without the Torah which we Jews have been fortunate to receive. No man can endure this world and not be overcome by its suffering. Only the Torah can provide this strength.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/27"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-27","owner":"sichos-308-position-27","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-27","englishUTF8SHA256":"79a3868cc9432b72ebf8b7365603c09e38d9fa20025674569d2c277b8ce75b9f"}},{"owner":"sichos-308-position-28","section":308,"position":28,"source_index":29,"fields":{"he":"כי כשמישב האדם עצמו היטב האמת לאמתו שהעולם הזה אינו שום תכלית כלל, כי אפלו אם היה עולם הזה מלא טובות ועשירות בלי שום יסורים וצער ודאגות כלל אף על פי כן הוא הבל וריק כי הזמן חולף ועובר כהרף עין (תהלים קמד): \"וימינו כצל עובר\" ולא כצלו של דקל וכו', וכמו שכתוב: \"ימי שנותינו בהם שבעים שנה וכו' ורהבם עמל ואון כי גז חיש ונעופה\".","he_nikud":"כִּי כְּשֶׁמְּיַשֵּׁב הָאָדָם עַצְמוֹ הֵיטֵב הָאֱמֶת לַאֲמִתּוֹ שֶׁהָעוֹלָם הַזֶּה אֵינוֹ שׁוּם תַּכְלִית כְּלָל, כִּי אֲפִלּוּ אִם הָיָה עוֹלָם הַזֶּה מָלֵא טוֹבוֹת וַעֲשִׁירוּת בְּלִי שׁוּם יִסּוּרִים וְצַעַר וּדְאָגוֹת כְּלָל אַף עַל פִּי כֵן הוּא הֶבֶל וָרִיק כִּי הַזְּמַן חוֹלֵף וְעוֹבֵר כְּהֶרֶף עַיִן (תְּהִלִּים קמד): \"וְיָמֵינוּ כְּצֵל עוֹבֵר\" וְלֹא כְצִלּוֹ שֶׁל דֶּקֶל וְכוּ', וּכְמוֹ שֶׁכָּתוּב: \"יְמֵי שְׁנוֹתֵינוּ בָהֶם שִׁבְעִים שָׁנָה וְכוּ' וְרָהְבָּם עָמָל וָאָוֶן כִּי גָז חִישׁ וַנָּעוּפָה\".","en":"For when a person thoroughly settles within himself the truth in its fullness that this world has no purpose whatsoever, [he recognizes that] even if this world were full of good things and wealth without any sufferings or pain or worries at all, nevertheless it would be vanity and emptiness, for time passes and goes in the blink of an eye (Psalms 144): “And our days are like a passing shadow”—and not like the shadow of a palm tree, etc. And as it is written: “The days of our years are seventy years, etc., and their pride is toil and sorrow, for it passes quickly and we fly away.”"},"history":{"earlier_supplied_English":"Imagine a world filled with good and riches. Imagine a world in which there was no pain or suffering or worries. It would still be empty and devoid of all purpose. For time passes like the blink of an eye, and life is over. It is written, “Our days are like a passing shadow” (Psalms 144:4) . Our Sages comment that life is not even permanent, like the shadow of a palm tree (cf. Bereshit Rabbah 96:3; Kohelet Rabbah 1:3) . It is also written, “The days of our years are seventy years … their pride is travail and vanity, for it is speedily gone and flies away” (Psalms 90:10) .","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/28"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-28","owner":"sichos-308-position-28","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-308-position-28","owner":"sichos-308-position-28","placement":"after-owning-paragraph","role":"current-source-qualification","text":"“[He recognizes that]” supplies an explanatory link after the opening “when a person settles the truth within himself”. Those bracketed words are explanatory supply, not a separate predicate in the supplied Hebrew. The supplied Hebrew syntax and abbreviated quotations are preserved."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-28","englishUTF8SHA256":"17ce1bae50ad45459742d63728374e8d82e20db0149ba31710d109e06c73bf6b"}},{"owner":"sichos-308-position-29","section":308,"position":29,"source_index":30,"fields":{"he":"מכל שכן שגם כל העולם הזה מלא צער ויגונות ויסורים ודאגות וטרדות בלי שעור, מגדול ועד קטן, מן גדולי גדולי העשירים המפלגים עד תכלית עני שבעניים, כלם מלאים דאגות, וטרדות הוצאות פרנסתם, ושארי יסורים מיסורים שונים, וצרות והרפתקאות כידוע לכל. ואפלו קיסרים ומלכים ושרים גדולים מלאים דאגות ויסורים ופחדים רבים בלי שעור כידוע למי שבקי בהם ובדרכיהם.","he_nikud":"מִכָּל שֶׁכֵּן שֶׁגַּם כָּל הָעוֹלָם הַזֶּה מָלֵא צַעַר וִיגוֹנוֹת וְיִסּוּרִים וּדְאָגוֹת וּטְרָדוֹת בְּלִי שִׁעוּר, מִגָּדוֹל וְעַד קָטֹן, מִן גְּדוֹלֵי גְדוֹלֵי הָעֲשִׁירִים הַמֻּפְלָגִים עַד תַּכְלִית עָנִי שֶׁבָּעֲנִיִּים, כֻּלָּם מְלֵאִים דְּאָגוֹת, וּטְרָדוֹת הוֹצָאוֹת פַּרְנָסָתָם, וּשְׁאָרֵי יִסּוּרִים מִיִּסּוּרִים שׁוֹנִים, וְצָרוֹת וְהַרְפַּתְקָאוֹת כַּיָּדוּעַ לַכֹּל. וַאֲפִלּוּ קֵיסָרִים וּמְלָכִים וְשָׂרִים גְּדוֹלִים מְלֵאִים דְּאָגוֹת וְיִסּוּרִים וּפְחָדִים רַבִּים בְּלִי שִׁעוּר כַּיָּדוּעַ לְמִי שֶׁבָּקִי בָּהֶם וּבְדַרְכֵיהֶם.","en":"All the more so, since this whole world is also full of pain and sorrows and sufferings and worries and preoccupations without measure, from great to small, from the greatest of the exceedingly wealthy to the poorest of the poor. All are full of worries and preoccupations about the expenses of their livelihood, and other sufferings of various kinds, and troubles and mishaps, as is known to all. And even emperors and kings and great princes are full of worries and sufferings and many fears without measure, as is known to one familiar with them and their ways."},"history":{"earlier_supplied_English":"If even a perfect world would itself be purposeless, what shall we say about the world in which we live? It is filled with pain, sorrow and suffering without end. Every man’s life is filled with worries about finances and concerns, troubles and problems, from the greatest to the smallest, from the richest of the rich to the poorest of the poor. Every man is trapped by his limitations. The greatest emperors and kings are filled with worries and fears without measure, as is understood by those who know about their lives.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/29"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-29","owner":"sichos-308-position-29","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-29","englishUTF8SHA256":"c8332bc484af2d901204adef4806c003b13419709f04f9f8b11b203edc9c80c0"}},{"owner":"sichos-308-position-30","section":308,"position":30,"source_index":31,"fields":{"he":"וכל זה ידוע ומבאר אפלו לחכמי האמות העולם.","he_nikud":"וְכָל זֶה יָדוּעַ וּמְבֹאָר אֲפִלּוּ לְחַכְמֵי הָאֻמּוֹת הָעוֹלָם.","en":"And all this is known and explained even to the wise men of the nations of the world."},"history":{"earlier_supplied_English":"Even the gentile wise men realized this.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/30"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-30","owner":"sichos-308-position-30","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-30","englishUTF8SHA256":"71c8f5107e26fc23dec870e4eb1a1341035c58487d9f72c3f4987828d929fe6a"}},{"owner":"sichos-308-position-31","section":308,"position":31,"source_index":32,"fields":{"he":"ואף על פי כן אין מי שיברח מזה כי אם כשבוחר חלקו בתורה ומצוות הקדושים, ומרצה להסתפק בתכלית המעוט מזה העולם כדי לעסק בתורה ולבלות ימיו על התורה ועל העבודה.","he_nikud":"וְאַף עַל פִּי כֵן אֵין מִי שֶׁיִּבְרַח מִזֶּה כִּי אִם כְּשֶׁבּוֹחֵר חֶלְקוֹ בְּתוֹרָה וּמִצְווֹת הַקְּדוֹשִׁים, וּמְרֻצֶּה לְהִסְתַּפֵּק בְּתַכְלִית הַמִּעוּט מִזֶּה הָעוֹלָם כְּדֵי לַעֲסֹק בַּתּוֹרָה וּלְבַלּוֹת יָמָיו עַל הַתּוֹרָה וְעַל הָעֲבוֹדָה.","en":"And nevertheless no one escapes from this except when he chooses his portion in Torah and the holy commandments, and is willing to be satisfied with the absolute minimum of this world in order to engage in Torah and spend his days on Torah and service."},"history":{"earlier_supplied_English":"The only way out is to choose the Torah and its commandments. Make up your mind to be satisfied with an absolute minimum in order to immerse yourself in the Torah.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/31"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-31","owner":"sichos-308-position-31","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-31","englishUTF8SHA256":"7ad86c5c2fbcdd82912c5ba958ad4699ef6fc7511e3e9851370a456d560f17d7"}},{"owner":"sichos-308-position-32","section":308,"position":32,"source_index":33,"fields":{"he":"אז דיקא יכול לברח מן עמל העולם הזה, לפטר מעליו עמל ויגיעות וטרדות ומרירות נפש של דאגות העולם הזה, ולחיות חיים אמתיים בתורה ועבודת ה', אשר הוא עקר החיים האמתיים בעולם הזה ובעולם הבא.","he_nikud":"אָז דַּיְקָא יָכוֹל לִבְרֹחַ מִן עֲמַל הָעוֹלָם הַזֶּה, לִפְטֹר מֵעָלָיו עָמָל וִיגִיעוֹת וּטְרָדוֹת וּמְרִירוּת נֶפֶשׁ שֶׁל דַּאֲגוֹת הָעוֹלָם הַזֶּה, וְלִחְיוֹת חַיִּים אֲמִתִּיִּים בְּתוֹרָה וַעֲבוֹדַת ה', אֲשֶׁר הוּא עִקַּר הַחַיִּים הָאֲמִתִּיִּים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.","en":"Precisely then he can flee from the toil of this world, to free himself of the toil and labors and preoccupations and bitterness of soul of the worries of this world, and to live true life in Torah and the service of God, which is the essence of true life in this world and in the World to Come."},"history":{"earlier_supplied_English":"Spend your days with Torah and devotion and you will be immune to the world’s travail. You will shake off the toil and struggle of worldly concerns and no longer taste the bitterness and enxiety they have to offer. Devoted to God and His Torah, you will truly be alive, for this is the root of life, both in this world and the next.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/32"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-32","owner":"sichos-308-position-32","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-32","englishUTF8SHA256":"490b0aeec7008860fe29816d18705f36bb484f0eadfb36c378b566e40844e775"}},{"owner":"sichos-308-position-33","section":308,"position":33,"source_index":34,"fields":{"he":"ובודאי צדקו ונאמנו דברי המשנה הקדושה אפלו על פי פשוטה. שמי שבוחר לסבל בעולם הזה לאכל פת במלח ומים במשורה ישתה ועל הארץ יישן וחיי צער יחיה, כי אפלו פת במלח ומים במשורה לאו כל אדם זוכה בהרחבה, ועל כן הוא צריך עם כל זה להיות מרצה לחיות חיי צער, אבל כל זה הוא מקבל על עצמו כדי לעסק בתורה כמו שכתוב שם: 'ובתורה אתה עמל', אז אם עושה כן בודאי אשריך וטוב לך. אשריך בעולם הזה ודאי. כי בודאי יש לו חיות אמתי מאחר שמקבל על עצמו לסבל כל יסורי עולם הזה.","he_nikud":"וּבְוַדַּאי צָדְקוּ וְנֶאֶמְנוּ דִּבְרֵי הַמִּשְׁנָה הַקְּדוֹשָׁה אֲפִלּוּ עַל פִּי פְּשׁוּטָהּ. שֶׁמִּי שֶׁבּוֹחֵר לִסְבֹּל בָּעוֹלָם הַזֶּה לֶאֱכֹל פַּת בַּמֶּלַח וּמַיִם בַּמְּשׂוּרָה יִשְׁתֶּה וְעַל הָאָרֶץ יִישַׁן וְחַיֵּי צַעַר יִחְיֶה, כִּי אֲפִלּוּ פַּת בַּמֶּלַח וּמַיִם בַּמְּשׂוּרָה לָאו כָּל אָדָם זוֹכֶה בְּהַרְחָבָה, וְעַל כֵּן הוּא צָרִיךְ עִם כָּל זֶה לִהְיוֹת מְרֻצֶּה לִחְיוֹת חַיַּי צַעַר, אֲבָל כָּל זֶה הוּא מְקַבֵּל עַל עַצְמוֹ כְּדֵי לַעֲסֹק בַּתּוֹרָה כְּמוֹ שֶׁכָּתוּב שָׁם: 'וּבַתּוֹרָה אַתָּה עָמֵל', אָז אִם עוֹשֶׂה כֵּן בְּוַדַּאי אַשְׁרֶיךָ וְטוֹב לָךְ. אַשְׁרֶיךָ בָּעוֹלָם הַזֶּה וַדַּאי. כִּי בְּוַדַּאי יֵשׁ לוֹ חִיּוּת אֲמִתִּי מֵאַחַר שֶׁמְּקַבֵּל עַל עַצְמוֹ לִסְבֹּל כָּל יִסּוּרֵי עוֹלָם הַזֶּה.","en":"And certainly the words of the holy Mishnah are right and faithful even according to their plain meaning. If one chooses to endure in this world—to eat bread with salt, drink water by measure, sleep on the ground and live a life of privation—for not every person merits to have even bread with salt and water by measure in abundance, and therefore, with all this, he must be willing to live a life of privation—but accepts all this upon himself in order to engage in Torah, as it is written there: ‘and in the Torah you toil’, then, if he does so, certainly: fortunate are you and it is good for you. Fortunate are you in this world—certainly. For certainly he has true vitality, since he accepts upon himself to endure all the sufferings of this world."},"history":{"earlier_supplied_English":"You will then know that the words of the Mishnah are correct, even in their plain meaning. You will have chosen to live such a life, eating bread with salt, drinking water by measure, sleeping on the ground and living a life of privation. You must be willing to accept such a life, for there are times when even bread with salt and water by measure will not be abundant. But accept all this in order to immerse yourself in the Torah – “in the Torah you shall toil.” If you do this, you will certainly be “happy and it shall be good for you … happy in this world.” You will have accepted any suffering from this world and will be worthy of true life.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/33"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-33","owner":"sichos-308-position-33","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-33","englishUTF8SHA256":"26347c07705e406f8a185465cee26b1fffe31bf7c24e114b0ec46bffa6eb69e2"}},{"owner":"sichos-308-position-34","section":308,"position":34,"source_index":35,"fields":{"he":"וזכה להשיג האמת שהעולם הזה לא נברא בשביל נחת להתענג בו. אדרבא מי שרוצה להתענג בזה העולם הוא מלא יסורים וכעס ומכאובות וכנ\"ל. רק הוא בורח מעמל העולם הזה לעמל התורה אשר הוא חיינו וארך ימינו. אז לא די שיזכה לעולם הבא שהוא עולם הנצחי שכל העולם הזה אינו עולה כנגדו אפלו כהרף עין, אף גם בעולם הזה אשרי לו אשרי חלקו.","he_nikud":"וְזָכָה לְהַשִּׂיג הָאֱמֶת שֶׁהָעוֹלָם הַזֶּה לֹא נִבְרָא בִּשְׁבִיל נַחַת לְהִתְעַנֵּג בּוֹ. אַדְּרַבָּא מִי שֶׁרוֹצֶה לְהִתְעַנֵּג בְּזֶה הָעוֹלָם הוּא מָלֵא יִסּוּרִים וְכַעַס וּמַכְאוֹבוֹת וכנ\"ל. רַק הוּא בּוֹרֵחַ מֵעֲמַל הָעוֹלָם הַזֶּה לַעֲמַל הַתּוֹרָה אֲשֶׁר הוּא חַיֵּינוּ וְאֹרֶךְ יָמֵינוּ. אָז לֹא דַּי שֶׁיִּזְכֶּה לָעוֹלָם הַבָּא שֶׁהוּא עוֹלָם הַנִּצְחִי שֶׁכָּל הָעוֹלָם הַזֶּה אֵינוֹ עוֹלֶה כְּנֶגְדּוֹ אֲפִלּוּ כְּהֶרֶף עַיִן, אַף גַּם בָּעוֹלָם הַזֶּה אַשְׁרֵי לוֹ אַשְׁרֵי חֶלְקוֹ.","en":"And he has merited to grasp the truth that this world was not created for ease and enjoyment in it. On the contrary, one who wants to take pleasure in this world is full of sufferings and vexation and pain, as mentioned above. Rather, he flees from the toil of this world to the toil of Torah, which is our life and the length of our days. Then not only will he merit the World to Come, which is the eternal world, against which this whole world does not amount even to the blink of an eye, but also in this world fortunate is he, fortunate is his portion."},"history":{"earlier_supplied_English":"You will then be worthy of perceiving the truth and you will know that the world was not created for ease and enjoyment. You will realize that the man who seeks the delights of this world will find only pain and vexation. The Torah is our life and the length of our days. 378 Prayer before Evening Shma , from Deuteronomy 30:20. If you flee the struggles of the world to toil in the Torah, you will be worthy of the World to Come, whose eternity reduces all of this world to the blink of an eye in comparison. But besides this, you will also have a good life in this world.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/34"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-34","owner":"sichos-308-position-34","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-34","englishUTF8SHA256":"dcfee0eb5cab984241d51ff8ac73d4701ea5eda4ef856996c59392a21bb88e86"}},{"owner":"sichos-308-position-35","section":308,"position":35,"source_index":36,"fields":{"he":"כי בעולם הזה אין טוב כמו הסבל אבל אי אפשר לקבל הסבל של יסורי העולם הזה כי אם כשבורח אל עמל התורה והמצוות הקדושים וכנ\"ל. והדברים מבארים ומובנים מאד למי שחפץ באמת ואינו רוצה להטעות את עצמו.","he_nikud":"כִּי בָּעוֹלָם הַזֶּה אֵין טוֹב כְּמוֹ הַסֵּבֶל אֲבָל אִי אֶפְשָׁר לְקַבֵּל הַסֵּבֶל שֶׁל יִסּוּרֵי הָעוֹלָם הַזֶּה כִּי אִם כְּשֶׁבּוֹרֵחַ אֶל עֲמַל הַתּוֹרָה וְהַמִּצְווֹת הַקְּדוֹשִׁים וְכַּנַּ\"ל. וְהַדְּבָרִים מְבֹאָרִים וּמוּבָנִים מְאֹד לְמִי שֶׁחָפֵץ בָּאֱמֶת וְאֵינוֹ רוֹצֶה לְהַטְעוֹת אֶת עַצְמוֹ.","en":"For in this world there is no good like endurance. But it is impossible to accept endurance of the sufferings of this world except when one flees to the toil of Torah and the holy commandments, as mentioned above. And these matters are explained and very well understood by one who desires the truth and does not want to deceive himself."},"history":{"earlier_supplied_English":"The best way to handle this world is forbearance. This cannot be attained except through immersion in the Torah and its commandments. Open your eyes to the truth and you will see this.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/35"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-35","owner":"sichos-308-position-35","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-35","englishUTF8SHA256":"a8fe9db149cd75567026035739a8f50e9c818b907ebc34472b93dafef8cc6cd2"}},{"owner":"sichos-308-position-36","section":308,"position":36,"source_index":37,"fields":{"he":"כי מי שמתלוצץ מדברים כאלו הוא מתלוצץ רק מעצמו, הינו שאינו רוצה לקבל עצותינו האמתיות ופונה ערפו אליהם. כי הוא רוצה רק לטבע ביון מצולת העולם הזה, ומי ימחה בידו, יאחז כל אחד דרכו (תהלים כ): \"ואנחנו בשם ה' אלקינו נזכיר\".","he_nikud":"כִּי מִי שֶׁמִּתְלוֹצֵץ מִדְּבָרִים כָּאֵלּוּ הוּא מִתְלוֹצֵץ רַק מֵעַצְמוֹ, הַיְנוּ שֶׁאֵינוֹ רוֹצֶה לְקַבֵּל עֲצוֹתֵינוּ הָאֲמִתִּיּוֹת וּפוֹנֶה עָרְפּוֹ אֲלֵיהֶם. כִּי הוּא רוֹצֶה רַק לִטְבֹּעַ בִּיוֵן מְצוּלַת הָעוֹלָם הַזֶּה, וּמִי יִמְחֶה בְּיָדוֹ, יֹאחֵז כָּל אֶחָד דַּרְכּוֹ (תְּהִלִּים כ): \"וַאֲנַחְנוּ בְּשֵׁם ה' אֱלֹקֵינוּ נַזְכִּיר\".","en":"For one who ridicules such matters ridicules only himself; that is, he does not want to accept our true counsel and turns his back on it. For he wants only to sink in the mire of the depths of this world, and who can prevent him? Let each person hold to his own path. (Psalms 20): “And we will invoke the name of the Lord our God.”"},"history":{"earlier_supplied_English":"Ridicule these words and you only ridicule yourself. We speak the truth and it is yours to accept. But if you wish to turn your back on it and remain immersed in the deep quicksand (Psalms 69:3) of this world, there is no one to prevent you. “Let each man go his own way, but we will call out in God’s name.”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/36"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-36","owner":"sichos-308-position-36","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-36","englishUTF8SHA256":"9320760c97bdc008814f409e698a2f8988cea59170e652e4ca655e0f263dd79a"}},{"owner":"sichos-308-position-37","section":308,"position":37,"source_index":38,"fields":{"he":"וכמו שאמר רבנו ז\"ל, על אחד שדבר עמו הרבה, וכונת רבנו ז\"ל, היה להוציאו ממקומות שנטבע בהם במים שאין להם סוף.","he_nikud":"וּכְמוֹ שֶׁאָמַר רַבֵּנוּ ז\"ל, עַל אֶחָד שֶׁדִּבֵּר עִמּוֹ הַרְבֵּה, וְכַוָּנַת רַבֵּנוּ ז\"ל, הָיָה לְהוֹצִיאוֹ מִמְּקוֹמוֹת שֶׁנִּטְבַּע בָּהֶם בְּמַיִם שֶׁאֵין לָהֶם סוֹף.","en":"And as our Rebbe, of blessed memory, said regarding a certain man, with whom there had been much conversation: our Rebbe, of blessed memory, intended to bring him out of the places in which he had sunk, in waters without end."},"history":{"earlier_supplied_English":"These were the Rebbe’s words to a man who spoke to him at length. The Rebbe knew that this man was drowning in the endless waters ( Yebamot 121a) and wanted to rescue him.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/37"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-37","owner":"sichos-308-position-37","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-308-position-37","owner":"sichos-308-position-37","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The Hebrew does not explicitly identify which participant spoke at length. The English leaves that speaker unstated; it does not adopt either earlier English account to decide the speaker or identify which preceding words are meant."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-37","englishUTF8SHA256":"f1ec8b971925e6cabef0d49926948d1da65478c09ccf569b1c81f0d189ddce48"}},{"owner":"sichos-308-position-38","section":308,"position":38,"source_index":39,"fields":{"he":"אבל אותו האיש נתן כתף סוררת וחזק את לבו ולא קבל דברי רבנו ז\"ל, בלבו אף על פי שגם הוא הבין שדברי רבנו ז\"ל, אמתיים ונפלאים, אבל לא רצה לקבלם.","he_nikud":"אֲבָל אוֹתוֹ הָאִישׁ נָתַן כָּתֵף סוֹרֶרֶת וְחִזֵּק אֶת לִבּוֹ וְלֹא קִבֵּל דִּבְרֵי רַבֵּנוּ ז\"ל, בְּלִבּוֹ אַף עַל פִּי שֶׁגַּם הוּא הֵבִין שֶׁדִּבְרֵי רַבֵּנוּ ז\"ל, אֲמִתִּיִּים וְנִפְלָאִים, אֲבָל לֹא רָצָה לְקַבְּלָם.","en":"But that man gave a rebellious shoulder and hardened his heart, and did not accept the words of our Rebbe, of blessed memory, into his heart, even though he too understood that the words of our Rebbe, of blessed memory, were true and wondrous. But he did not want to accept them."},"history":{"earlier_supplied_English":"But the man hardened his heart and turned a stubborn shoulder (Zechariah 7:11; Nehemiah 9:29) , not accepting the Rebbe’s advice. He knew the Rebbe spoke the truth, but refused to take his words to heart.","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/38"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-38","owner":"sichos-308-position-38","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-38","englishUTF8SHA256":"74afe811a30e7f8d015e2e0187187e0559d923a857fa08b05f70887ca7f94365"}},{"owner":"sichos-308-position-39","section":308,"position":39,"source_index":40,"fields":{"he":"ענה ואמר רבנו ז\"ל: זה האיש דומה כמו מי שנטבע במים והולך לאבוד, ובא אחד ופושט ידו ורוצה להוציאו משם, והוא נותן כתף סוררת ופונה ערפו בעזות ואינו רוצה להניח את עצמו לתפס בו להוציאו, ובורח מן הבא להצילו.","he_nikud":"עָנָה וְאָמַר רַבֵּנוּ ז\"ל: זֶה הָאִישׁ דּוֹמֶה כְּמוֹ מִי שֶׁנִּטְבָּע בַּמַּיִם וְהוֹלֵךְ לְאִבּוּד, וּבָא אֶחָד וּפוֹשֵׁט יָדוֹ וְרוֹצֶה לְהוֹצִיאוֹ מִשָּׁם, וְהוּא נוֹתֵן כָּתֵף סוֹרֶרֶת וּפוֹנֶה עָרְפּוֹ בְּעַזּוּת וְאֵינוֹ רוֹצֶה לְהַנִּיחַ אֶת עַצְמוֹ לִתְפֹּס בּוֹ לְהוֹצִיאוֹ, וּבוֹרֵחַ מִן הַבָּא לְהַצִּילוֹ.","en":"Our Rebbe, of blessed memory, answered and said: “This man is like someone who is drowning in water and is going to perish. Someone comes and extends his hand and wants to take him out of there, but he gives a rebellious shoulder and turns his back brazenly, and does not want to allow himself to be grasped to be taken out, and flees from the one who comes to save him.”"},"history":{"earlier_supplied_English":"The Rebbe said, “He is like a drowning man who is about to die. A rescuer comes along and extends a hand to lift him from the water. But the drowning man turns a stubborn shoulder and turns his back in arrogance, not wanting to grasp the helping hand. He flees from the one who comes to save him.”","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/39"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-39","owner":"sichos-308-position-39","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-39","englishUTF8SHA256":"6ef55bfce89a320ff5864f5baaed5932b4468c3421ae2ee98fa339a651238d0f"}},{"owner":"sichos-308-position-40","section":308,"position":40,"source_index":41,"fields":{"he":"ולהשומע ינעם בעולם הזה ובעולם הבא:","he_nikud":"וּלְהַשּׁוֹמֵעַ יֻנְעַם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא:","en":"And for the one who heeds, may it be pleasant in this world and in the World to Come:"},"history":{"earlier_supplied_English":"Heed these words! You will find pleasure both in this world and the next. Finished and completed is the book of Rebbe Nachman's Wisdom with the help of the Blessed God","original_source_url":"/reader/reviewed/sichos-301308-sources/sicha-308-original.json","original_owner_pointer":"/segments/40"},"required_qualifications":[{"id":"author301-origin-sichos-308-position-40","owner":"sichos-308-position-40","placement":"after-owning-paragraph","role":"current-origin","text":"Editorial translation from the supplied Hebrew."},{"id":"author301-source-note-1-sichos-308-position-40","owner":"sichos-308-position-40","placement":"after-owning-paragraph","role":"current-source-qualification","text":"The earlier English includes a book-completion statement that is absent from both supplied Hebrew fields of this paragraph. It is preserved in full under the earlier English. Its original placement and ownership have not been established."}],"currentOrigin":{"kind":"editorial_translation_from_supplied_hebrew","noticeID":"author301-origin-sichos-308-position-40","englishUTF8SHA256":"f7100f4a84ff904f2e5e104dd6e47aae2aad7c6226414704b8e3bd1c7b552a33"}}]};
